window.__D("text/likkutei-sichot/c155",{"p":[[1300241069,"ובמילא איז מובן אז די שלימות הכניסה לא\"י, עס איז דא בעלות בשלימות און ראוי לבעלות פון יעדער אידן אויף גאנץ א\"י⁵², איז נתגלה געווארן⁵³ ווען „הותרו שבטים לבוא זה בזה\"⁵⁴.\nה. אע\"פ אז „חמשה דברים אירעו את אבותינו . . בתשעה באב\"⁵⁵ און דער ערשטער ענין איז וואס „בתשעה באב נגזרו על אבותינו שלא יכנסו לארץ\", איז אבער דער (עיקר) גזירת התענית בתשעה באב מצד דעם חורבן הבית וואס אירע בו⁵⁶.\nאון דעריבער נעמט און די גמרא אז דער טעם העיקרי אויף „לא היו ימים טובים לישראל כט\"ו באב\" איז ווייל דאס איז דער „יום שפסקו מלכרות עצים למערכה\", און ענין וואס איז שייך צום בנין וקיום הבית⁵⁷ — דער היפך פון חורבן הבית⁵⁸.\nאין חורבן הבית זיינען דא צווי ענינים: דער חורבן הבית, אז ס'איז ניטא קיין ביהמ\"ק ובמילא אויך ניט דער סדר העבודות שבו; סיבת החורבן — וואס בבית שני (וואס איז „חמיר לן\"⁵⁹ פונעם חורבן הראשון) איז די סיבה געווען „מפני שהיתה בו שנאת חנם\"⁶⁰.\nאון דער היפך פון די צוויי ענינים⁶¹ האט זיך אויפגעטאן בחמשה עשר באב לויטן טעם⁶² „יום שפסקו מלכרות עצים למערכה\".",[["52","52","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151103\" data-slug=\"likkutei-sichot\" data-id=\"1300151103\">לקו\"ש שם ס\"ע 103</a> ואילך. וש\"נ."],["53","53","אף שעצם הענין גם דמתנה ניתן כבר בימי אברהם. ואכ\"מ."],["54","54","את\"ל שזהו כענין הב' דבצפע\"נ תרומות שם יומתק ביותר מה דהיו\"ט בט\"ו באב מצד זה דהותרו השבטים לבוא זה בזה, הוא בניגוד כו' לת\"ב, כי ענין זה „דשייכא למין ישראל\" לא פקע לעולם גם אחר ת\"ב וחורבן הבית. וכמו דהענין דהותרו השבטים כפשוטו והיתר הסבת נחלה נמשך לאחר החורבן."],["55","55","משנה תענית כו, א."],["56","56","מאירי למשנה שם. וראה תודה\"ה הואיל (ר\"ה יח, ריש ע\"ב)."],["57","57","להעיר מחדא\"ג במשנה תענית שם ד\"ה וכה\"א „ולפי ענינו נראה דאט\"ו באב קאי שטעמי שמחתו אמרינן בגמרא תלוים בבנין המקדש\". וראה אוצר בלום לע\"י שם."],["58","58","ובפרט שיו\"ט (גדול) בזמן בית שני הי' לאחרי (ובמילא לא תיקן) חורבן בית הא'. ולהעיר מהשקו\"ט ומחלוקת אם התענו בת\"ב בימי בית שני (הובא ונסמן ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151429\" data-slug=\"likkutei-sichot\" data-id=\"1300151429\">לקו\"ש חט\"ו ע' 416</a> הערה 43). וראה תו\"ח ב\"ב שם (תחלת לשונו נעתקה לעיל הערה 32): ועוד דרב מנשה (מנשיא) לאחר החורבן הוה . . ואמאי הוו קרי לי' בזמנו יום תבר מגל אי לאו כו'. ולהעיר מטעם דרב מתנה „יום שניתנו הרוגי ביתר לקבורה\" שהי' לאחרי חורבן הבית (ראה גבורת ארי תענית שם), ובצפע\"נ שהובא בסוף הערה 42 ממשיך: וא\"ש מה דאמר שם טעם דנעשה לאחר חורבן ולא אמרינן כמו הך דר\"ה דף י\"ט קמייתא בטל כו' ועי' תוס' עירובין ד' מא ע\"א גבי קרבן עצים ותענית ד' יב ובפסקי תוס' שם משמע דלא בטלה ועש\"ה בתוס'."],["59","59","שו\"ע או\"ח סתקמ\"ט ס\"ב. וראה הערה 39 והערה שלפנ\"ז."],["60","60","יומא ט, ב."],["61","61","ולהטעם „יום שהותר שבט בנימין לבוא בקהל\" מודגש רק הפרט הב' — ענין האחדות. ולהעיר דביהמ\"ק (והמזבח) הוא בחלקו של בנימין דוקא (זבחים קיח, ב. ושי\"נ)."],["62","62","ועד\"ז הוא בהטעם ד„יום שביטל הושע בן אלה פרוסדיות שהושיב ירבעם בן נבט על הדרכים שלא יעלו ישראל לרגל ואמר לאיזה שירצו יעלו\": גם בזה מודגש ב' הפרטים: א) ענין האחדות היפך סיבת החורבן, כי (נוסף ע\"י שאז יוכלו כל ישראל להתאחד גם עם אלה שהוכרחו לילך לפני העגלים אשר עשה ירבעם (מ\"א יב, ל), הרי) העלי' לרגל היא ש„חוגגין אליו שלש פעמים בשנה\" (רמב\"ם הל' ריש הל' בית הבחירה\") שהוא ענין של התאחדות דכל ישראל**. ב) הענין דעלי' לרגל „חוגגין אליו שלש *) ועד\"ז כתב בסהמ\"צ מ\"ע כ: ואליו תהי' ההליכה והעלי' לרגל והקיבוץ בכל שנה. ושם שורש יב כתב: והוא שיהי' לנו בית מוכן יבאו אליו ויחוגו בו ובו תהי' ההקרבה ובו יהי' הקבוץ במועדים. וראה הלשון בהוצאות הר\"ח העליר והר\"י קאפח. **) ראה חגיגה כו, א (ופי' ר\"ח שם). ירושלמי הנ\"ל (הערה 46). גליוני הש\"ס חגיגה שם."]]],[1300241070,"ו. וועט מען דאס פארשטיין בהקדים נאך א דיוק אין דעם ענין: צוליב וואס דארף דא די גמרא ברענגען די ראי' „דתניא ר\"א הגדול אומר מחמשה עשר באב ואילך תשש כחה של חמה ולא היו כורתין עצים למערכה\" — למאי נפק\"מ⁶³ בנדו\"ד די סיבה פונעם הפסק כריתת עצים? ובפרט אז דאס מאכט נאך שווערער צו פארשטיין די סיבה פון דער שמחה פון דעם וואס פסקו מלכרות עצים, וויבאלד ס'איז דאך קיין ברירה ניט געווען, וכנ\"ל.\nדער הסבר בזה און היא הנותנת: די כריתת עצים למערכה האט אויפגעטאן אז במשך כל השנה זאל מען קענען מקריב זיין אויפן מזבח אלע סוגי קרבנות — סיי די קרבנות יחיד, וואס יעדער איינער בפרט דארף ברענגען לחובתו אדער לנדרו אדער בנדבה, סיי די קרבנות צבור פון כלל ישראל וואס יעדער איד האט אין זיי א חלק⁶⁴ (און עס טוט זיך אויף אויך כפרת היחיד לויט די סוגי קרבנות צבור⁶⁵).\nד.ה. אז די פעולה פון כריתת עצים איז בתוכנה וענינה די מצוה פון צדקה, וועלכע איז „שקולה כנגד כל המצות ובכל תלמוד ירושלמי היא נק' בשם מצוה סתם⁶⁶, ובפרט ווען מ'איז דאס מקיים באופן הכי נעלה⁶⁷, וואס דאן איז עס (נאכמער —) א מצוה גדולה —\nוצדקה — בענין הקרבנות\nדי גדלות פון דער צדקה איז סיי בכמות — אז זי ווערט געטאן מיט יעדער יחיד און מיטן גאנצן כלל ישראל, און צו דערמעגלעכן די הקרבת קרבנות היחיד והציבור. און סיי גדלות באיכות, אן אנדער סוג צדקה — ווען ניט די כריתת עצים ביז ט\"ו באב, איז נאכדעם ניטא נאך עצים הראויים למערכה —\nדערמיט איז מובן די הסברה פון ר' אליעזר הגדול: „מחמשה עשר באב ואילך תשש כחה של חמה\" איז ניטא קיין עצים ראויים למערכה, וואס דערמיט איז מוסבר די פעולה גדולה פון כריתת עצים וואס ווערט נשלם ביז ט\"ו באב⁶⁸.\nאון במילא איז אויך מובן, אז דערמיט ווערט דערגרייכט די שלימות פון (בנין ה)בית המקדש: בנין ביהמ\"ק איז אז עס זאל זיין „בית לה' מוכן להיות מקריבים בו הקרבנות\"⁶⁹ — און דאס ווערט ערמעגליכט ונשלם דוקא בחמשה עשר באב, וואס דעמאלט ענדיקט מען דעם שנידן די עצים למערכה, און דורכדעם ווערט דאס א „בית לה' מוכן להיות מקריבים בו הקרבנות\", ס'איז דא (אויך) די עצים פאר הקרבת הקרבנות ביז צו חודש ניסן שלאח\"ז⁷⁰.",[["","","פעמים בשנה\" הוא חלק וגדר המצוה — המכוון דה„מצות עשה לעשות בית לה'\" (כברמב\"ם שם) — בנין ביהמ\"ק. וראה לקמן הערה 70."],["63","63","ראה לעיל הערה 5, 8 הגירסא באיכ\"ר."],["64","64","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171027\" data-slug=\"likkutei-sichot\" data-id=\"1300171027\">לקו\"ש חי\"ז ע' 27</a> הערה 47. וש\"נ."],["65","65","ראה ריש מס' שבועות במשנה. במדב\"ר פכ\"א, כא. וש\"נ."],["66","66","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>). ושם „מפני שהיא עיקר המצות מעשיות ועולה על כולנה\"."],["67","67","גם כפשוטו אלו שכרתו עצים למערכה והביאו ללשכה הרי\"ז בדוגמת א' ממעלות הכי גדולות בצדקה „ולא ידע למי נתן ולא ידע העני ממי לקח כו' כגון לשכת חשאים שהיתה במקדש כו'\" (רמב\"ם הל' מת\"ע פ\"י ה\"ח)."],["68","68","ראה גם לקו\"ש חי\"ד (ע' 1104 ואילך), <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091088\" data-slug=\"likkutei-sichot\" data-id=\"1300091088\">ח\"ט (ע' 88</a> ואילך), לענין נדבת עצים בט\"ו באב, כ\"ף בו וכו' שבמשנה תענית שם."],["69","69","רמב\"ם ריש הל' בית הבחירה."],["70","70","ואף שגם בהטעם ש„יום שביטל כו' שלא יעלו ישראל לרגל\" מודגשים ב' הענינים (כנ\"ל הערה 62), מ\"מ בהטעם ד„יום שפסקו מלכרות עצים"]]],[1300241071,"ז. אויף דעם איז מוסיף רב מנשיא „וקרו לי' יום תבר מגל\", אז מיטן הפסק כריתת עצים טוט זיך אויף נאך א טיפערער ענין אין שלימות פון בנין הבית (ניט נאר וואס דורך דער „מצוה גדולה\" ווערט „בית לה' מוכן להיות מקריבים בו הקרבנות\"):\nדי משנה⁷¹ זאגט וועגן דעם איסור פון נגיעת ברזל באבני המזבח (וואס דער אבן ווערט פסול, מ'קען (מיט עם) ניט בויען א מזבח) „שהברזל נברא לקצר ימיו של אדם והמזבח נברא להאריך ימיו של אדם\".\nאון דאס איז רב מנשיא אויסן צו מוסיף זיין (לפי' רש\"י ורשב\"ם) מיטן ענין פון „תבר מגל\" — „שבירת הגרזן (של ברזל)\": דער עילוי פון ט\"ו באב, ווען „פסקו לכרות עצים למערכה\", באשטייט ניט נאר אינעם אויפטאן (בפשטות) א הכשר מצוה (וואס דערפאר האט מען דעם מגל ניט גענוצט אויף א תשמיש חול און ער איז „בטל\"), און אפילו ניט בלויז אין דעם וואס (בתוכנה) איז דאס א מצוה גדולה פון צדקה און ס'ווערט דורכדעם א „בית לה' מוכן להיות מקריבים בו הקרבנות\" — נאר נאכמער: עס איז אויך געווען דער תכלית המכוון פון בנין הבית (והמזבח והקרבת הקרבנות)⁷² — דאס וואס דער מזבח איז „נברא להאריך ימיו של אדם\" ע\"י הקרבת הקרבנות עליו האט זיך אויפגעטאן און אויסגעדריקט אין דעם טאג ובגמר כריתת עצים (נאך איידער מ'האט געבראכט די עצים במקדש על המערכה — די אלע טעג ביז ניסן) אין דעם „תבר מגל\" — „נשברו הקרדומות\", ד. ה. שוין דעמאלט (בט\"ו באב) איז מען פועל, מען צעברעכט (און מבטל) דעם ענין הפכי פון מזבח (והקרבת הקרבנות), ברזל וואס איז „נברא לקצר ימיו של אדם\"⁷³.\nאון דערפאר האט מען דעם קרדום של ברזל צעבראכן⁷⁴, כפשוטו: היות אז פון דעמאלט אן איז ער מער ניט מסייע אין דער כריתת עצים למערכה למזבח און עס בלייבט אין אים בלויז דער ענין הפכי (וואס נברא) לקצר ימיו של אדם — דעריבער איז מן הראוי אז מ'זאל דאס (מבטל זיין) צעברעכן⁷⁵.",[["","","למערכה\" מודגש א) ענין האחדות — היפך דשנאת חנם ביותר, כנ\"ל בפנים. ב) גם ענין הבנין דבנין הבית מודגש יותר, כי: 1) כריתת והכנת עצים למערכה הוא מעשה בפועל וחלק מהמערכה והקרבת הקרבנות. 2) ענין הא' שבהמ\"ק הוא „לעשות בית לה' מוכן להיות מקריבים בו הקרבנות\", ואח\"כ ממשיך „וחוגגין אליו שלש פעמים בשנה\". ועוד ועיקר, גם השלימות דחוגגין שצ\"ל עולת ראי' — ולא יראו פני ריקם** — בא ע\"י כריתת עצים למערכה כו'."],["71","71","מדות פ\"ג מ\"ד. מכילתא ופרש\"י יתרו כ, כב. וראה חינוך מצוה מ. *) משא\"כ יום שביטל . . שלא יעלו ישראל לרגל: א) שלא הי' בזה פעולה (ושייכות לבנין הבית). ב) אמר לאיזה שירצו יעלו\", וגלו ישראל בימיו „על ידי ששמט את הקולר מצוארו ותלוי בצואר הרבים לא אמר כל עמא יסקון אלא מאן דבעי מיסוק יסוק\" (ירושלמי תענית שם, איכ\"ר שם). **) והבא ולא הביא עולה לא דין שלא עשה מ\"ע אלא עובר על ל\"ת שנאמר ולא יראו פני ריקם (רמב\"ם הל' חגיגה בתחלתו)."],["72","72","להעיר מדעת ר\"א (שבת קל, א) ד„כורתין עצים (בשבת) לעשות פחמין לעשות ברזל\" בשביל איזמל למילה. ולהעיר מהמבואר במ\"א (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171187\" data-slug=\"likkutei-sichot\" data-id=\"1300171187\">לקו\"ש חי\"ז ע' 187</a> ואילך. ובכ\"מ) בגדרי הכשר מצוה ופעולה המוכרחת למצוה וכיו\"ב שנעשה מעין החשיבות וגדר המצוה."],["73","73","עפ\"ז יומתק יותר ההמשך בגמ' „מכאן ואילך דמוסיף (יוסיף חיים על חייו) דלא יוסף כו'\"."],["74","74","וצ\"ע לשון הרשב\"ם „שנשברו הקרדומות\", כאילו נשברו מעצמם. משא\"כ בלשון רש\"י תענית „שבירת הגרזן\"."],["75","75","ובמילא אין בזה משום בל תשחית, שהוא רק „כשעושה דרך השחתה וקלקול\" (שו\"ע אדה\"ז חלק חו\"מ הל' שמירת גו\"נ ובל תשחית סט\"ו)."]]],[1300241072,"ח. ע\"פ הנ\"ל אז דער תוכן פונעם יו\"ט חמשה עשר באב איז דער ענין האחדות⁷⁶ צווישן אידן — דער היפך (תיקון וביטול) פון שנאת חנם, וואס איז געווען די סיבת החורבן — איז מובן וואס דער יו\"ט ושמחה פון ט\"ו באב איז באשטאנען אין דעם וואס „בנות ירושלים יוצאות וחולות בכרמים⁷⁷, אז ניט קוקנדיק אויף די פארשידענע חילוקים צווישן זיי — יפיפיות, מיוחסות, מכוערות, ווי די ברייתא⁷⁸ רעכנט אויס ווייטער — גייען זיי אלע אין איינעם מחול, בשלום ואחדות.\nאון נאכמער: זיי זיינען דאן געווען אנגעטאן „בכלי לבן שאולין שלא לבייש⁷⁷ את מי שאין לו\" — ווי די גמרא⁷⁸ איז ממשיך ומפרט דעם סדר: בת מלך שואלת מבת כהן גדול בת כה\"ג מבת סגן כו' — וואס די הנהגה ברענגט ארויס נאך מער און שטארקער די שלימות פון דעם שלום ואחדות ביז אז די וואס געהערט צום חשוב'ערן סוג איז „שואלת\" — בעט, לייט, און איז זיך מכניע ומקבל פון דער וואס באלאנגט צו א סוג יותר נמוך וכו',\nאון אין דעם זעלבן ענין איז אויך דער סיום המסכת: עתיד הקב\"ה לעשות מחול לצדיקים והוא יושב ביניהם בגן עדן וכל אחד ואחד מראה באצבעו שנאמר⁷⁹ ואמר ביום ההוא גו' — דעמאלט וועט זיין די שלימות האחדות וההתכללות פון אלע אידן (ועמך כולם צדיקים) צוזאמען, כמשנ\"ת בארוכה במ\"א⁸⁰.\nאון „ביום ההוא\" פון לעת\"ל וועט זיין דער „תבר מגל\", בכל העולם כולו „וכתתו חרבותם לאתים גו' לא ישא גוי אל גוי חרב\"⁸¹, און עס וועט מקוים ווערן בשלימות דער ענין פון „להאריך ימיו של אדם\"⁸² — אתם קרויין אדם⁸³ — אריכות ימים ושנים אין דעם זמן פון תחיית המתים⁸⁴ לעת\"ל⁸⁵, ביי „כל ישראל\" וואס „יש להם חלק לעוה\"ב⁸⁶ שנאמר⁸⁷ ועמך כולם צדיקים\", אזוי אז אלע אידן וועלן זיך באטייליקן אין דעם „מחול לצדיקים\" וואס „עתיד הקב\"ה לעשות\",\nבמהרה בימינו ממש.\n(משיחות ט\"ו וכ' מנ\"א תשל\"ט)",[["76","76","וכמודגש גם ב„זמן עצי הכהנים והעם (שמתנדבים עצים . . והיו מקריבים קרבן אותו היום — רש\"י שם) כו' בחמשה עשר בו (באב) בני זתוא בן יהודה ועמהם כהנים ולוים וכל מי שטעה בשבטו ובני גונבי עלי ובני קוצעי קציעות\" (משנה תענית כו, א)."],["77","77","במשנה שם ע\"ב."],["78","78","לא, א."],["79","79","ישעי' כה, ט."],["80","80","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191086\" data-slug=\"likkutei-sichot\" data-id=\"1300191086\">לקו\"ש חי\"ט ע' 86</a> ואילך."],["81","81","ישעי' ב, ד."],["82","82","להעיר מהסיום בתנחומא יתרו בסופו."],["83","83","יבמות סא, רע\"א."],["84","84","ועפ\"ז יש לקשר הסיום לתחלת המס' „מזכירין גבורת גשמים בתחיית המתים\", ד„מתוך שהיא שקולה כתחיית המתים קבעוה בתחיית המתים\" (תענית ז, רע\"א). ובירושלמי תענית בתחלתו: כשם שתחיית המתים חיים לעולם כך ירידת גשמים חיים לעולם. ולהעיר מדב\"ר פ' תבוא (פ\"ז, ז) דביום ירידת גשמים כולם שמחים (וד\"ה במד\"ר פ' תבוא — ש\"ת תרכ\"ח סוס המאמרים תרכ\"ז). וראה ריטב\"א בתחלת המס'. טור או\"ח סי' קיד. ושו\"ע אדה\"ז שם."],["85","85","כי אף שנאמר „והוא יושב ביניהם בגן עדן\", הרי מפשטות הלשון „עתיד הקב\"ה לעשות מחול\" וכן מהכתוב שהביא „ואמר ביום ההוא\" (ראה שמו\"ר ספכ\"ג) אולי יש לומר שהמדובר לעת\"ל בעוה\"ב, אחר התחי' שגם אז יהי' מקום דג\"ע בעולם. וראה לקו\"ת ואתחנן ז, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151143\" data-slug=\"likkutei-sichot\" data-id=\"1300151143\">לקו\"ש חט\"ו ע' 143</a> הערה 44. לקמן ע' 66 הערה 76."],["86","86","סנהדרין ר\"פ חלק."],["87","87","ישעי' ס, כא."]]],[1300241073,"<h3>חמשה עשר באב ב'*</h3>\nא. די משנה זאגט בסיום מס' תענית¹: „לא היו ימים טובים לישראל כחמשה עשר באב² וכיוה\"כ שבהן כו' ובנות ירושלים (ויש גורסים³: ובנות ישראל) יוצאות וחולות בכרמים ומה היו אומרות בחור שא נא עיניך וראה מה אתה בורר לך אל תתן עיניך בנוי תן עיניך במשפחה שקר⁴ החן והבל היופי אשה יראת ה' היא תתהלל⁵ ואומר⁶ תנו לה מפרי ידי' ויהללו בשערים מעשי' וכן הוא אומר⁷ צאינה וראינה בנות ציון במלך שלמה בעטרה שעטרה לו אמו ביום חתונתו וביום שמחת לבו ביום חתונתו זה מתן תורה (יום הכפורים שניתנו בו לוחות האחרונות, רש\"י⁸) וביום שמחת לבו זה בנין בית המקדש (שנתחנך ביום הכפורים, רש\"י לרי\"ף שם⁹. רע\"ב¹⁰) שיבנה במהרה בימינו\".\nבגמרא¹¹ (אויף דער משנה) ברענגט מען א ברייתא, אז אין די „בנות ירושלים\" (ישראל) זיינען געווען כמה סוגים („משפחות\"): „יפיפיות שבהן מה היו אומרות תנו עיניכם ליופי שאין האשה אלא ליופי, מיוחסות שבהן מה היו אומרות תנו עיניכם למשפחה לפי שאין האשה אלא לבנים מכוערות שבהם מה היו אומרות קחו מקחכם לשום שמים כו'\".\nלויט דער גירסא אין עין יעקב¹² קומט צו א פערטער סוג¹³ (קודם דעם פאל פון „מכוערות\") „עשירות שבהן אומרות תנו עיניכם בבעלי ממון\".\nאויך אין ירושלמי¹⁴ איז ער מפרט סוגים אין „בנות ירושלים\", אבער מיט א שינוי: אנשטאט צו רעכענען דריי (אדער פיר) סוגים, רעכנט ער נאר צוויי",[["","","*) וסיום מס' תענית (דירושלמי ובבלי)."],["1","1","כו, ב."],["2","2","ויש לומר השייכות לסיום המס' — כי סיום מס' תענית הוא בענין של „סיום\" (וביטול) של ענין התענית [ולהעיר שגם סיום הל' תעניות להרמב\"ם הוא בענין של ביטול (והפיכת*) הצומות לעת\"ל לששון ולשמחה ולמועדים טובים]. והסיום הוא בענין היו\"ט דט\"ו באב, שענינו — ה(הפיכה ל)יו\"ט באותו החודש של התענית דתשעה באב ועוד יותר מיו\"ט דחהמ\"ס וחה\"ס, עלי' ביותר לאחרי ירידה ביותר (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650097\" data-slug=\"or-hatorah-hb\" data-id=\"8316650097\">אוה\"ת נ\"ך (ח\"ב) איכה ע' אצו</a>. וד\"ה נחמו עת\"ר בארוכה ועוד)."],["3","3","ראה שינויי נוסחאות למשניות, וש\"נ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191080\" data-slug=\"likkutei-sichot\" data-id=\"1300191080\">לקו\"ש חי\"ט</a> ט\"ו באב (וסיום מס' תענית) ע' 80 הערה 2."],["4","4","הפסוקים שקר החן גו' תנו לה גו' לא הובאו במשנה בירושלמי (ועוד — ראה שינויי נוסחאות למשניות ודק\"ס). וראה לקמן הערה 30."],["5","5","משלי לא, ל."],["6","6","שם, לא."],["7","7","שה\"ש ג, יא."],["8","8","ע\"פ גמרא שם ל, ב. *) ראה בארוכה לקו\"ש חט\"ו ע' 413 ואילך."],["9","9","ולולא דמסתפינא הייתי אומר שכצ\"ל גם בפרש\"י שבש\"ס — ועפ\"ז בטלה התמי' גדולה שאין רש\"י מפרש זה בש\"ס."],["10","10","וראה חדא\"ג מהרש\"א ותוי\"ט שם."],["11","11","לא, א."],["12","12","ומסתבר לומר, שבענין של אגדתא יש להעדיף גירסת העי'. כי נוסף על השייכים ללימוד כל הגמרא — נתוספו גם לומדי האגדה, ומכיון שרוב לומדי האגדה הוא בעין יעקב (כמנהג ישראל), הנוסחאות שבו מבוררות יותר, ע\"ד מ\"ש הרשב\"א (שו\"ת המיוחסות להרמב\"ן סי' צו) בנוגע לרבוי השבושים בנוסחאות הירושלמי מפני „מעוט השגחת הלומדים בו\"."],["13","13","וכמו שמקדים (בעי' שם): ארבע משפחות היו בא\"י."],["14","14","בסיום מס' תענית."]]],[1300241074,"סוגים — „הכאורות (כמו כעורות¹⁵, קרבן העדה) היו אומרות אל תתן עיניך בנוי והנאות היו אומרות תן עיניך במשפחה\".\nדארף מען פארשטיין: עס איז ידוע דער כלל¹⁶ אז ס'איז ניט שייך קיין פלוגתא אין א מציאות. איז דערפון פארשטאנדיק, אז לכולי עלמא זיינען צווישן די בנות ירושלים (היוצאות ואומרות כו') געווען (ניט נאר יפיפיות (נאות) און מכוערות, נאר) אויך מיוחסות (און עשירות) — איז פארוואס ווערן זיי ניט גערעכנט אין ירושלמי?\nאויך דארף מען פארשטיין דעם שינוי הלשון: אין בבלי נוצט ער דעם לשון יפיפיות (יופי)¹⁷, און אין ירושלמי — נאות?\nב. אין ירושלמי גופא, זיינען ניט פארשטאנדיק כמה פרטים ומהם:\nא) דאס וואס די כאורות האבן געזאגט — „אל תתן עיניך בנוי\", איז דאך בלויז א דיבור של שלילה, וואס מען זאל ניט קלייבן. כדי אבער אז דער „בחור\" זאל וועלן אויסקלייבן די „כאורה\" האט זי דאך לכאורה געדארפט ריידן א דיבור חיובי וואס ער זאל יע קלייבן (ע\"ד ווי די נאות זאגן „תן עיניך במשפחה\"); און ווי מען זעט טאקע אז אין בבלי שטייט אז זיי האבן געזאגט „קחו מקחכם לשום שמים\" (צוליב אירע מעשים טובים¹⁸) און דא זאגט זי נאר „אל תתן כו'\" — א שלילה?\nדי תמי' איז נאך גרעסער: וואס פאר אן ארט האט עס אז די „כאורות\" זאלן מכריז זיין „אל תתן עיניך בנוי\", דאס איז דאך מדגיש אז ביי זיי איז ניטא קיין נוי¹⁹!\nב) וואס איז דער קשר צווישן „נאות\" און „תן עיניך במשפחה\": דער ענין פון „משפחה\" איז דאך א מעלה פון יחוס (ווי עס שטייט טאקע אין בבלי, אז דאס פלעגן זאגן די „מיוחסות\") — וואס פאר א שייכות האט עס אבער מיט די „נאות\"?¹⁹\nמפרשים²⁰ זיינען דאס מבאר, אז וויבאלד „בנות ישראל (מצד עצמן) נאות הן אלא שהעניות מנוולתן²¹, הרי היפות מסתמא בנות עשירים הן\". אבער דער פירוש איז צע\"ג: פארוואס דארף א נאה זאגן „תן עיניך במשפחה\" כדי ברענגען א ראי' אז זי איז פון די נאות? — זי דארף גלייך זאגן „תן עיניך ביופי\".\nג) אין ירושלמי איז ער מקדים דעם סוג פון „כאורות\" פאר די „נאות\",",[["15","15","הרמז שבירושלמי נכתב באל\"ף, יש לומר, שהוא ע\"ד מחז\"ל (ב\"ר פ\"כ, יב. ועוד) שבתורתו של ר' מאיר — (שענינו אור, כמחז\"ל (עירובין יג, ב מאיר עיני חכמים) — מצאו כתוב כתנות אור (באל\"ף)*, והרי תלמוד ירושלמי הוא בחי' אור לגבי תלמוד בבלי (במחשכים הושיבני — סנה' כד, א). וראה ס' רמזי דחכמתא (ורשה, תרצב, וז\"ע מחדש — ע' 96)."],["16","16","ראה שד\"ח כרך ג תקמה, ד ואילך."],["17","17","וכן ב(פסוק שהובא ב)משנה בבבלי: הבל היופי. וראה לקמן הערה 31."],["18","18","ראה אלי' רבה לשו\"ע או\"ח סתק\"פ ס\"י (נעתק בענף יוסף לע\"י תענית שם). קרבן העדה לירושלמי שם."],["19","19","ביפ\"מ (הובא גם בשירי קרבן) לירושלמי גריס „והנאות היו אומרות תן עיניך ביופי והמיוחסות היו אומרות תן עיניך במשפחה\". אבל ראה שירי קרבן שם ד„דוחק להגי' כך\"."],["20","20","קרבן העדה שם."],["21","21","נדרים סו, א (במשנה). *) ראה תו\"ש לבראשית פ\"א אות תקיז. פ\"ג אות קעח. וש\"נ. ועוד. וראה ע\"ד החסידות — או\"ת להה\"מ ס\"פ בראשית. מאמרי אדה\"ז פרשיות ח\"א ע' נ ואילך. דרמ\"צ ח, א. ועוד."]]],[1300241075,"לכאורה האט געדארפט שטיין כסדר חשיבותן ומעלתן (ע\"ד ווי אין בבלי, וואס די אמירה פון די „מכוערות\" ווערט גערעכנט לבסוף)?\nג. נאכן אויסרעכענען די צוויי סוגים הנ\"ל, איז דער ירושלמי ממשיך (און איז דערמיט מסיים די מסכת): וכן הוא אומר צאינה וראינה בנות ציון במלך שלמה בעטרה שעטרה לו אמו ביום חתונתו זו מתן תורה וביום שמחת לבו זה בנין בית המקדש שיבנה במהרה בימינו אמן.\nוואס אין דעם איז ניט פארשטאנדיק:\nא) די ראי' פון פסוק „צאינה וראינה גו'\" ווערט שוין געבראכט אין דער משנה — וואס איז די גמרא מחדש אויף המפורש במשנה?\nנאך מער: אין דער משנה, קומט דער פסוק „צאינה וראינה בנות ציון\" אלס ראי' אויף דעם אז ביום הכפורים (יום חתונתו ויום שמחת לבו) פלעגט זיין „בנות ירושלים יוצאות וחולות\"²²; אבער וואס פאר א שייכות האט דער פסוק צו דעם סיום אין גמרא — וואו עס רעדט זיך (ניט וועגן דער „יציאה\" אדער זמן היציאה, נאר) בלויז וועגן זייער אמירה („מה היו אומרות\")?\nב) לויט נוסחת הירושלמי, ווערט אין דער משנה ניט געבראכט דער פסוק בשלימותו — די ווערטער „בעטרה שעטרה לו אמו\" ווערן ניט נעתק (זיי ווערן נאר נרמז מיט „וגומר\")²³; משא\"כ אין גמרא (ירושלמי) ווערן אויך די ווערטער נעתק.\nג) נאך די ווערטער „שיבנה במהרה בימינו\" איז די גמרא מוסיף „אמן\", וואס אין דער משנה (אין נוסח הירושלמי²⁴) שטייט דאס ניט. ומאי טעמא?\nד. וי\"ל דעם ביאור בכל זה — ובהקדם:\nמ'וואלט געקענט זוכן א סברא אויף יעדן שינוי (ושאלה) בפ\"ע, ס'איז אבער מסתבר צו זאגן אז עס איז פאראן איין סברא כללית (אדער צוויי) וואס איז מסביר אלע שינויים (ושאלות).\nובנדו\"ד יש לומר, אז דאס איז פארבונדן מיט א חילוק כללי צווישן תלמוד בבלי און תלמוד ירושלמי, וואס איז (ווי גערעדט שוין פיל מאל²⁵) — אז אין תלמוד ירושלמי ריידן זיך די ענינים בקיצור ובכללות, משא\"כ אין בבלי ווערן זיי נתבאר בפרטיות יותר ובאריכות.\nאון דער טעם אויף דעם בפשטות איז, ווייל לימוד הגמרא שבבבל האט זיך געצויגן א לענגערע צייט נאך חתימת תלמוד ירושלמי [ווארום דער חיבור וחתימה פון תלמוד בבלי איז געווען „אחר שחיבר ר' יוחנן הגמרא ירושלמית בכמו מאה שנה\"²⁶]. ד.ה. אז תלמוד בבלי איז „בתראי\" לגבי תלמוד ירושלמי²⁷, און „בתראי\" זיינען זיך עוסק (אויך) אין דברי הקדמאי ובמילא —",[["22","22","ראה ר\"ן (הובא בתוי\"ט) תענית שם. פני משה (לירושלמי). ועוד."],["23","23","הטעם בפשטות י\"ל, כי תיבות אלו אינן חלק מהראי' (מפסוק זה) שבנות ירושלים יוצאות וחולות ביוהכ\"פ וכו'. אבל עפ\"ז — גם בגמרא אצ\"ל. — וראה לקמן הערה 30."],["24","24","להעיר אשר בדפוסי משניות שלפנינו איתא תיבת „אמן\". וכ\"ה ברי\"ף. ועוד."],["25","25","ראה לקמן ע' 168 (וש\"נ). ועוד."],["26","26","ל' הרמב\"ם בהקדמתו לספר היד."],["27","27","ראה רי\"ף סוף עירובין (ועוד) שזהו מהטעמים שהלכה כבבלי."]]],[1300241076,"מער מפרט ומפרש ווי די פריערדיקע²⁸.\nוע\"ד ווי דער אונטערשייד פון לשון המשנה (וואס איז א „דיבור קצר וכולל ענינים רבים\"²⁹), לגבי לשון הגמרא — איז א שפעטערדיקן זמן³⁰.\nאון דאס איז אויך די נקודת החילוק — צווישן דעם תלמוד בבלי וירושלמי — בנדו\"ד:\nאין דער משנה (וואס איז א „דיבור קצר\", כנ\"ל) שטייט נאר דער כלל אז „בנות ירושלים . . היו אומרות . . אל תתן עיניך בנוי תן עיניך במשפחה\" — אן פרטים; די פרטים בזה — קומען ערשט אין דער גמרא, וואו ס'זיינען מפורט די סוגים פון „בנות ירושלים\".\nאון אין דעם איז אויך דער חילוק צווישן בבלי און ירושלמי: אין ירושלמי, ריידן זיך די ענינים מער בכללות, טיילט מען די בנות אין צוויי סוגים (כלליים); אבער אין בבלי איז מען מפרט די צוויי סוגים מער בפרטיות, קומט ארויס (דריי) פיר סוגים.\nדערמיט איז אויך מבואר דער שינוי הלשון צווישן בבלי און ירושלמי: אין בבלי שטייט דער לשון „יפיפיות . . ליופי\", משא\"כ אין ירושלמי איז דער לשון „נאות\" — וואס דער חילוק ביניהם איז: ווען מען זאגט דעם תואר „יופי\", מיינט עס בפשטות³¹ — יופי הגוף אדער הפנים; משא\"כ „נוי\" — איז א תואר כללי וואס קען זיך באציען אויף אלערליי מעלות, און סיי גשמיות'דיקע און סיי רוחניות'דיקע.\nאון דאס איז דער חילוק צווישן ירושלמי און בבלי: דער ירושלמי טיילט די בנות ירושלים אין צוויי סוגים כלליים — די וועלכע זיינען בעלות מעלה — „נאות\", און „כאורות\"; משא\"כ אין בבלי, איז ער מחלק דעם סוג פון „נאות\" גופא אין דריי פרטים: „נאות\" מצד יופי הגוף והפנים — „יפיפיות\"; „נאות\" מצד יחוס — „מיוחסות\"; און (לויט גירסת העי') — „נאות\" מצד דעם וואס זיי זיינען „עשירות\", וי\"ל אז אין דעם איז די מעלה ניט אזוי די „עשירות\" מצ\"ע, נאר אז ביי זיי איז ניטא דער „עניותן מנוולתן\", ואדרבה — ס'איז ביי זיי דא די „דירה נאה וכלים נאים\" וואס „מרחיבין דעתו של אדם\"³².\nה. ע\"פ הנ\"ל, ווערט אבער נאך שטארקער די שאלה (הנ\"ל ס\"ב) אויפן ירושלמי: אין הכי נמי אז „נאות\" איז כולל אויך יחוס — עס איז דאך אבער כולל (ובעיקר) „יפיפיות\" און אויך „עשירות\", איז ווי פאסט זאגן בא זיי „תן עיניך במשפחה\"?",[["28","28","ראה ספרי הכללים (יד מלאכי כללי הרמב\"ם אות כד. ועוד) — ע\"פ ב\"י לטיו\"ד סר\"א ד\"ה ומ\"ש ואף אם תסבול."],["29","29","הרמב\"ם בהקדמתו לפיה\"מ ד\"ה אח\"כ ראה להסתפק."],["30","30","וי\"ל שזהו גם הטעם ל(כמה מה)שינויים שמצינו בנוסח ל' המשנה בין הבבלי לירושלמי (ולהעיר מב\"ק ו, ב: האי תנא ירושלמי הוא דתנא לישנא קלילא), וכמו בנדו\"ד: במשנה שבבבלי הובאו הפסוקים שקר החן גו' תנו לה גו', משא\"כ בירושלמי: בבבלי נעתק כל הכתוב „צאינה וראינה גו'\", משא\"כ במשנה שבירושלמי (כנ\"ל סעיף ג) — כי בבבלי מפרט יותר מבירושלמי."],["31","31","אף שאפ\"ל גם בנוגע לרוחניות — ראה לקו\"ש חי\"ט <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191083\" data-slug=\"likkutei-sichot\" data-id=\"1300191083\">שם ע' 83</a>. ועפ\"ז יומתק מה שהביא במשנה בבבלי „הבל היופי\"."],["32","32","ברכות נז, ב. *) אף שהמשנה אחת היא שנתחברה ע\"י רבינו הקדוש קודם לגמרא — אפ\"ל שינוי גירסאות בין מדינחאי ומערבאי. ובמכש\"כ מתנ\"ך."]]],[1300241077,"והביאור בזה: די אלע סוגי מעלה הנ\"ל, זיינען ניט ענינים וואס די בנות ירושלים האבן אליין „אויסגעהארעוועט\" און דערגרייכט, נאר וואס זיי באקומען פון זייערע עלטערן און משפחה:\n„מיוחסות\" איז דאך בפשטות אן ענין הבא בירושה; „עשירות\" — א בת ואשה כשרה (בנות ישראל ועאכו\"כ בנות ירושלים — יראה שלם³³), פירט זיך דאך אין אן אופן פון „כל כבודה בת מלך פנימה\"³⁴ (און ניט אז זי גייט ארויס אליין פארדינען געלט — ובפרט פאר דער חתונה³⁵), און איר עשירות איז וואס זי האט פון משפחתה; און אזוי אויך יופי — איז דאך ניט תלוי אין איר, נאר אין אירע עלטערן³⁶ [נוסף לזה, וואס כדי צו שולל זיין דעם „עניותן מנוולתן\" (כנ\"ל ס\"ד) איז דאס דורך דער עשירות פון די עלטערן].\nעפ\"ז קומט אויס, אז עס איז דא א חילוק עקרי אין דעם תוכן האמירה של ה„נאות\" — צווישן בבלי און ירושלמי:\nלויטן בבלי קומט אויס, אז יעדער סוג האט ארויסגעבראכט זיין מעלה — „תנו עיניכם ליופי . . תנו עיניכם למשפחה . . (און לגירסת העי') תנו עיניכם בבעלי ממון\": מען זאל קוקן אויף די מעלות וואס זי פארמאגט [ווארום אויך די וואס זאגט „תנו עיניכם למשפחה\", איז זי דאך ניט אויסן די מעלה פון דער משפחה אין אלגעמיין, נאר דאס וואס זי, אלס א טייל פון דער משפחה — פארמאגט די מעלה פון יחוס];\nמשא\"כ אין ירושלמי, איז דער תוכן האמירה פון די „נאות\", אז מען זאל קוקן אויף די סיבת המעלות — אז זיי זיינען ניט ענינים וואס זי האט אויפגעטאן (בכח עצמה), נאר זיי אלע שטאמען פון איר משפחה.\nאון אויך דער חילוק צווישן בבלי און ירושלמי, איז פארבונדן מיט דעם חילוק הנ\"ל (ס\"ד) צווישן אופן לימוד הבבלי ואופן לימוד הירושלמי³⁷, כדלקמן.\nו. דער חילוק אין אונזער סוגיא צווישן בבלי און ירושלמי, איז ניט נאר וואס דער בבלי איז מער מפרט ווי דער ירושלמי, נאר עס איז א חילוק עיקרי אין דעם אופן פירוט דברי המשנה:\nלויטן ירושלמי, איז אין גמרא ניטא קיין נייע אמירה לגבי דער אמירה וואס שטייט אין משנה. דער ירושלמי איז בלויז מפרט, אז דאס וואס שטייט אין דער משנה, אז די בנות ירושלים פלעגן זאגן „אל תתן עיניך בנוי תן עיניך במשפחה\", זיינען דאס צוויי באזונדערע אמירות פון צוויי סוגי משפחות — „הכאורות היו אומרות אל תתן עיניך בנוי והנאות היו אומרות תן עיניך במשפחה\":\n[און דערמיט איז פארענטפערט בפשטות וואס דער ירושלמי איז מקדים",[["33","33","ראה תוד\"ה הר — תענית טז, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380960\" data-slug=\"likkutei-torah\" data-id=\"4001380960\">לקו\"ת ר\"ה ס, ב</a>."],["34","34","תהלים מה, יד."],["35","35","ולהעיר ממש\"נ (משלי לא, יא-יב): אשת חיל גו' בטח בה לב בעלה גו'."],["36","36","ראה עדיות פ\"ב מ\"ט. מס' כלה פ\"א. נדרים כ, א."],["37","37","ויש לומר שזהו בהתאם להחילוק בין תלמוד בבלי לתלמוד ירושלמי ע\"ד הקבלה: ירושלמי ענינו חכמה, אור; ובבלי — בינה, כלים (ראה סה\"מ תש\"ח ס\"ע 121. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161372\" data-slug=\"likkutei-sichot\" data-id=\"1300161372\">לקו\"ש חט\"ז ע' 359</a>. וש\"נ). ולכן: בירושלמי, אור (שענינו ביטול) נרגש הסיבה והמקור של המעלות (וראה בארוכה לקמן סעיף ז-ח); ובבבלי, כלים („מציאות\") — איך שהמעלות הן בבנות ירושלים גופא. והירושלמי אור ישר, והבבלי אר\"ח (שערי אורה ד\"ה בכ\"ה בכסלו פנ\"ד ואילך. סה\"מ תש\"ח ע' 124 ואילך)."]]],[1300241078,"די „כאורות\" צו די „נאות\" — ווייל דאס איז בהתאם צו סדרם במשנה: פריער די אמירה „אל תתן עיניך בנוי\" און דערנאך „תן עיניך במשפחה\"].\nמשא\"כ דער בבלי, איז מוסיף נייע (פרטי) אמירות וואס ווערן ניט דערמאנט (בפירוש³⁸) אין משנה.\nאין אנדערע ווערטער: די משנה דערציילט וועגן דער אמירה כללית, וואס אלע בנות ירושלים פלעגן זאגן³⁸ — „בחור שא נא עיניך וראה מה אתה בורר לך כו'\";\nדערנאך קומט די גמרא אין ירושלמי און איז מפרט, אז אע\"פ אז די ווערטער „בחור שא נא עיניך וראה מה אתה בורר לך\" האבן געזאגט אלע בנות ירושלים³⁹, אבער די ווייטערדיקע (שבמשנה) — „אל תתן עיניך בנוי תן עיניך במשפחה\", זיינען צוויי באזונדערע אמירות: די „כאורות\" היו אומרות אל תתן עיניך בנוי, און די „נאות\" — אלע סוגי בעלות מעלה — היו אומרות תן עיניך במשפחה.\nאון אויף דעם איז די גמרא אין בבלי מוסיף, אז אויסער די אמירה כללית (וואס שטייט אין משנה)⁴⁰ — האט יעדער סוג פרטי פון בנות ירושלים דערנאך מוסיף געווען נאך אן אמירה (פרטית), בהתאם צו די מעלה פרטית שבסוג זה⁴¹.\nז. ע\"פ הנ\"ל — אז אין ירושלמי איז די אמירה פון די „נאות\" („תן עיניך במשפחה\") די זעלבע אמירה וואס שטייט אין משנה — איז פארענטפערט וואס דער ירושלמי זאגט, אז די נאות פלעגן זאגן (ניט „תן עיניך\" אין זייערע (פרטיות'דיקע) מעלות, נאר) „תן עיניך במשפחה\". וההסברה בזה:\nדער מכוון פון דער אמירה — ווי עס שטייט אין דער משנה — איז צו מדגיש זיין, אז די בנות ירושלים דערהערן ווי אלע מעלות וואס זיי פארמאגן, איז דאס ניט זייערע מעלות — ניט אז „כחי ועוצם ידי עשה לי את החיל הזה\"⁴² — נאר דאס איז זיי געגעבן געווארן.\n— וע\"ד המוסר והחסידות: „בנות ירושלים\" ווייסן, אז כדי א שידוך זאל מצליח זיין, מוז דער בחור טראכטן ניט (אזוי) וועגן די מעלות — רוחניות'דיקע אדער גשמיות'דיקע — וואס ער זעט און וואס געפעלן אים, נאר מהוי' אשה משכלת⁴³, מתפלל און מכוון זיין אויף אויסקלייבן דעם ריכטיקן שידוך — וואס איז אויסגערופן געווארן במרום, „בת פלוני לפלוני\"⁴⁴.\nוואס דערפאר זיינען אלע בנות ירושלים מקדים „בחור שא נא עיניך וראה מה אתה בורר לך\", וואס דער דיוק בזה איז⁴⁵: מען דארף קוקן אויף",[["38","38","באליהו רבה (שבהערה 18) שג' אמירות נאמרו (נרמזו) במשנה. אבל ראה בארוכה לקו\"ש חי\"ט <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191081\" data-slug=\"likkutei-sichot\" data-id=\"1300191081\">שם (ע' 81</a>) שמסתימת לשון המשנה משמע שהנאמר במשנה נאמר ע\"י כל בנות ירושלים, עיי\"ש."],["39","39","באיר שם שרק ה„יפיפיות\" אמרו זה. אבל ראה הערה שלפנ\"ז."],["40","40","ועפ\"ז, גם להבבלי, הכוונה במשנה היא כמו הביאור בירושלמי. — ועפ\"ז יומתק שינוי הלשון בבבלי: במשנה אומר „אל תתן עיניך בנוי\", ובגמרא משנה ל„יפיפיות . . ליופי\" — כי במשנה היא אמירה כללית דכל בנות ירושלים, (שיש להן מעלות), ובגמרא הכוונה ליפיפיות כפשוטן (ע\"ד הנ\"ל סעיף ד בהחילוק בין הבבלי וירושלמי)."],["41","41","ראה גם לקו\"ש חי\"ט <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191083\" data-slug=\"likkutei-sichot\" data-id=\"1300191083\">שם ע' 83</a> ואילך (ושם נת' באופן אחר קצת)."],["42","42","פרשתנו ח, יז. וראה סמ\"ג מל\"ת סד."],["43","43","משלי יט, יד."],["44","44","סוטה ב, א. וש\"נ."],["45","45","ראה גם לקו\"ש חי\"ט <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191084\" data-slug=\"likkutei-sichot\" data-id=\"1300191084\">שם ע' 84</a>."]]],[1300241079,"מעלות האשה (הן רוחניות'דיקע והן גשמיות'דיקע) — ניט ווי מען זעט זיי מיט די אויגן ווי זיי זיינען דא למטה, נאר פריער דארף זיין „שא⁴⁶ נא עיניך (און דערנאך) וראה כו'\" (עדמש\"נ⁴⁷ „שאו מרום עיניכם — וועט זיין — וראו מי ברא אלה\") — קוקן אויף דעם מקור⁴⁸ פון וואנעט עס שטאמען און קומען אראפ די מעלות;\nובמילא וועט זיין — „אל תתן עיניך בנוי תן עיניך במשפחה\", ווארום די מעלות קומען דאך פון „משפחה\" (כנ\"ל סעיף ה).\nאון דעמאלט וועט ער זוכה זיין צו מכוון זיין צו דעם שידוך וועלכן מ'האט מכריז געווען במרום, וואס מ'איז מכריז „בת פלוני לפלוני\" (און ניט „פלונית לפלוני\"), דער עיקר הדגשה איז (ניט אין דער כלה, נאר) אין משפחת — אב⁴⁹ הכלה.\nח. ע\"פ הנ\"ל איז אויך פארשטאנדיק מאמר הירושלמי, אז די „כאורות\" פלעגן זאגן „אל תתן עיניך בנוי\" — וואס איז אן ענין שלילי (כנ\"ל סעיף ב) — ווייל אלע בנות ירושלים, כולל די „כאורות\", האבן פריער געזאגט „שא נא עיניך וראה מה אתה בורר לך\",\nאויך די „כאורות\" זאגן דאס, וואו־ארום אע\"פ אז קיין מעלות גלויות האבן זיי ניט — דארף מען דאך אבער קוקן פון וואנען זיי שטאמען, אז יעדערע פון זיי איז א בת שרה רבקה רחל ולאה.\nויתירה מזו יש לומר — און אדרבה: אין דעם ענין, וואס די בנות ירושלים זיינען מדגיש אז עס דארף זיין „שא נא עיניך\", צו זען דעם העכער, איז פאראן א מעלה אין די „כאורות\" לגבי די נאות⁵⁰.\nדער ביאור בזה:\nמפרשים⁵¹ זיינען מבאר, אז דאס וואס די „מכוערות\" זאגן (ווי עס שטייט אין בבלי) „קחו מקחכם לשום שמים\" איז ווייל זיי האבן יראת ה' (ווי דער פסוק וואס ברענגט זיך אין משנה לנוסחת הבבלי — „אשה יראת ה' היא תתהלל\"). אבער אעפ\"כ רופט זיי און די גמרא „מכוערות\" וואס עס איז היפך מעלה?!\nויש לומר הפירוש בזה:\nביי „מכוערות\", וואס האבן ניט קיינע מעלות (יופי, יחוס, אדער עשירות, וועלכע קומען) פון זייער משפחה כנ\"ל — איז זייער יראת ה' מצד עצמן, זייענדיק אן אידיש קינד איז „רוצה הוא לעשות כל המצות ולהתרחק מן העבירות\"⁵² — זיי דערהערן אז זייער יראת ה' (היא תתהלל) איז מצד זייער חלק אלקה ממעל ממש⁵³, הוא הנותן לך כח לעשות חיל, אבער לולא זאת זיינען זיי „מכוערות\"⁵⁴ — ע\"ד ווי די לבנה (וואס",[["46","46","אף שבכלל חתן — „נחית דרגא\" (יבמות סג, א)."],["47","47","ישעי' מ, כו."],["48","48","עפ\"ז מתורץ ג\"כ מה שבנות ירושלים יוצאות כו' גם ביוהכ\"פ (יום הקדוש) ואומרים „תנו עיניכם כו'\" (ומ\"ש בתפאר' שביוהכ\"פ התכוונו רק להקב\"ה (ולא לשידוכים) — אינו מתאים לפשטות ל' המשנה, פרש\"י ור\"ן בריף ועוד). — כי כ\"ז הי' בדוקא ובהקדמת „שא נא עיניך כו'\"."],["49","49","להעיר ממחז\"ל (ברכות ס, א. וש\"נ) אב מזריע תחלה יולדת נקבה."],["50","50","ועפ\"ז יומתק מה שהירושלמי מקדים אמירת ה„כאורות\" ל„נאות\" [משא\"כ להביאור דלעיל (סעיף ו) — שהוא לפי סדרם במשנה — עדיין קשה בהמשנה גופא, דהול\"ל „תן עיניך במשפחה ואל תתן עיניך בנוי\"]."],["51","51","נסמן לעיל הערה 18."],["52","52","רמב\"ם הל' גירושין ספ\"ב."],["53","53","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["54","54","ע\"ד תפלת דוד בכו\"כ כתובים שתתקבל תפלתו „כי עני ואביון אני\", „עני ואביון אנכי\" (תהלים פו, א. קט, כב) ועוד."]]],[1300241080,"אידן זיינען מונין ללבנה און דומין ללבנה⁵⁵) איז „לית לה מגרמה כלום\"⁵⁶ — דעם אור וואס זי איז מאיר איז ניט איר אור, נאר (דאס וואס זי האט) פון דעם אור השמש (און דורכדעם ווערט זי א מאור — הקטן (בערך השמש) און אויך הגדול (בערך הכוכבים)).\nאון דאס איז דער חילוק צווישן די צוויי סוגים „כאורות\" און „נאות\":\nדי „נאות\" זיינען די וואס פילן זייערע מעלות, נאר אזוי ווי זיי זיינען בנות ירושלים און צנועות — אנערקענען זיי אז די מעלות האבן זיי באקומען פון זייערע משפחות — „תן עיניך במשפחה\". אבער אעפ\"כ, איז דאס וואס „תן עיניך במשפחה\" ניט שולל ביי איר דעם הרגש אז זי איז א בעלת מעלה — זי איז דאך א טייל פון דער משפחה.\nמשא\"כ די „כאורות\" פילן ווי „לית לה מגרמה כלום\" — אלץ קומט פון אויבערשטן⁵⁷. און דעריבער, אויך ווען זיי האבן מעלות (און אפילו ווען זיי האבן מעלות פון יופי, יחוס און עשירות) זיינען דאס ניט זייערע מעלות. און דערפאר זיינען זיי ניט מייחס זייערע מעלות צו „משפחה\" (וואס גיט אן ארט אויף דעם הרגש אז זי איז א בעלת מעלות, כנ\"ל) — זיי זאגן נאר „שא נא עיניך\" אז מען זאל זען דעם שורש ומקור הכל (— דעם אויבערשטן), און „אל תתן עיניך בנוי\" — שע\"פ הנ\"ל איז דער פירוש בזה⁵⁸ — אפילו עס איז דא „נוי\"⁵⁹ איז „אל תתן עיניך\" בטפל ומטה נאר שא עיניך וראה.\nט. ע\"פ הנ\"ל וועט מען אויך פארשטיין פארוואס דער ירושלמי איז דערנאך ממשיך ומסיים מיט ברענגען נאכאמאל דעם פסוק „וכן הוא אומר צאינה וראינה גו'\" — ווייל די כוונה אין גמרא (בירושלמי⁶⁰) איז צו ברענגען א ראי' אויף די צוויי סוגים (שבגמרא) — „כאורות\" און „נאות\"⁶¹.\nאון דערפאר איז דער ירושלמי דא מוסיף על המשנה און מעתיק די ווערטער „בעטרה שעטרה לו אמו\" (וועלכע שטייען ניט אין משנה) —\nדער ביאור בזה:\nדער פסוק „צאינה וראינה גו'\" זאגט צוויי מעלות בקשר צו שלמה: (א) „בעטרה שעטרה לו אמו\", (ב) „ביום חתונתו וביום שמחת לבו\" „זה בנין ביהמ\"ק\", וואס שלמה האט געבויט.\nדער חילוק צווישן די צוויי מעלות איז:\n„עטרה\" — כתר מלכות — איז א מעלה אין דעם מלך⁶². וכמאמר חז\"ל⁶³",[["55","55","ראה סוכה כט, א. אוה\"ת בראשית ד, סע\"ב ואילך."],["56","56","ראה זח\"א רנס, ב. ח\"ב רטו, א. ועוד."],["57","57","כמחז\"ל (ויק\"ר פכ\"ז, ב) עה\"פ (איוב מא, ג) מי הקדימני ואשלם."],["58","58","שעפ\"ז מובנת בפשטות אמירת המכוערות: אל תתן עיניך בנוי, ואצ\"ל שהכוונה לנוי שבאחרות."],["59","59","ולהעיר: „יראת\" (השייך למכוערות, כנ\"ל בפנים) — ר\"ת יונתי רעיתי אחותי תמתי (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381272\" data-slug=\"likkutei-torah\" data-id=\"4001381272\">לקו\"ת שה\"ש לה, ד</a> סד\"ה תמתי) — כל ד' הסוגים — מלכות, כנסת ישראל הכונסת וכוללת כל הספירות."],["60","60","משא\"כ בבבלי שהובאו ג' (ד') סוגים אין מקום להביא סיום זה."],["61","61","עפ\"ז מובן מדוע הובא פסוק זה (במשנה) — גם בנוגע לט\"ו באב (אף שיום חתונתו ויום שמחת לבו קאי (רק) על יום כיפור. וראה הנסמן בהערה 10)."],["62","62","ועד שבזה תלוי ענין המלכות (ראה מגילת אסתר (ו, י): קח את הלבוש גו', ואת הכתר לא הזכיר (רש\"י שם)). וראה שערי אורה ד\"ה יביאו לבוש מלכות פ\"ז-ח בארוכה."],["63","63","ע\"ז מד, סע\"א."]]],[1300241081,"אז אן עדות אויף א ראוי למלכות בית דוד איז ווען עטרת דוד „הולמתו\"; דערביי איז דער פסוק אבער מדגיש אז דאס איז „עטרה שעטרה לו אמו\" — עס קומט פון „אמו\"⁶⁴.\n— בדוגמת די „נאות\" וואס זאגן „תן עיניך במשפחה\": זיי זיינען בעלות מעלות, אבער די סיבה פון די מעלות איז משפחה (אמו) — „תן עיניך במשפחה\". —\nמשא\"כ בנין בית המקדש, האט דאס שלמה⁶⁵ געבויט⁶⁵*, אבער לאידך — איז דאס „הכל בכתב מיד ה'\"⁶⁶, דאס איז „בית ה'\"⁶⁷, וכתפלת שלמה⁶⁷*: שמך נקרא על הבית הזה אשר בניתי.\n— בדוגמת די „כאורות\", זיי זיינען „אשה יראת ה' היא תתהלל\", אבער דאס גופא פילט זי אז „לית לה מגרמה כלום\", אלץ איז דעם אויבערשטנס⁶⁸.\nי\"ד. און דאס איז אויך דער טעם וואס דער ירושלמי איז מוסיף בסיום הענין דעם ווארט „אמן\" — „שיבנה במהרה בימינו אמן\" — ווייל די שייכות פון „זה בנין בית המקדש\" צו די „כאורות\" דריקט זיך אויס מיט מער הדגשה אין דעם ענין פון „אמן\":\n„אמן\" איז מלשון אמת⁶⁹, וואס דערפאר אז מען ענטפערט אמן אויף א תפלה און בקשה דארף מען מכווין זיין „שכך יתאמת לעינינו\"⁷⁰. וואס אמת איז שולל שינוי, באווייזט אויף נצחיות⁷¹.\nדי הוספה „(שיבנה במהרה בימינו) אמן\" איז מוסיף און זאגט אז דער „שיבנה במהרה בימינו\", ביהמ\"ק השלישי, וועט זיין א בנין נצחי.\nדער טעם וואס דער ביהמ\"ק השלישי וועט זיין א בית נצחי, איז עס דערפאר וואס „מקדש אד-ני כוננו ידיך\"⁷² — דאס איז „בנינא דקוב\"ה\"⁷³.\nאון דאס זאגט דער ירושלמי, אז די מעלה פון „בנין בית המקדש\" וואס איז בית ה' (בדוגמת די מעלה פון די „כאורות\", וואס דערהערן אז אלץ קומט פון דעם וואס „ברא אלה\") — וועט זיין בגילוי אין דעם ביהמ\"ק השלישי, וואס וועט זיין א בנין נצחי — „שיבנה במהרה בימינו אמן\".\nיא. ויש לומר, אז אויך דער סיום הגמרא אין בבלי — וואס איז דער מאמר „עתיד הקב\"ה לעשות מחול לצדיקים כו'\" — איז פארבונדן",[["64","64","ולהעיר שעל מלכות שלמה ביקשה אמו (ראה מ\"א א, יז. וראה שם, יג וברד\"ק שם)."],["65","65","משא\"כ דוד רק עשה את ההכנות להבנין, אבל לא את הבנין גופא. *65) והזדרז בזה יותר מבנין ביתו (מ\"א ו, לח ושם ז, א ובפרש\"י ממדרז\"ל — שהש\"ר פ\"א, א (ה). וש\"נ)."],["66","66","דה\"א כט, יט."],["67","67","לשון הכתוב — דה\"ב ג, א. שם ח, א. וראה מלכים א ו, א-ב ועוד (משא\"כ „ביתו\" — מ\"א ז, א. דה\"ב ח שם). *67) מ\"א ח, מג. דה\"ב ו, לג."],["68","68","וי\"ל שגם במשנה עצמה נרמזים ב' הסוגים — בב' הענינים: „יום חתונתו זה מ\"ת\" — תורה ענינה „דברי כאש\" (ראה ברכות כב, א) — הבא מלמעלה (בדוגמת „תן עיניך במשפחה\"): ו„יום שמחת לבו זה בנין ביהמ\"ק\" — בדוגמת ה„כאורות\" (כנ\"ל בפנים)."],["69","69","ראה שבועות לו, א וברש\"י ד\"ה בו שם. וראה בפרטיות אנציקלופדי' תלמודית ערך „אמן\". וש\"נ."],["70","70","בית לטור או\"ח סקכ\"ד ד\"ה ויענו. וראה ט\"ז (סק\"ג) מג\"א (סק\"י) ושו\"ע אדה\"ז שם (סעיף ט)."],["71","71","ראה פרה פ\"ח מ\"ט. ולהעיר מסוף נזיר דעניית אמן היא בדוגמת „גבורים נוצחין\"."],["72","72","בשלח טו, יז. רש\"י עה\"פ."],["73","73","זח\"ג רכא, א. זח\"א כח, א."]]],[1300241082,"[ניט נאר מיטן פרט שבהמשנה, „בנות ירושלים יוצאות וחולות\", אזוי אויך „עתיד הקב\"ה לעשות מחול לצדיקים\", נאר אויך]\nמיטן ענין פון „שיבנה במהרה בימינו\" (וואס שטייט בסיום המשנה). אז אין דעם זמן פון לעתיד („שיבנה במהרה בימינו\") וועט זיין ניט נאר דער ענין פון שמחה בכלל, „יום שמחת לבו זה בנין בית המקדש\", נאר אויך דער אופן השמחה, וועט זיין, אז „עתיד הקב\"ה לעשות מחול לצדיקים כו'\".\nוואס אויך אין דעם זעט מען דעם חילוק צווישן אופן לימוד הבבלי והירושלמי⁷⁴:\nדי גמרא אין ירושלמי איז בלויז מפרש די משנה⁷⁵, אז דער „שיבנה במהרה בימינו\" וועט זיין אין אן אופן פון „אמן\";\nמשא\"כ די גמרא אין בבלי איז מוסיף נייע⁷⁵ פרטים וועגן דעם זמן דלעתיד — „עתיד הקב\"ה לעשות מחול לצדיקים והוא יושב ביניהם בג\"ע⁷⁶ וכל אחד ואחד מראה באצבעו שנאמר⁷⁷ ואמר ביום ההוא הנה אלקינו זה קוינו לו ויושיענו זה ה' קוינו לו נגילה ונשמחה בישועתו\".\n(משיחת ט\"ו באב תשמ\"ג)",[["74","74","ע\"ד הנ\"ל בפנים (סעיף ו) בנוגע לפירוט הסוגים דבנות ירושלים."],["75","75","ולכן לא הובא המאמר „עתיד הקב\"ה כו'\" בירושלמי כאן (אף שהובא בירושלמי במק\"א — מגילה פ\"ב ה\"ד. מו\"ק פ\"ג ה\"ז)."],["76","76","ולהעיר: מלשון חז\"ל הנ\"ל (בבבלי*) „בג\"ע\" מוכח, שלעת\"ל גם הגופים יהיו בג\"ע (כפשטות הענין שהמחול לצדיקים יהי' לנשמות בגופים. — וצ\"ע בלקו\"ת ואתחנן ז, ב**. — ובפרט לדעת הרמב\"ן (בש' הגמול. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380138\" data-slug=\"likkutei-torah\" data-id=\"4001380138\">לקו\"ת צו טו, ג</a>. דרמ\"צ יד, ב. ובכ\"מ) שזהו עיקר השכר). [ובלאה\"כ מוכרח לומר כן. כי מכיון שקודם החטא הי' גופו של אדה\"ר בג\"ע, עכצ\"ל, שלעת\"ל שיתוקן החטא בשלימותו, ועוד יתוסף — יוכלו הגופים להיות בג\"ע]. וע\"פ המבואר לעיל הערה 37, דזה שבסיום המס' בבבלי מודגשות פרטי המעלות דבנות ירושלים כמו\"ש בהן גופא, הוא מפני שבבבלי מודגש ענין הכלים — מובנת גם השייכות דפרט האמור (שהמחול דלעתיד יהי' בג\"ע) לסיום המס' בבבלי, כי בזה מודגש הענין דבירור הגוף (כלים)."],["77","77","ישעי' כה, ט. *) משא\"כ בירושלמי (שצויינו בהערה הקודמת) איתא „לעתיד לבא\" ולא „בג\"ע\". וראה לקמן בפנים ההערה בסופה. **) וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151143\" data-slug=\"likkutei-sichot\" data-id=\"1300151143\">לקו\"ש חט\"ו ע' 143</a> הערה 44. לעיל ע' 56 הערה 85."]]],[1300241083,"<h3>עקב</h3>\nא. אין אָנהײב פון סדר ברכת¹ הנהנין² שרײבט דער אַלטער רבי: „מצות עשה מן התורה לברך אחר אכילת מזון שנאמר³ ואכלת ושבעת וברכת את ה׳״.\nאַט דער לשון, וואָס דער אַלטער רבי איז מעתיק אױך בשולחן ערוך שלו⁴, איז גענומען פון רמב״ם (ריש הל׳ ברכות)⁵; עס זײנען אָבער דאָ שינויים אין דעם לשון פונעם אלטן רבי״ן (בספריו הנ״ל) לגבי דעם לשון הרמב״ם, און אױך שינויים צווישן די לשונות אין זײן שו״ע און סדר ברכת הנהנין:\nא) אין רמב״ם⁶ און סדר ברכת הנהנין איז דער לשון „מצות עשה . . לברך אחר אכילת מזון כו׳״; אין שו״ע איז דער אלטער רבי מוסיף „(מצות עשה . . לברך) את ה׳ כו׳״.\nב) דער רמב״ם איז מעתיק פון פסוק אױך דעם וואָרט „(וברכת את ה׳) אלקיך״⁷; דער אלטער רבי אין שו״ע איז מרמז דעם המשך הפסוק מיטן וואָרט „וגומר״; און אין סדר ברכת הנהנין שטײט נאָר „וברכת את ה׳״ (אָן „וגומר״).\nדער דיוק אין דעם (שינוי בנוגע דעם „וגו׳״) איז נאָך בולט׳ער: אין דעם המשך הסעיף — סײ אין שו״ע און סײ אין סדר ברכת הנהנין — זאָגט דער אלטער רבי⁸ „וכל הנהנה מהעוה״ז (מן העוה״ז) בלא ברכה כאלו נהנה מקדשי שמים שנאמר⁹ לה׳ הארץ ומלואה״ — און ביי דעם דין איז דאָ א שינוי אין א פארקערטן אופן: אין שו״ע איז ער נאָך די װערטער פון פסוק ניט מוסיף „וגו׳״¹⁰, און דוקא אין סדר ברכת הנהנין איז ער יע מוסיף „וגומר״!",[["7","7","וכ״ה במנין המצות שלו שם (וראה רמב״ם ספר המדע — ירושלים, תשכ״ד — גירסאות שונות בזה מכת״י) ובסהמ״צ שלפנינו שם (אבל בתרגום קאפח ליתא תיבת „אלקיך״)."],["8","8","מברכות לה, סע״א. וברמב״ם הל׳ ברכות שם (הלכה ב) הובא המאמר שלפנ״ז (בברכות שם) „וכל הנהנה בלא ברכה מעל״. וי״ל בפשטות: ברמב״ם שלא כתב בספרו טעמי ההלכות (ראה הל׳ ת״ת לאדה״ז רפ״ב בקו״א) נקט ההלכה — „מעל״; בשו״ע אדה״ז כתב ההלכה עם טעמה (ראה לקמן ס״ה) — „כאלו נהנה מקדשי שמים שנאמר לה׳ הארץ ומלואה״ (ראה רש״י ברכות שם ד״ה מעל)."],["9","9","תהלים כד, א."],["10","10","וכ״ה בברכות שם. אבל בריא״ף (ונוסח הכ״י בדק״ס) שם הובא גם סיום הכתוב. ועד״ז בירושלמי שם. ---"],["1","1","כן הוא בדפוסים שראיתי (ולא „ברכות״ — ל׳ רבים). — ואולי אגב דברכת המזון (שמדובר בו בראשו), שהוא מ״ע (וברכה׳) אחת מה״ת."],["2","2","ועד״ז ב״לוח ברכת הנהנין״ (הוצאה חדשה (ביחד עם סדר ברכת הנהנין) עם מ״מ וכו׳ — קה״ת (כפר חב״ד) תשל״ח)."],["3","3","פרשתנו ח, י."],["4","4","אדה״ז סי׳ קסז ס״א."],["5","5","וראה ברכות כא, א. מח, ב. תוספתא שם רפ״י."],["6","6","וכן במנין המצות שלו בריש ספר היד (מ״ע יט) — „לברך״ (סתם). ובסהמ״צ שם „לברכו״ (ובתרגום קאפח: להודות לו יתעלה). וראה לקמן בפנים סעיף ב והערה 12. *) שו״ע אדה״ז או״ח סקס״ח ס״ח. שם סקצ״א ס״א (ולהעיר מהגהה על הגליון שם, דלפמ״ש אדה״ז בסידורו אתי גם לדעת הפוסקים דמנין הברכות מן התורה). ולהעיר משו״ע אדה״ז שם סקפ״ח ס״ט שג׳ ברכות של בהמ״ז חשובות כברכה אחת."]]],[1300241084,"<h3>עקב א</h3>\nאון אע״פ אז לכאורה זעט אױס אז דאָס זײנען שינויים קלים, װיסנדיק אָבער אױף װיפל ס׳איז מדויק דער לשון פון רמב״ם און פון אלטן רבי׳ן, ובפרט בנדו״ד װאָס דער אלטער רבי איז משנה דעם לשון װאָס ער איז מעתיק פון רמב״ם, ועד״ז איז דער אלטער רבי משנה פון זײן אײגענעם לשון בשולחנו — איז זיכער אז די שינויים זײנען מיט א כוונה.\nב. דעם ערשטן שינוי צווישן דעם לשון הרמב״ם און אלטן רבי׳נס לשון בשו״ע קען מען מסביר זײן:\nדער רמב״ם זאָגט „לברך״ (סתם) — ניט צוגעבנדיק „את ה׳״ — װײל אין דער „כותרת״¹¹ פון הלכות ברכות זאָגט דער רמב״ם „מצוה עשה אחת, והיא לברך את השם הגדול והקדוש אחר אכילה״, דעריבער דארף דער רמב״ם ניט איבער׳חזר׳ן און זאָגן „לברך את ה׳״ אין גוף ההלכה¹² (ובפרט אז דאָס איז די ערשטע הלכה פון הל׳ ברכות, זי קומט גלײך נאָך דער „כותרת״ הנ״ל).\nמשא״כ אין אלטן רבי׳נס שו״ע, װאו ס׳איז ניטאָ אזא הקדמה, זאָגט ער אין דער הלכה אז די מ״ע איז „לברך את ה׳״.\nמען דארף אבער פארשטיין: פארוואָס דארף דער (רמב״ם (בהכותרת) און דער) אלטער רבי בכלל באוארענען „מצות עשה . . לברך את ה׳״ — דאָס שטײט דאָך בפירוש אין דעם פסוק (װעלכן זײ ברענגען דאָ) „וברכת את ה׳״?\nולאידך גיסא, אויב מען דארף דאָס יע באוארענען, איז שװער (כנ״ל סעיף א) — פארוואָס איז דער אלטער רבי דאָס משמיט אין סדר ברכת הנהנין?\nג. װעט מען דאָס פארשטיין ע״פ ביאור החילוק צווישן מטרת החיבור פון (רמב״ם און) שו״ע — און סדר ברכת הנהנין:\nדער רמב״ם והשו״ע זײנען נתחבר געװארן אלס אוסף ו„קיבוץ״ פון פסקי הלכות: דער חילוק איז נאָר, װאָס דער רמב״ם איז „מקבץ לתורה שבעל פה כולה״¹³ — אױך די הלכות װעלכע זײנען ניט נוהג בזמן הזה, און דער שו״ע אנטהאלט בלויז די הלכות װעלכע זײנען נוגע בזמן הזה. דער צד השווה אין זײ איז, אז דאָס זײנען צונויפגעזאמלטע הלכות.\nדעם סדר ברכת הנהנין האט דער אלטער רבי אריינגעשטעלט אין סי־דורי¹⁴, װאָס סידור, כולל אױך די הלכות אין סידור, זײנען פארבונדן מיט הנהגות בפועל בחיי יום יום¹⁵ (װי מ׳זעט עס אין די „הלכות נטילה שחרית״, „הלכות ציצית״ וכו׳, װעלכע פון זײ האט דער אלטער רבי אױסגעקליבן צו אריינ־שטעלן אין סידור)¹⁶.",[["13","13","לשון הרמב״ם בהקדמתו לספר היד."],["14","14","שקלאוו תקס״ג (שער הכולל בהקדמתו. בית רבי ח״א פכ״ז. ס׳ התולדות אדה״ז (גליצנשטיין תשכ״ז, תשל״ו) ע׳ שכג)."],["15","15","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151387\" data-slug=\"likkutei-sichot\" data-id=\"1300151387\">לקו״ש חט״ו (ע׳ 374</a>) שבכללות זהו ההפרש בין ספר היד (דהרמב״ם) להשולחן ערוך, ע״ש. אבל מובן, שלגבי ההלכות שבסידור (שבו רק ליקוט הלכות הצריכות ממש, ע״ד הרגיל) גם השו״ע ענינו „קיבוץ״ פסקי הלכות."],["16","16","ובכל אופן צ״ע למה הכניס אדה״ז בסידורו כל סדר ברכת הנהנין, שהוא חיבור שלם בפ״ע (ולא רק ליקוט של הלכות הרגילות ביותר, כהלכות נטילת שחרית, ציצית וכו׳ שבסידור). — וראה הגש״פ עם ביאורים (קה״ת תשמ״ו ושלאח״ז) ע׳ סט. ---"],["11","11","שגם כותרות אלו הם להרמב״ם (ראה רמב״ם דפוס שולזינגער תש״ז צילום כת״י הרמב״ם דריש הל׳ שאלה ופקדון)."],["12","12","אבל זה שלא כתב תיבות אלו במנין המצות (כנ״ל הערה 6) לא קשה כלל, כי שם נכתבו בקיצור הכי נמרץ."]]],[1300241085,"<h3>עקב א</h3>\nד.ה. אז די הלכות פון סדר ברכת הנהנין זײנען געשריבן (ניט בסגנון לימוד לשם ידיעת הלכות, נאָר) אין א סגנון פון — הוראות למעשה בפועל¹⁷.\nד. אײנער פון די חילוקים המס־תעפים מזה צווישן לשון — אדה״ז בהשו״ע און לשון סדר ברכת הנהנין (והלכות שבסידור בכלל):\nאין סדר ברכת הנהנין, הוראות להנהגה גלײך בפועל¹⁸, איז דער דיוק הלשון בעיקר צו באוארענען אז די הלכה זאל קלאר אריסברענגען װי די הנהגה גלײך על אתר דארף זײן; ס׳איז אבער ניט אזוי נוגע דער דיוק הלשון צו באוארענען װאָס מ׳װעט אריסדרינג־ען פון דעם בא אַנאַנדער הנהגה, לגבי אַן אַנדער הלכה.\nמשא״כ אין שו״ע, װאָס איז א קיבוץ פון אלע פסקי הלכות, איז דער דיוק הלשון אין אן אופן װאָס באוארנט מ׳זאל ניט אריסדרינגען דערפון קיין ענין װאָס איז ניט אױסגעהאלטן בשו״ע (װאו ס׳זאל ניט זײן).\nעפ״ז װעט מען פארשטיין פארוואָס אין שו״ע איז דער אלטער רבי מדייק ומוסיף „(לברך) את ה׳״ און אין סדר ברכת הנהנין לאזט ער דאָס אױס:\nס׳איז א כלל¹⁹, אז דער װארט „את״ בתושב״כ (אבער כלל ניט בתושבע״פ²⁰) איז א ריבוי. ע״ד װי מען לערנט אפ²¹ פון „את ה׳ אלקיך תירא״²² — „לרבות תלמידי חכמים״. ועד״ז אין אונזער פסוק „ואכלת גו׳ וברכת את ה״א״ — איז דער װארט „את״ א ריבוי, װי עס שטײט אין ראשונים²³: „וברכת את — לרבות בעה״ב״, און דעריבער איז די הלכה „אורח²⁴ מברך (המזון) כדי שיברך לבעל הבית״.\nדערפאר מוז דער אלטער רבי בשולחנו מדייק זײן „מצות עשה מן התורה לברך את ה׳״ — צו שולל זײן א טעות, מ׳זאל ניט מיינען אז די „מצות עשה מן התורה״ איז כולל אױך די ברכה לבעל הבית²⁵ (װאָס װערט אפגעלערנט פון װארט „את״, כנ״ל).",[["17","17","ועאכו״כ „לוח ברכת הנהנין״ — די״א שנק׳ כן מפני שלכתחילה הי׳ כמו לוח על כותלי ביהכנ״ס ובהמ״ד כו׳."],["18","18","וצע״ג למה נשתנו הל׳ נט״י לסעודה וברה״נ — שבאו בהסידור לאחרי ברהמ״ז (ותקח״צ וכו׳) ולא לפניהם כשאר ההלכות שבסידור. בכל סידורי תורה אור שראיתי (כולל ההוצאה דשנת תרנ״ב „שערי תפלה״) הוא כנ״ל, אבל בסידור עם דא״ח בהוצאה הראשונה שהו״ל ע״י אדמו״ר האמצעי (וכן בשלאחרי׳) באו דיני נט״י לסעודה לפני ברהמ״ז, וסדר ברה״נ — לאחרי ברהמ״ז [וכ״ה גם בסידור אור המאיר (ווילנא תרנ״ה). ועוד]. בסדר תפלות לכל השנה (טשערנאוויץ תרכ״ה), וסידור המאיר לארץ (ווילנא תר״ל) ושני המאורות (ווילנא תרנ״ז) באו שניהם לפני ברהמ״ז. בסידור שלמי תודה (ווילנא תרס״ו) באו כל ההלכות (גם דנט״י וסדר ברה״נ) בתחלת הסידור — אבל נראה שבסידורים אלו נהגו המו״ל ע״ד עצמם בכל כיו״ב. ולהעיר אשר בסי׳ האריז״ל (דר׳ שבתי וסי׳ קול יעקב) כוונות הנטילה הן לפני ברהמ״ז וכוונות ברכת הנהנין — לאחרי ברהמ״ז (אלא שבסי׳ קול יעקב בא בין ברהמ״ז לכוונות ברה״נ „כוונת הלימוד״)."],["19","19","„בכולי הש״ס אמרי׳ אתין . . ריבויא״ (רא״ש בכורות פ״א סי״ה). וראה אנציקלופדי׳ תלמודית ערך אתין וגמין. וש״נ."],["20","20","ומשמע בכ״מ בש״ס וכיו״ב — דאדרבא הוספת „את״ מוסיפה דיוק ושלילת הוספה אפילו טפל דטפל. ואכ״מ."],["21","21","פסחים כב, ב. וש״נ."],["22","22","פרשתנו י, כ."],["23","23","סמ״ג עשין כז בשם הירושלמי. ס׳ המנהיג הל׳ סעודה סט״ז (הובא באבודרהם דיני ברכת המזון) בשם התוספתא. ועוד (ראה הנסמן באנציקלופדי׳ תלמודית ע׳ אורח הערה 72)."],["24","24","ברכות מו, א. רמב״ם הל׳ ברכות פ״ז ה״ב. טושו״ע (ודאדה״ז) או״ח סי׳ רא ס״א (ס״ד)."],["25","25","ואף שהרמב״ם שם (הלכה א) מקדים"]]],[1300241086,"<h3>עקב א</h3>\nמשא״כ אין סדר ברכת הנהנין, װאו ס׳איז װיכטיק (נאָר) צו אריסברענגען קלאר די הנהגה על אתר, איז ניט נויטיק די הוספה „לברך את ה׳״, װײל עס שטײט בהסידור „וברכת את ה׳א״, אױך, איז מובן מעצמו אז ברכת המזון איז צו דעם אױבערשטן (און דערצו ברענגט ער גלײך דערנאָך אין סדר ברה״נ דעם פסוק „וברכת את ה׳״).\nועוד להוסיף: אין סדר ברכת הנהנין װערט ניט געבראכט דער דין²⁶ „האורח מברך כדי שיברך לבעה״ב״, ובמילא דארף מען ניט באוארענען אין סדר ברכת הנהנין דעם טעות הנ״ל (אז די מ״ע מהת״ איז ניט כולל ברכה לבעה״ב); משא״כ אין (רמב״ם ו)שו״ע אדה״ז װאו דער דין װערט יא גע־בראכט.\nה. נאָך א חילוק צווישן דעם אלטן רבי׳נס שו״ע וסדר ברכת הנהנין וואָס קומט אריס פון דעם חילוק הנ״ל (ס״ג) — איז אין דעם ענין פון טעמי הלכות:\nדער חידוש פון דעם אלטן רבי׳נס שו״ע (לגבי דעם שו״ע פון ב״י) איז וואָס ער זאָגט „מילתא בטעמא״, „הלכות בטעמיהן״²⁷; משא״כ די הלכות אין סידור זײנען בלויז פסקי הנהגות בנוגע למעשה בפועל. און אע״פ אז אױך אין סידור ברענגען זיך בכ״מ²⁸ טעמי ההלכה (בקיצור) — איז דער חילוק צווישן דעם שו״ע אדה״ז און זײן סידור:\nדער אלטער רבי האט אריינגעשטעלט טעמי ההלכות אין שו״ע כדי ס׳זאל ניט זײן ע״ד „מבלי עולם״²⁹, צוליב ידיעת התורה³⁰, װעלכע איז צו װיסן „הלכות בטעמיהן (בדרך קצרה)״³¹;\nמשא״כ אין סידור (ועד״ז סדר ברכת הנהנין) װאָס ענינו איז פסקי הנהגות למעשה, זײנען אױך די טעמים װאָס ברענגען זיך דארט (ניט צוליב ידיעת הטעמים, נאָר) צוליב װיסן קלערער די הנהגה למעשה בפועל, מאכן איר „געשמאקער״ מיט מער כוונה, חיות וכו׳³².\nװי מען זעט עס בכ״מ, װאו מען בריינגט דעם טעם ההלכה (בקיצור).\nו. עפ״ז װעט מען אױך פארשטײן דעם צװײטן שינוי (הנ״ל סעיף א) צװישן לשון השו״ע ולשון סדר ברכת הנהנין:",[["","","„מנהגות רבות נהגו . . וכולן דרך ארץ״, וא״כ אין מקום לטעות שהוא מ״ע מה״ת (וכן משמע בשו״ע אדה״ז שם, דמותר לבעה״ב לוותר על ברכתו) — כותב „לברך את השם כו׳״, כי מכללי הרמב״ם שאינו סומך על מה שיכתוב לאח״ז בריחוק מקום (יד מלאכי כללי הרמב״ם אות וא״ו). ולהעיר מתוד״ה הא ברכות ב, סע״א (ובהנסמן שם), דרגילות של משניות לאשמעינן בקוצר אף למה שמפורש כבר."],["26","26","ולהעיר שאין נוהגין שהמזמן יברך ברכה זו לבעה״ב, כ״א כולם (ואפילו כשאין זימון) אומרים בסוף ברהמ״ז (לאחרי (ברכת) אל יחסרנו), „הרחמן כו׳ בעל הבית הזה״, וכמו שתמה במעדני יו״ט לרא״ש ברכות שם (פ״ז סי״א). וראה לבוש או״ח שם ס״א."],["27","27","הקדמת הרבנים בני הגאון המחבר ז״ל."],["28","28","בהתחלתו בהשכמת הבוקר ועוד רבות. ומודגש בכ״מ גם בהסגנון (וע״י האריכות) וכמו בהל׳ נטילת שחרית, „לפי שבנוסח כו׳ אין איסור כו׳ אבל להזכיר כו׳״."],["29","29","סוטה כב, א."],["30","30","כמובן מהקדמה הנ״ל, ע״ש."],["31","31","הל׳ ת״ת לאדה״ז רפ״ג. ועד״ז שם רפ״ב."],["32","32","ואף שגם ידיעת הטעמים הוא מפני ש„אם אינו יודע טעמי ההלכות אינו מבין גופי ההלכות לאשורן על בוריין״ (הל׳ ת״ת שם רפ״ב) — מובן, גודל החילוק בין הבנה „לאשורן על בוריין״, להוספת ידיעה בההנהגה בפועל וכוונה הבאות ע״י טעם קצר."]]],[1300241087,"<h3>עקב א</h3>\nאין שו״ע, װאו דער אלטער רבי ברענגט די טעמי ההלכות צוליב ידיעה (כנ״ל), ברענגט ער אױך (בכ״מ) די פסוקים פון װאנעט מען לערנט אפ די הלכות: ועד״ז בנדו״ד ברענגט דער אלטער רבי דעם פסוק אױף דער מצות עשה מן התורה לברך אחר אכילת מזון³³ — „ואכלת ושבעת וברכת את ה׳״.\nאון דערפאר איז דער אלטער רבי דערנאָך אױך מוסיף „וגומר״ — װײל אין דער ידיעת לימוד ברכת המזון „מן התורה״ איז נוגע (ניט נאָר די װערטער „וברכת את ה׳״, נאָר) אױך דער המשך הכתוב, װי דער אלטער רבי ברענגט אראפ בשולחנו³⁴, אז פון די װערטער „על הארץ הטובה״ שבפסוק לערנט מען אפ, אז מן התורה דארף ברכת המזון כולל זײן א ברכה „על הארץ ועל המקדש (ירושלים)״,\n[משא״כ אין רמב״ם³⁵, װאו דער לימוד (אױף הלכה) הנ״ל װערט ניט גע־בראכט³⁶, שטײט נאָר „וברכת את ה׳ אלקיך״ — אן הוספת „וגו׳״ — װײל אין דער הלכה (די „מ״ע . . לברך אחר אכילת מזון״) איז נוגע בלויז „וברכת את ה׳ אלקיך״³⁷].\nאבער אין (סידור³⁸, כולל) סדר ברכת הנהנין, װאו די טעמים קומען נאָר צו קלאר מאכן די (הלכה) הנהגה, איז ניט נוגע צו ברענגען די פסוקים.\nאעפ״כ ברענגט דער אלטער רבי דעם פסוק בנדו״ד, װײל דער פסוק גיט אריס דעם גדר (װאָס קומט אריס פון דעם טעם) פון דער הלכה, די תוספת הבנה, כוונה און געשמאק אין דער הנהגה\nדער גדר (וטעם) פון ברכת המזון איז — „ואכלת ושבעת וברכת את ה׳״: װי־באלד ער איז געװארן זאט, מוז מען פאר דעם בענטשן (דאנקען) דעם אױבערשטן.\n[און דאָס איז א הקדמה צום המשך הסעיף (בנוגע אלע ברכת הנהנין) — „וכל הנהנה מן העוה״ז כו׳ כאלו נהנה מקדשי שמים״ — װיבאלד מ׳גײט הנאה האבן פון א זאך װאָס געהערט „לה׳״ דארף מען אים אױף דעם מברך זײן (ע״ד ברכת המזון, װאו די שביעה איז מחייב א ברכה)].\nאון דערפאר לאזט ער אױס דעם „וגומר״ — װײל אין דעם גדר פון ברכת המזון איז ניט נוגע דער המשך הכתוב, אפילו ניט דער װארט „אלקיך״,\nואדרבה: ניט נאָר איז „אלקיך״ ניט מוכרח לידיעת גדר הברכה, נאָר עס קומט ללמד אױף א סוג ברכה װאָס איז אן ענין הפכי פון ברכת המזון (וברכת הנהנין)³⁹:",[["33","33","נוסף לזה שהוא גם טעם ההלכה, כדלקמן בפנים. וראה הערה 39."],["34","34","סקס״ח ס״ח, ר״ס קפז — מברכות מח, ב. תוספתא שם רפ״י."],["35","35","הל׳ ברכות רפ״ב."],["36","36","להעיר מכס״מ שם (ה״ב. וכ״ה בב״י לאו״ח סקצ״א) דלהרמב״ם הנך קראי אסמכתא בעלמא נינהו. אבל כוונתו רק בנוגע למנין הברכות (שאינו מהת״ת), כי „מן התורה הי׳ די בברכה א׳ מעין שלש״ (שו״ע אדה״ז סקס״ח שם (ובקו״א). סקצ״א)."],["37","37","וצע״ק שהרמב״ם מביא גם תיבת „אלקיך״ (ואולי מפני שהוא סיום הענין) — ויש לברר בכת״י וכו׳. וראה לעיל הערה 7."],["38","38","אבל ראה ב„השכמת הבוקר״ שלשה פסוקים! וי״ל הטעם מפני שזהו מעין פתיחה לכל ההנהגות והתפלות (הסידור). ויתרה מזה — חלק וחלק עקרי בהו. ועפ״ז יובן ויומתק זה שלא נקרא „הלכות השכמת הבוקר״."],["39","39","ועפ״ז מובן ג״כ הא שלא העתיק אדה״ז"]]],[1300241088,"<h3>עקב א</h3>\nעס שטײט אין תוספתא⁴⁰ אז פון „אלקיך״ — מלשון „דיינך״ — לערנט מען אפ „שכשם שאתה מברך על הטובה כך אתה מברך על הרעה״, „בכל דין שדנך בין במדת הטוב בין במדת הפור־ענות״ — װאָס איז היפך⁴¹ פון ברכת המזון וברה״נ װעלכע זײנען אױף שביעת (והנאת) הגוף (און דער פאר־גלײך צו „מברך על הטובה״ איז נאָר אין דעם „לקובלינהו בשמחה״⁴²).\nז. ע״פ החילוק כללי הנ״ל צווישן דעם אלטן רבי׳נס שו״ע וסדר ברכת הנהנין קען מען אױך מסביר זײן דעם חילוק צווישן זײ אין דעם המשך הסעיף, ביים ברענגען דעם פסוק „לה׳ הארץ ומלואה״ (כנ״ל סעיף א):\nאע״פ אז דער באוארענען א טעות װאָס קען אריסקומען במק״א איז שייך אין שו״ע און ניט (אזוי) אין סדר ברכת הנהנין (כנ״ל ס״ד) — איז אבער בנוגע דער באוארעניש אין דער הלכה והנהגה על אתר, הענין בהיפך:\nאין סדר ברכת הנהנין װאָס איז הוראות למעשה, קומט אױך א הוספה בלשון װאָס באוארנט אפילו דבר\nהמובן, אבי די הנהגה בפועל זאל זיכער אריסקומען כדבעי (משא״כ אין שו״ע איז דער לשון בקיצור, און עס שטײט ניט א זאך װאָס איז מובן מעצמו).\nאון דערפאר איז ער אין סדר ברכת הנהנין מוסיף (נאָך „לה׳ הארץ ומלואה״) „וגו׳״: דאָס איז מוסיף ביאור בההלכה אז „כל הנהנה מן העוה״ז כו׳ כאלו נהנה מקדשי שמים״ (װײל אלץ באלאנגט צום אױבערשטן), װעלכע מיינט — (הנאה פון) יעדער זאך אין עוה״ז: װאָס דאָס (אז גאנץ עוה״ז באלאנגט צום אױבערשטן) איז מפורט, אָדער געזאגט אין דעם המשך הכתוב „תבל ויושבי בה״⁴³:\n„לה׳ הארץ ומלואה״ גײט אױף ארץ ישראל⁴⁴, און אין המשך הפסוק קומט צו, אז אױך „תבל״ — די גאנצע װעלט — איז „לה״, און נאכמער — אױך „ויושבי בה״ זײנען לה׳:\nובמילא איז „כל הנהנה מן העוה״ז״, און אפילו װען דער מאכל געהערט צו א צװײטן מענטשן⁴⁵ און אפילו צו א ניט־איד, איז דאָס „כאלו נהנה מקדשי שמים״, און דערפאר מוז יעדער הנאה האבן א ברכה לפני׳.\n(משיחות כ״ד טבת ומוצאי ש״ק וארא תשל״ט)",[["","","תיבת „אלקיך״ בשולחנו (דלכאורה הו״ל להעתיק „אלקיך״ (כברמב״ם) ואח״כ להוסיף „וגומר״) — כי זה שהביא הכתוב בשו״ע הוא (בעיקר) מפני שהוא טעם ההלכה (כנ״ל), ובטעם ברכה זו תיבת „אלקיך״ מיותרת ו(גם) הפכית, כבפנים (משא״כ ברמב״ם שלא כתב (ובפרט כאן) טעם ההלכה (כנ״ל הערה 8) העתיק גם תיבה זו)."],["40","40","ברכות פ״ו, ג. ברכות מח, ב."],["41","41","נוסף לזה שהוא ממין אחר דברכות שנמנו — ראה רמב״ם הל׳ ברכות פ״א ה״ד."],["42","42","ברכות ס, ב. רמב״ם שם פ״י ה״ג. טושו״ע או״ח סרכ״ב ס״ג. סדר ברכת הנהנין פי״ב ה״י."],["43","43","וראה לעיל הערה 10."],["44","44","רש״י תהלים עה״פ (ע״פ מדרש תהלים עה״פ בתחלתו („והעיר זה ארצו (ארץ ישראל) . . לכך נאמר לה׳ הארץ ומלואה״))."],["45","45","להעיר מהשקו״ט אם אורח קונה חלקו — ראה אנציקלופדי׳ תלמודית ערך אורח (ע׳ שפז) וש״נ."]]],[1300241089,"<h3>עקב ב</h3>\nא. אויפן פסוק¹ „כי ה׳ אלקיכם הוא אלקי האלקים גו׳ אשר לא ישא פנים ולא יקח שוחד” — זאגט רש״י: „לא ישא פנים — אם תפרקו עולו”; „ולא יקח שוחד — לפייסו בממון”.\nדארף מען פארשטיין: וואס איז רש״י מחדש מיט זאגן אז „לא ישא פנים” איז „אם תפרקו עולו” — ווען דען זאל דער אויבערשטער ניט נושא פנים זיין — בשעת מ׳איז מקיים תומ״צ? ומאי קמ״ל!\nזאגן מפרשים², אז רש״י קומט בא־ווארענען דאס וואס דא שטייט „לא ישא פנים” און פריער (אין ברכת כהנים) שטייט³ „ישא ה׳ פניו אליך”⁴: איז רש״י מפרש, אז דא איז אנדערש, ווייל עס רעדט זיך „אם תפרקו עולו”.\nעס איז אבער אלץ ניט מובן — מאי קמ״ל, עס איז, לכאורה, מובן מעצמו, אז „לא ישא פנים” איז „אם תפרקו עולו”; ובפרט נאך דער אריכות בזה פריער אין פרשת בחוקותי.\nועוד: „ישא ה׳ פניו אליך” — טייטשט רש״י „יכבוש כעסו”, קומט אויס, אז דארט רעדט זיך אין א פאל אז ס׳איז דא „כעסו” ובמילא די סיבה אויף „כעסו”, הנהגה היפך רצון השם, און פונדעסט־וועגן איז „ישא ה׳ פניו” — בלייבט דאך ווידער די סתירה האמורה?\nב. אויך דארף מען פארשטיין אין דעם צווייטן פירוש פון רש״י: „ולא יקח שוחד” — „לפייסו בממון”.\nבשלמא דאס וואס רש״י גיט צו דעם ווארט „לפייסו” — הגם אז אין פסוק רעדט זיך וועגן „שוחד” — איז, ווי דער רא״ם איז מבאר ומובן בפשטות, אז שוחד בכל מקום (בא א דיין ב״ד) קען מיינען „לזכות את החייב” (עיוות הדין) אדער „לוותר לו ענשו”, „והשי׳ ית׳ לא יפול בו לזכות את החייב, רק לוותר העונש”, דעריבער איז רש״י מדגיש אז דער פסוק רעדט וועגן אזא שוחד וואס תוכנו איז „לפייס”, ד.ה. וויתור העונש (און ניט — „לזכות את החייב”, ווארום דאס דארף מען ניט שולל זיין).\nעס בלייבט אבער ניט פארשטאנדיק דער „בממון” אין פרש״י, וכקושיית הרא״ם: „לא ידעתי מה ממון נופל אצל הקב״ה. ולמה לא פירש ולא יקח שוחד המצוה בעבור העבירה”?\nאויך: פארוואס איז רש״י מעתיק פון פסוק אויך די ווערטער „ולא יקח”? זיין פירוש דא איז נאר בנוגע דעם ווארט „שוחד” — (א) אז דאס איז „פיוס”, און (ב) אז דער פיוס באשטייט דורך „ממון”.\nג. אויף דער קשיא האמורה פון רא״ם געפינט מען אין מפרשים⁵ כמה תירוצים:\nא) מיט „ממון” דא ווערט געמיינט דאס ברענגען א קרבן צום אויבערשטן,",[["1","1","פרשתנו י, יז."],["2","2","דבק טוב, משכיל לדוד, מלאכת הקודש."],["3","3","נשא ו, כו."],["4","4","וראה ברכות כ, ב. ר״ה יז, סע״ב. נדה ע, ב. ספרי נשא שם. פיה״מ להרמב״ם מגילה פ״ד (הי׳ קורא) מ״ח. ובכ״מ. בתוס׳ ר״ה ונדה שם, שע״פ פשוטו של מקרא אין זו סתירה בין הכתובים. אבל ראה חדא״ג מהרש״א נדה שם (סט, ב ד״ה ושאלו). לקו״ת נשא ד״ה כה תברכו (כו, סע״א ואילך)."],["5","5","ראה גו״א, דברי דוד (להט״ז), שפ״ח. וראה גם משכיל לדוד."]]],[1300241090,"און דער פסוק לאזט אונז דערמיט הערן, אז „זבח רשעים תועבה”⁶ — כל זמן ער האט ניט תשובה געטאן ווערט זיין קרבן ניט אנגענומען.\nב) דער ענין פון „לפייסו בממון” מיינט, כלשון הכתוב פריער „ויקחו לי תרומה”⁷, יעדער ממון וואס מ׳איז מקדיש לי לשמי, לצרכי המשכן, המקדש וכיו״ב — און דער פסוק זאגט אז מיט נתינת ממון לגבוה קען מען ניט אראפ־נעמען דעם עונש פון אן עבירה (סיידן דורך תשובה טאן).\nג) „ממון” מיינט יעדער מצוה וואס איז פארבונדן מיט נתינת ממון, אזוי ווי צדקה וכיו״ב (וכנ״ל, אז דאס איז ניט מספיק).\nאבער: די תירוצים פארענטפערן נאר דעם חלק הטפל פון קושיית הרא״ם, ווי קען זיין א מציאות פון קבלת ממון ביים אויבערשטן, אבער דער עיקר שאלה בלייבט במקומה:\nוויבאלד דער טעם וואס (עס קען זיין א קס״ד אז) דער ממון קען האבן א פעולה פון „שוחד” כביכול ביים אוי־בערשטן איז ניט ווי ממון ביי א ב״ד (וואס דער דיין האט א תועלת פון דעם ממון גופא), נאר ווייל דערמיט ווערט געטאן א מצוה, געבראכט א קרבן או כיו״ב, איז פארוואס טיילט רש״י אויס (מצוה) „בממון” — מאי שנא א מצוה דורך נתינת ממון פון אלע אנדערע מצות?\nובפרט לויטן פירוש אז עס רעדט זיך וועגן א קרבן (וועלכער איז „ניחוח” — נחת רוח לפני⁸, היפך פון „כעסו”), האט רש״י זיכער געדארפט זאגן קלאר „לפייסו בקרבן” און ניט מרמז זיין אויף דעם מיטן ווארט „בממון”,\nועוד — לויט דעם פירוש איז בכלל „העיקר חסר מן הספר” (אז כאטש קרבן איז מכפר, דאך מוז זיין דערביי אויך תשובה):\nועוד: בפשוטו של מקרא — ווי ווערט נרמז (עכ״פ) אין „לא יקח שוחד” אז קרבן איז מכפר נאר מיט תשובה?\nאויך — מען קען ניט זאגן אז רש״י זאגט „בממון” — ווייל „שוחד” בשייכות צו בנ״א מיינט ע״ד הרגיל אז מ׳איז משחד מיט „ממון”⁹ — ווארום: א) אויך ביי מענטשן איז פאראן „שוחד דברים”¹⁰ וכיו״ב. ב) ועיקר: עס בלייבט די שאלה אויפן פסוק — פארוואס זאגט דער פסוק „שוחד” (וואס מיינט „בממון”) און ניט אן אויסדרוק וואס מיינט „במצות” וכיו״ב?\nד. דער ביאור בזה:\nדי כוונה אין פירוש רש״י דא איז מדויק בלשונו — „אם תפרקו עולו” (ניט איינע פון די לשונות פון פ׳ בחוקותי וכיו״ב):\nדא רעדט זיך ניט וועגן סתם ניט מקיים זיין מצות, טאן עבירות ר״ל\nאין אזא פאל בעט מען ביים אוי־בערשטן און כהנים בענטשן אז „ישא ה׳ פניו אליך”, ער וועט כובש זיין כעסו און ניט מעניש זיין —\nנאר דא רעדט זיך וועגן פריקת עול — וועגן אזא וואס ווארפט אראפ דעם גאנצן יאך פון אויבערשטן ר״ל, ער",[["6","6","משלי כא, כז."],["7","7","תרומה כה, ב."],["8","8","פרש״י ויקרא א, ט."],["9","9","ראה משכיל לדוד."],["10","10","כתובות (קה, ב), אבל רש״י עה״ת (שמות כג, ח) לא פירש כן."]]],[1300241091,"ווערט אויס עבד ה׳ ואדרבא¹¹ ער פילט זיך פריי צו טאן וואס ער וויל, ער זאגט „בשרירות לבי אלך”¹² — אויף דעם זאגט דער פסוק „לא ישא פנים”: דער אויבערשטער פירט זיך מיט אים בדקדוק, איז ניט מוותר.\nאון דער הכרח אויף דעם פירוש איז פון כללות תוכן הפרשה:\nדי פרשה הויבט זיך אן¹³ מיט „ועתה ישראל מה ה״א שואל מעמך כי אם ליראה גו׳”. איז רש״י מפרש: „אע״פ שעשיתם כל זאת עודנו רחמיו וחיבתו עליכם, ומכל מה שחטאתם לפניו אינו שואל מכם כי אם ליראה וגו׳”.\nגלייך בתחלת הפרשה איז מודגש, אז דער אויבערשטער איז יע נושא פנים צו אידן, אע״פ שעשיתם כו׳, נאר ער מאנט בלויז — „ליראה וגו׳”.\nאון דעריבער, ווען דער פסוק זאגט בהמשך לזה „לא ישא פנים”, מוז מען זאגן, אז דא רעדט זיך וועגן דעם היפך פון דעם ענין — אויב עס איז היפך, עס קען ניט זיין „ליראה וגו׳”.\nדערפאר איז רש״י מפרש „לא ישא פנים — אם תפרקו עולו”, כנ״ל.\nה. עפ״ז איז מובן פארוואס רש״י קען ניט לערנען, ווי אנדערע מפר־שים¹⁴, אז „ולא יקח שוחד” מיינט „שוחד מצות” — ווייל ווי רש״י לערנט דעם פסוק (אז דער מדובר איז וועגן אזא וואס ביי אים פעלט דער „ליראה” — „תפרקו עולו”) האט שוין קיין ארט ניט צו מפרש זיין (דעם „ולא יקח שוחד”) אז דער אויבערשטער נעמט ניט אן קיין „שוחד מצות” פון א „פורק עול”, ווייל אזא הוה אמינא איז שוין מופרך פון „לא ישא פנים” וואס שטייט פריער.\nמוז רש״י געפינען אן ענין ביי וועלכן עס קען זיין א קס״ד אז ער קען אויפ־טאן אן ענין פון פיוס וכפרה אויך ביי א פורק עול — און דערפאר זאגט רש״י „לפייסו בממון”.\nפארוואס וואלט מען געמיינט אז „ממון” קען מכפר זיין אויפן ענין פון „תפרקו עולו” — דארף רש״י ניט אויסטייטשן, ווייל מען האט שוין דאס געלערנט פריער: אויף „ולא תקחו כופר”¹⁵ (וואס שטייט ביי א הורג נפש) זאגט רש״י „לא יפטר בממון” (און עד״ז בנוגע שור שהרג אדם שטייט „ונתן פדיון נפשו”¹⁶) — וואס דערפון איז מובן, אז דער „שוחד” פון „ממון” האט אין זיך א צווייענדיקע תכונה ופעולה: נוסף לזה וואס דער מקבל הממון ווערט „משוחד” (צוליב זיין הנאה ותועלת פון דעם ממון), דינט דער ממון אויך אלס „כופר”, אויסלייז און פארבייט פון דעם נותן, אז אנשטאט ער זאל אפגעבן זיך אליין (למיתה וכיו״ב), גיט ער אוועק זיין ממון¹⁷; ביז אז רש״י¹⁶ ברענגט א דיעה בנוגע צו כופר פון שור שהרג אדם — אז דער „פדיון נפשו” מיינט גאר „דמי מזיק”.\n[און דער טעם דערויף איז מובן — מדה כנגד מדה, כמש״נ¹⁸: בדבר אשר זדו עליהם. און ווי דער אלטער רבי איז",[["11","11","ראה תולדות (כו, מ): תעבוד (והפכו) . . ופרקת עולו."],["12","12","נצבים כט, יח."],["13","13","פרשתנו י, יב."],["14","14","רמב״ן וספורנו (ומפרשי רש״י הנ״ל) כאן. פיה״מ להרמב״ם אבות ספ״ד (הובא לקמן בפנים). ולגירסת המאירי (אבות שם. ועוד) כ״ה בספרי פרשתנו כאן."],["15","15","מסעי לה, לא."],["16","16","משפטים כא, ל."],["17","17","ולהעיר ממכות ב, ב."],["18","18","יתרו יח, יא."]]],[1300241092,"מבאר בפרטיות אין תניא¹⁹ בנוגע צו מצות הצדקה, אז וויבאלד דורך דעם ממון „הי׳ יכול לקנות חיי נפשו”, במילא „הרי נותן חיי נפשו לה׳”.\nוע״ד ווי רש״י ברענגט מיט עטלעכע פסוקים ווייטער²⁰, אויף „היקום אשר ברגליהם” — „זה ממונו של אדם שמעמידו על רגליו”].\nאון דאס איז דער פסוק שולל: ביי דעם אויבערשטן איז ניט שייך „לפייסו בממון”: אוודאי מיינט עס ניט צו בא־ווארענען אז מען קען דעם אויבערשטן ניט „אונטערקויפן” ח״ו מיט ממון: דא רעדט זיך נאר וועגן דעם אויפטו פון דעם ממון פאר דעם נותן: ער קען מיינען, אז כאטש ער איז א פורק עול און איז ניט איבערגעגעבן צום אוי־בערשטן, קען ער (אנשטאט זיך אליין) געבן זיין ממון, און דער אויבערשטער וועט עס אננעמען אלס „כופר נפשו”.\nאויף דעם זאגט דער פסוק: „ולא יקח שוחד”. דער אויבערשטער וועט ניט נעמען כופר, עפעס אנדערש, נאר סיידן ער גיט זיך אליין איבער צום אוי־בערשטן, און ערשט דעמולט האט א פעולה ווען ער גיט ממונו צו הקב״ה; בשעת אבער ער איז א „פורק עול” — איז „לא יקח שוחד”.\nלויט דעם איז אויך מובן דער טעם וואס דער פסוק איז מדגיש (און רש״י איז מעתיק) „לא יקח”: וויבאלד די נתינת ממון איז א זאך וואס האט אין זיך דעם תוכן פון נתינת עצמו (חיי נפשו), קבלת עול: נאר דער חסרון איז וואס זייענדיק א פורק עול קען די נתינת הממון אים ניט פארבייטן — דערפאר איז דא די הדגשה פון פסוק ניט אינעם שולל זיין די (נתינת ה)ממון, נאר אין דעם ניט אנגענומען ווערן אלס „פיוס” ו„שוחד”. דער פסוק איז מדגיש „ולא יקח שוחד”.\nו. יעדער ענין — ובפרט ענינים פון תומ״צ — איז בהשגחה פרטית. זעט מען, אז אט דער ענין (אז דער אוי־בערשטער „לא ישא פנים ולא יקח שוחד”) שטייט אויך אין סוף פון דעם פערטן פרק פון מס׳ אבות: „שאין לפניו כו׳ ולא משוא פנים ולא מקח שוחד”,\nוואס לויטן סדר פון די „יש נוהגין”²¹ צו לערנען פרקי אבות „כל שבתות הקיץ”, קומט אויס (בכמה שנים) אז דער פרק רביעי ווערט געלערנט בשבת פרשת עקב.\nאון דא זעט מען, אז דוקא לויט פירוש רש״י בפשוטו של מקרא, ווערט מוסבר ומתורץ די שאלה: וואס טוט אויף די משנה אויפן פסוק המפורש בתורה?\nדער חילוק איז מובן ע״פ הנ״ל:\nאין תורה שטייט דער פסוק אין דעם ענין (ומצב) „ועתה ישראל מה ה״א שואל מעמך גו׳”, וואס דאס איז מכריח צו לערנען (כנ״ל), אז דער „ולא יקח שוחד” דא קומט אלס המשך צו כללות הענין פון קבלת עול מלכות שמים: און דערפאר איז רש״י — וואס פירושו איז לויט פשוטו של מקרא — מפרש „לא ישא פנים — אם תפרקו עולו, ולא יקח שוחד — לפייסו בממון”.",[["19","19","פל״ז (מח, סע״ב)."],["20","20","פרשתנו יא, ו. וראה רש״י שמות ד, יט."],["21","21","סידור אדה״ז. וכן הוא דעת הרמ״א (או״ח סו״ס רצב — ולא העתיק זה אדה״ז בשולחנו שם). סידור הרמ״ק. מטה משה סי׳ תפו. מנהג זה הובא בס׳ המנהיג (מנהג צרפת), ס׳ המנהגים למהר״י טירנא (מנהג הגר פולין וברונא), ארחות חיים (משבועות ועד סוכות). ועוד. — ולהעיר שי״א הן בקיץ והן בחורף — טור מר״ע גאון. ועוד. וראה מחזור וויטרי."]]],[1300241093,"משא״כ אין (די משניות פון) פרקי אבות, וואס אנטהאלטן „מילי דחסי־דותא”²², מוז מען לערנען אז דאס וואס דארט ווערט געזאגט וועגן דעם אוי־בערשטן „שאין לפניו כו׳ ולא משוא פנים ולא מקח שוחד”, קומט ארויס־ברענגען אן ענין שונה, בנוגע צו א שומר תומ״צ, נאר מ׳פארלאנגט פון עם אויך „מילי דחסידותא” —\nאון ווי דער רמב״ם זאגט אין פירוש המשניות שלו²³: „לא יקח שוחד הטובות כמו שיעשה אדם אלף טובות ורעה אחת שלא ימחול הש״י מעבירה ההיא לרוב טובותיו ויחסר לו מאלף טובותיו טובה אחת או יותר אבל יענש על זאת הרעה האחת ויגמלהו על הטובות ההם כולם²⁴. וזהו ענין לא יקח שוחד. והוא כמו לא ישא פנים שיענש הגדול במעלות על דבר מועט כמו שנענש משה רבינו ע״ה . . וגמול עשו הרשע על כבוד אב ואם ונבוכדנאצר על כבוד הש״י . . וזהו ענין ולא משוא פנים”.\nד.ה. אז דער חשבון פון מצות און עבירות איז ניט אין אן אופן פון מסחר וחליפין פון מצות און עבירות און עס ווערט אראפגערעכנט דער שכר פון איין מצוה און דערמיט ווערט פארגעבן דער עונש פאר אן עבירה — נאר יעדער מצוה און יעדער עבירה האבן א באזונדערן שכר ועונש פאר זיך.\nוי״ל מהטעמים אויף דעם: דער גדר פון מצות און עבירות באשטייט ניט (בלויז) אין זייער ווירקונג און אויפטו בנוגע דעם אדם המקיים — נאר דער גדר המצוה איז — קיום רצון העליון, און דער גדר פון אן עבירה איז — עובר אויף רצון העליון; ובמילא איז יעדער מצוה אן ענין לעצמו (וכן בהפכה).\nנאר אין דעם גופא זיינען פאראן צוויי ענינים: „ולא משוא פנים ולא מקח שוחד”: דער חילוק בפשטות צווישן „משוא פנים” און „מקח שוחד” איז — „משוא פנים” מיינט דער וויתור וואס קומט מצד מעלת האדם, און „מקח שוחד” קומט מצד דער חשיבות פון דעם דבר הניתן;\nוי״ל, אז עד״ז איז אויך אין זייער פעולה אויפן דיין: „משוא פנים” טוט אויף, אז דעם מענטשנ׳ס מעלה ווערט ניט געמינערט דורך דער עוולה: ער איז ניט קיין חוטא (מל׳ חסרון); און „שוחד” טוט אויף, אז זיין מעשה בלתי רצוי ווערט „אויסגעקויפט” און אפגעמעקט.\nאון דאס איז די משנה מחדש: דעם מענטשנ׳ס פארבונד²⁵ מיט דעם אוי־בערשטן ווערט ניט „אויסגעגליכן” דורך א מצוה כנגד עבירה, און די עבירה ווערט ניט אפגעמעקט דורך א מצוה.\nדערמיט וועט מען אויך פארשטיין²⁵* וואס דער מדרש²⁶ זאגט אז תשובה איז אן ענין פון „שוחד” („אתה נוטל שוחד מן הרשעים בעוה״ז, תשובה ומע״ט ותפלה (ומסיים) עשו תפלה²⁷ ותשובה”)",[["22","22","ראה ב״ק ל, א."],["23","23","אלא שהוא פירש כן גם בכתוב דידן, וא״כ קשה לכאורה, כנ״ל בפנים, מהו החידוש במשנה. אבל לפרש״י מובן. ולהעיר, שבפירוש רבינו יונה שם מציין לכתוב בדברי הימים ולא לכתוב דידן."],["24","24","להעיר ממדרש משלי רפ״א. ספרי ברכה לג, ו. האזינו לב, ד."],["25","25","כי מצוה — ל׳ צוותא וחיבור (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380272\" data-slug=\"likkutei-torah\" data-id=\"4001380272\">לקו״ת בחוקותי מה, ג</a>. ובכ״מ) ועובר עבירה — בתכלית הפירוד בשעת מעשה (<a class=\"ft-cite\" href=\"#/read/tanya/3401310029\" data-slug=\"tanya\" data-id=\"3401310029\">תניא פכ״ד</a>). 25*) בהבא לקמן — ראה בארוכה יותר לקו״ש חלק לד ע׳ 59 ואילך."],["26","26","מדרש תהלים מזמור יז, ב. יל״ש שם רמז תר״ע."],["27","27","ובמד״ת באבער וביל״ש תהלים רמז תר״ע — ליתא תיבת תפלה."]]],[1300241094,"— ווייל דער אויפטו פון תשובה, איז באין ערוך העכער פון מצות, ובנדו״ד (ניט נאר אין דעם וואס מ׳איז מוותר — דער אדם איז געווארן א בעל תשובה, נאר) וואס זי מאכט אויך איבער דעם מעשה בלתי טוב:\nזי מאכט פון זדונות — שגגות²⁸; נאך מער — זדונות כזכיות²⁹: נאך מער — זדונות כזכיות ממש³⁰.\n(משיחת ש״פ עקב תש״מ)",[["28","28","יומא פו, ב תשובה מיראה."],["29","29","יומא שם תשובה מאהבה."],["30","30","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא ספ״ז</a>. ובארוכה בביאור דרגות אלו — <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171183\" data-slug=\"likkutei-sichot\" data-id=\"1300171183\">לקו״ש חי״ז ע׳ 183</a> ואילך. וש״נ."]]],[1300241095,"<h3>ראה</h3>\nא. וועגן דעם חיוב אז מ׳זאל ברענגען און מקריב זיין קרבנות בלויז אין ביהמ״ק דוקא, און דעם איסור ההקרבה מחוץ למקדש — וואס רעדט זיך בפרשתנו¹ — ווערן אויסגערעכנט אין משנה² (ועד״ז אין ספרי³) די שלבים שבזה: „משהוקם המשכן נאסרו הבמות . . באו לגלגל הותרו הבמות . . באו לשילה נאסרו הבמות ולא הי׳ שם תקרה אלא בית אבנים . . והיא היתה מנוחה. באו לנוב וגבעון הותרו הבמות . . באו לירושלים נאסרו הבמות ולא הי׳ להן [עוד] היתר והיא היתה נחלה״.\nווי ס׳איז מובן מלשון המשנה, איז דער ענין פון „באו לשילה נאסרו הבמות״ פארבונדן דערמיט וואס דארטן איז געווען א „בית אבנים . . והיא היתה מנוחה״⁴ (משא״כ בגלגל לפני זה וואס דעמולט האט מען אויפגעשטעלט דעם אוהל מועד⁵), און ווי דער לשון הרמב״ם⁶ „נקרא שילה בית״⁷.\nדארף מען פארשטיין: עס שטייט מפורש אין פסוק⁸ „כי לא ישבתי בבית למיום העלותי את בנ״י ממצרים ועד היום הזה ואהי׳ מתהלך באוהל ובמשכן״, ד.ה. אז אויך דער משכן שילה ווערט ניט גערעכנט ווי א „בית״ נאר בלויז אלס „אוהל״ (אדער משכן)⁹?\nבפשטות קען מען זאגן, אז עס ווענדט זיך לגבי וואס מ׳רעדט: לגבי דעם אהל מועד — דעם משכן — ווערט שילה גערעכנט אלס בית; משא״כ לגבי דעם ביהמ״ק שבירושלים איז עס בלויז אן אוהל¹⁰.¹¹\nאבער פון דעם וואס מ׳פארבינדט דאס מיט א דין מסוים — איסור הבמות — איז משמע¹¹, אז אויך אין משכן שילה איז פאראן א גדר פון בית, וואס דערפאר „היא היתה מנוחה״.\nב. וי״ל הביאור בזה:\nמ׳געפינט אין תורה דעמזעלבן לשון ביי שילה און דעם ביהמ״ק שבירושלים: אויף „המקום אשר יבחר ה׳״",[["1","1","יב, ד ואילך."],["2","2","זבחים קיב, ב."],["3","3","פרשתנו שם, ח."],["4","4","וראה בגמ׳ שם (קיט, א) „באו לירושלים כו׳ ת״ר כי לא באתם עד עתה אל המנוחה ואל הנחלה כו׳ זו שילה כו׳״. ושם (קיח, א) באו לשילה כו׳ מנה״מ כתוב אחד אומר (ש״א א, כד) ותביאהו בית ה׳ שילה כו׳. ואכ״מ."],["5","5","זבחים קיח, ב. רמב״ם הל׳ בית הבחירה פ״א ה״ב."],["6","6","בפיה״מ זבחים פי״ד מ״ז. וראה לשונו בהל׳ ביהב״ח שם."],["7","7","וממשיך שם: וכן כתוב ותביאהו בית ה׳ שילה כו׳. ואחר שהי׳ שם בנין אז הוא מנוחה לפי שנתיישבו ולא היתה שם נסיעה וה׳ צוה שלא להקריב בבמות לכשתהי׳ שם מנוחה והוא מה שנאמר כי לא באתם עד עתה אל המנוחה ומכאן ראי׳ שבשעה שיגיעו אלי׳ שיהא אסור עליהן להקריב בבמות. וראה הלשון בתרגום קאפח שם."],["8","8","ש״ב ז, ו."],["9","9","ראה ת״י ורש״י שם. וראה זח״ב רמא, א. רמב״ן עה״ת קרח טז, כא."],["10","10","וראה בארוכה ביאור הרי״פ פערלא לסהמ״צ רס״ג מ״ע פד־פה."],["11","11","ואפילו את״ל שהנאמר בשילה ש„היא היתה מנוחה״ הוא רק סימן להזמן שאז נאסרו הבמות, הרי מובן, שהסימן שייך לתוכן הענין. וע״ד הסימן שבירושלמי דלקמן הערה 16."]]],[1300241096,"שטייט אין ספרי¹² „זו שילה ובית עולמים״. וואס דאס געפינט מען ניט בנוגע דעם משכן פריער (און אויך ניט בנוגע דעם „מקדש״¹³ שבנוב וגבעון¹⁴).\nאון ס׳איז מובן בפשטות דער חילוק שביניהם: ווען דער משכן איז געשטאנען במדבר, כאטש אויך דעמולט איז „נאסרו הבמות״, מ׳האט געדארפט מקריב זיין די קרבנות נאר אין משכן — איז דאס אבער ניט געווען דער „מקום אשר יבחר ה׳״, ווארום ער איז דאך ניט געשטאנען אויף איין ארט, נאר געגאנגען ממסע למסע¹⁵. ופשיטא אז מ׳קען דאס ניט זאגן בנוגע די י״ד שנים שכבשו וחלקו (ווען דער משכן איז געווען אין גלגל, ווען ס׳איז ניט געווען די מציאות פון מחנות¹⁶);\nמשא״כ בשילה, וואס דארטן איז חל די הגדרה פון „המקום אשר יבחר ה׳״, ס׳איז געווען א מקום קבוע אויף שס״ט שנה¹⁷. ובמילא איז בזמן שילה געווען דער איסור צו מקריב זיין אין אן אנדער ארט (מחוץ למשכן שילה).\nאון דעריבער האט מען דארט אויפגעשטעלט א בית של אבנים¹⁷* (און ער ווערט אנגערופן בית)¹⁸, ווארום דאס דריקט אויס אן ענין פון קביעות מקום¹⁹.\nג. על פי זה יש לבאר דעם חילוק אין די לימודים בנוגע צו היתר הבמות „כשנכנסו לארץ״ ווען „באו לגלגל״, און היתר הבמות נאכדעם וואס חרב שילה, און „באו לנוב וגבעון״:\nובלשון הרמב״ם²⁰: „לפי שמיום שפסקו המחנות ונכנסו לארץ כו׳ והוא הזמן שבאו לגלגל נסתלקה מצות ל״ת זו ונשאר מותר שכל מי שרוצה להקריב בבמה מקריב כמו שהי׳ קודם המשכן״: דער היתר ההקרבה איז בדרך ממילא,",[["12","12","פרשתנו יד, כה (אלא דהכתוב מדבר (לא בנוגע למקדש עצמו אלא) בנוגע לירושלים). תבוא כו, ב. וראה פרש״י ב״מ פט, א ד״ה נתחייבו. פרש״י פסחים צא, א ד״ה מנין."],["13","13","לשון הרמב״ם הל׳ ביהב״ח שם: ובנו שם מקדש. אבל בדה״ב א, ג־ח וגמרא שם.(קיח, סע״ב), פיה״מ שם מ״ז (שהקימו בנוב וגבעון) אה״מ שנעשה במדבר. ואכ״מ."],["14","14","וראה רמב״ן תבוא שם. ביאור הרי״פ פערלא שם. ועוד."],["15","15","ובלשון הרמב״ם ריש הל׳ ביהב״ח „והי׳ לפי שעה״. ועיי״ש ברמב״ם שמביא ע״ז „שנאמר (פרשתנו יב, ט) כי לא באתם עד עתה וגו׳״. שהכתוב ממשיך „אל המנוחה ואל הנחלה״ שקאי על שילה וירושלים (ספרי וגמרא שם קיט, א), והיינו שגם בנוגע להמשכן (ביחס לשילה) נאמר כי לא באתם עד עתה גו׳ (אבל ברש״י עה״פ פי׳ „כי לא באתם — כל אותם י״ד שנה״). וראה לקמן בפנים סעיף ג."],["16","16","ראה פיה״מ להרמב״ם זבחים שם מ״ה (נעתק — חלקו — לקמן ס״ג). אבל בירושלמי מגילה פ״א הי״ב: זה סימן כל זמן שהארון בפנים הבמות אסורות יצא הבמות מותרות. וראה בארוכה מאירי מגילה ס, ב. ואכ״מ."],["17","17","זבחים קיח, ב. רמב״ם הל׳ ביהב״ח שם. — משא״כ ימי נוב וגבעון (רק) נ״ז שנה (זבחים ורמב״ם שם). ובפרט שנק׳ „במה״ (דה״א סז, לט. כא, כט. דה״ב א, ג. שם, יג), „במה גדולה״ (מ״א ג, ד. תוספתא זבחים ספי״ג). 17*) אבל להעיר מדעת הרמב״ם (דלעיל הערה 13) שגם בנו״ג בנו מקדש, דמשמע בנין אבנים (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161304\" data-slug=\"likkutei-sichot\" data-id=\"1300161304\">לקו״ש חט״ז ע׳ 304</a> הערה 47. וש״נ)."],["18","18","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161305\" data-slug=\"likkutei-sichot\" data-id=\"1300161305\">לקו״ש שם ע׳ 305</a> ואילך, שגם בנוגע לג׳ מצוות שנצטוו ישראל בשעת כניסתן לארץ (וסדרן) למנות להם מלך ולהכרית זרעו של עמלק ולבנות להם בית הבחירה (סנהדרין כ, ב וספרי עה״פ. רמב״ם ריש הל׳ מלכים) קיימו (גם) במשכן שילה (אף דהשלימות בזה היתה — בבית הבחירה בירושלים). שלכן לא הביא הרמב״ם בהל׳ מלכים שם הכתוב שבו מפורש בית הבחירה כ״א הכתוב „לשכנו תדרשו״ (פרשתנו יב, ה), שלכמה פי׳ נאמר בשילה (ראה לח״מ שם). וראה לקמן הערה 32."],["19","19","ראה מהרש״א לתוס׳ שבועות טו, א ד״ה אין העזרה."],["20","20","פיה״מ זבחים שם. וראה הלשון בתרגום קאפח."]]],[1300241097,"וויבאלד ס׳איז ניטא קיין מחנות און ס׳איז פונקט ווי פריער, פאר הקמת המשכן²¹.\nמשא״כ דער היתר ההקרבה בבמה נאך דעם זמן פון משכן שילה, דארף מען דערויף האבן א לימוד מיוחד, ווי מ׳לערנט עס אפ²² פון דעם פסוק²³ „כי לא באתם עד עתה אל המנוחה ואל הנחלה — אל המנוחה זו שילה נחלה זו ירושלים, למה חלקן [הכתוב] כדי ליתן היתר בין זה לזה״: מ׳דארף האבן א היתר מיוחד אויף דעם.\nאון ווי ס׳איז משמע פון דעם לשון „ליתן היתר בין זה לזה״, איז די קס״ד צו אסר׳ן במות (וואס דער לימוד איז שולל) איז [ניט ווייל דער משכן איז געווען בנוב וגבעון און עס זיינען געווען מחנות, נאר] ווייל מ׳וואלט געמיינט אז „משבאו לשילה״ איז בטל געווארן כללות ענין הבמות (און דערויף איז דער פסוק מחדש און גיט א „היתר בין זה לזה״²⁴). און אזוי איז אויך מובן פון לשון רש״י בפירושו על הש״ס²⁵: „מנוחת״מ שהי׳ היתר לבמות אחר קדושת שילה משחרבה״.\nולכאורה: פארוואס זאל מען זאגן אז „משבאו לשילה״ איז אינגאנצן בטל געווארן ענין הבמות?\nנאר דערפון איז מוכח, אז אין שילה האט זיך אויפגעטאן אן ענין פון קביעות מקום (וואס איז פריער ניט געווען) — „המקום אשר יבחר ה׳״²⁶, האט דאס מבטל געווען דעם ענין הבמות²⁷, נאר דערנאך איז געקומען א לימוד מיוחד „ליתן היתר בין זה לזה״.\nד. עפ״ז דארף מען אבער פארשטיין: וויבאלד אז אויך בנוגע לשילה שטייט דער לשון „המקום אשר יבחר ה׳״, פארוואס ווערט דוקא ביהמ״ק שבירושלים אנגערופן „בית הבחירה״, און ניט דער משכן שבשילה?\nמוז מען זאגן, אז כאטש אויך שילה ווערט אנגערופן „מקום אשר יבחר ה׳״, איז אבער פאראן א חילוק אין דער בחירה צווישן שילה און ירושלים.\nוועט מען דאס פארשטיין בהקדים די חילוקי הלשונות בפרשתנו בנוגע דעם חיוב ההקרבה בבית.\nפריער שטייט אין פסוק²⁸ „לא תעשון כן לה״א (וואס דאס מיינט — כפירוש רש״י: להקטיר לשמים בכל מקום), כי אם אל המקום אשר יבחר ה״א גו׳ לשכנו תדרשו ובאת שמה והבאתם שמה עולותיכם גו׳״: דערנאך שטייט²⁹ „ועברתם את הירדן גו׳ והניח לכם גו׳ והי׳ המקום אשר יבחר ה״א בו לשכן שמו שם שמה תביאו את כל אשר אנכי מצוה גו׳״. און מען איז מבאר אין ספרי, און רש״י ברענגט עס בפירושו על התורה³⁰, אז דער ערשטער פסוק איז „אמור לענין שילה״ און דער צווייטער — „אמור לענין ירושלים״³¹.",[["21","21","אבל ראה רש״י במשנה שם ד״ה הותרו. פרש״י פרשתנו יב, ח דלמדין היתר הבמות בגלגל מהכתוב (שם) (לא תעשון גו׳) איש כל הישר בעיניו."],["22","22","זבחים קיט, א."],["23","23","פרשתנו יב, ט."],["24","24","וראה הלשון בפיה״מ להרמב״ם שם מ״ז."],["25","25","זבחים שם."],["26","26","להעיר מפרש״י קידושין לז, א ד״ה ללמדך."],["27","27","ולהעיר מפירוש רבי חיים בתוס׳ ד״ה מאי קסבר זבחים (ס, ב) דלרש״י דקאמר זה וזה שילה אתא לאשמעינן דשילה אין אחרי׳ היתר."],["28","28","יב, ד ואילך."],["29","29","שם, יו״ד ואילך."],["30","30","שם, יא."],["31","31","לשון רש״י שם. בספרי זה בא בהמשך להדרשה על „מבחר נדריכם״ שבהפסוק, ובפרש״י כתבו בד״ה „שמה תביאו״. אבל מובן שגם בספרי הכוונה לעצם המצוה דהבאת קרבנות."]]],[1300241098,"זעט מען נאך א חילוק אין די פסוקים: אין דעם ערשטן פסוק איז די (התחלה) הדגשה אויפן מענטשן, דעם גברא, „והבאתם שמה עולותיכם גו׳״, משא״כ אין צווייטן פסוק איז די (התחלה) הדגשה אויף דעם מקום „שמה תביאו את כל אשר אנכי מצוה אתכם גו׳״.\nוי״ל אז דאס איז פארבונדן מיט א חילוק כללי צווישן די פסוקים:\nאין די ערשטע פסוקים הויבט אן די תורה מיטן איסור „לא תעשון כן לה׳ אלקיכם״ — „להקטיר לשמים בכל מקום״, און ווי א המשך (און תוצאה) פון דעם איסור קומט דער חיוב: „כי אם אל המקום גו׳״³², דאס מיינט, אז אין דעם ענין הבחירה במקום מיוחד זה איז מודגש אז דערמיט ווערט באווארנט דער איסור פון מקריב זיין קרבנות „בכל מקום״ — נאר בלויז אין איין ארט וואס וועט זיין אויסגעטיילט ע״י בחירתו ית׳;\nמשא״כ אין דעם צווייטן פסוק איז די התחלה מיטן חיוב — „והי׳ המקום אשר יבחר ה״א בו לשכן שמו שם שמה תביאו גו׳״, וואס דאס הייסט, אדרבה, אז דער „שמה תביאו״ איז א תוצאה דערפון וואס דאס איז דער „מקום אשר יבחר ה״א בו״.\nה. דערפון איז מובן, אז אין הכי נמי, אויך ביי שילה איז געווען דער ענין הבחירה: אבער אין דעם תוכן הבחירה איז א חילוק עיקרי צווישן שילה און ירושלים:\nביי שילה איז געווען די בחירה אין דעם מקום, נאר בלויז ווי א תוצאה פון דעם איסור „להקטיר לשמים בכל מקום״, וואס דערפאר האט געמוזט זיין א מקום מיוחד להקרבה, ד.ה. א בחירה (במקום) מצד א טעם וסיבה;\nמשא״כ אין ירושלים איז דאס דער ארט וואס דער אויבערשטער האט בוחר געווען (ניט מצד א טעם³³, נאר) אז דאס זאל זיין מקום השראת שכינתו ית׳ — ובמילא איז דאס אויך דער מקום וואו עס דארף זיין הקרבת הקרבנות („שמה תביאו״)³⁴.\nבסגנון אחר: די בחירה אין שילה איז געווען צוליב אידן³⁵, אז זיי זאלן האבן א",[["33","33","להעיר דגם כפשוטו, בזמן (דוד) שלמה שבנו בית הבחירה הי׳ מקדש ב(נוב ו)גבעון (לא רק משכן כבגלגל). אלא שאז היו הבמות מותרות. ודין במה גדולה להם (ראה מ״א ג, ד ובפרש״י שם. דה״ב א, ג־ה. מאירי מגילה ט, ב. ובכ״מ). ואכ״מ."],["34","34","החילוק בין שילה וירושלים יש לבאר גם באופן אחר קצת: בשילה בחירת המקום להקרבה הוא (בעיקר) שלילה דשאר המקומות, שלא יקטירו בכל מקום (לא תעשון כן גו׳ כי אם אל המקום גו׳). [היפך מבמשכן — ע״פ פשטות הכתוב בפ׳ אחרי (יז, ה) בטעם האיסור דשחוטי חוץ ומצות הבאתם במשכן — „למען אשר יביאו בנ״י את זבחיהם אשר הם זובחים על פני השדה והביאום לה׳ גו׳״. ראה ראב״ע שם. פיה״מ להרמב״ם זבחים שם מ״ה. וראה רש״י זבחים קיב, ב ד״ה בעשה דמפרש העשה מהכתוב הנ״ל „והביאום לה׳ גו׳״]: משא״כ בירושלים (כמו במשכן) בחירת המקום הוא (בעיקר) חיוב ובחירת מקום זה בשביל הקרבה. אבל מפשטות הכתוב בנוגע להמקדש בירושלים „והי׳ המקום אשר יבחר ה׳ לשכן שמו שם״ משמע, דהבחירה היא כדי שיהי׳ מקום לשכן גו׳ וכתוצאה מזה „שמה תביאו גו׳״, כבפנים. וראה לקמן הערה 45. משא״כ בשילה (אף שגם שם ממשיך „לשום את שמו שם״, הרי כיון שההתחלה היא בנוגע להקרבה — „לא תעשון כן כי אם אל המקום גו׳״, משמע דהבחירה היא מצד ההקרבה, כנ״ל בפנים."],["35","35","להעיר משפתי חכמים בפרש״י פרשתנו יב, יג."],["32","32","ראה גו״א בפרש״י (שם, ה) דכל הפסוק „כי אם אל המקום אשר יבחר גו׳״ קאי על שילה. ועד״ז בגו״א שם, יד. אבל ראה רא״ם ושפ״ח (ועוד) בפרש״י בפסוקים הנ״ל."]]],[1300241099,"מקום מיוחד להקרבה (און ניט — בכל מקום, ווי עס איז געווען פריער, היתר הבמות); משא״כ די בחירה אין ירושלים איז געווען מצד דעם אויבערשטן כביכול, אז הוא ית׳ האט כביכול בוחר געווען אן ארט לשכינתו — „זאת מנוחתי עדי עד״³⁶.\nו. מצד דעם אונטערשייד אין דעם אופן הבחירה צווישן שילה וירושלים — איז אויך פאראן א חילוק בשייכות דעם ענין הנבחר:\nוויבאלד אז די בחירה בשילה איז כדי עס זאל זיין אן ארט מיוחד להקרבה, ווערט עס באווארנט, עס איז גענוג ווען די בחירה איז אין דעם מקום (הבית אבער ניט אין דעם בית שנבנה עליו):\nמשא״כ בירושלים, איז דאס א בחירה מצ״ע (אן א טעם המגביל) אין דעם ענין, איז דאס כולל סיי דעם מקום (הבית), סיי דעם בית. ואדרבא וויבאלד אז דאס איז א זאך וואס דער אויבערשטער, די שכינה האט בוחר געווען למנוחתו „עדי עד״, איז מובן, אז די מנוחה בפועל ווערט דורך דעם בית, דער בית גופא איז א „בית הבחירה״³⁷.\nוואס דאס איז אויך מודגש אין די שינויי הלשונות אין די פסוקים הנ״ל:\nבנוגע צו שילה זאגט דער פסוק „המקום אשר יבחר ה״א גו׳ לשום את שמו שם״, אבער בשייכות צו ירושלים איז דער לשון הכתוב „אשר יבחר ה״א בו לשכן שמו שם״³⁸: ביי שילה איז די בחירה ניט „בו״ (אין דעם מקום³⁸*) נאר אין „לשום את שמו״³⁹, משא״כ ביי ירושלים, איז דער „יבחר ה״א״ — „בו״, אין דעם מקום³⁹.\nז. עפ״ז איז פארשטאנדיק וואס דער רמב״ם רופט די הלכות — „הלכות בית הבחירה״ —\n[כאטש אז אין דער התחלה — כותרת פון הלכות בית הבחירה, וואו עס ווערן אויסגערעכנט די מצוות וועלכע זיינען אין די הלכות⁴⁰, זאגט דער רמב״ם אז די ערשטע מצוה איז „לבנות בית המקדש״ (און ניט „בית הבחירה״). ועד״ז אין די הלכות גופא, גלייך אין דער ערשטער הלכה, ברענגט ער דעם פסוק⁴¹ „ועשו לי מקדש״ (און ניט דעם פסוק⁴² וואו עס",[["36","36","תהלים קלב, יד."],["37","37","ועפכ״ז אולי יש לבאר ולתווך מה שבכ״מ מפורש דאין שילה בכלל המקום אשר יבחר ה׳ — ראה ספרי פרשתנו (יב, יח) לפני ה׳ זו שילה, במקום אשר יבחר זו ירושלים [אבל שם י״ל כיון דכל הרואה בשילה דשם נאכל קק״ל (מגילה ט, סע״ב. זבחים קיב, ב) אינו המקום אשר יבחר כירושלים שבו נאמר ענין הבחירה בפ״ע (כפרשתנו שם. ושם יד, כג ואילך. וראה זבחים קטז, סע״ב ואילך. שפת אמת שם)]. רד״ק (מ״א ח, יג) — כיון דלא הוי (גם) בהבנין א״כ אי״ז אמיתית ענין הבחירה גם בהמקום (כדלקמן הערה 38*). אבל לכאור׳ לא משמע כן מלשון הרד״ק שם „גלגל ושילה ונוב וגבעון . . לא היו הם המקום הנבחר כו׳ כי אם זה המקום שהוא הר המורי׳ כו׳״. וראה רמב״ן פרשתנו טז, ט. פנים יפות ס״פ פנחס."],["38","38","ראה כלי יקר פרשתנו יב, ד „המפרשים אמרו״ (אלא שלדעתו אינו כן). 38*) כי שלימות הבחירה בהמקום הוא כאשר ישנה הבחירה (גם) בהבית (שבמקום זה). ומכיון שבשילה לא היתה בחירה בהבית, מובן שאי״ז בחירה בשלימותה (גם) דהמקום. וכנ״ל הערה 37."],["39","39","ואולי י״ל עוד חילוק: לשום — שייך גם לרגע, ארעי: לשכן — משמעותו קביעות."],["40","40","שגם זה הוא מהרמב״ם — וראה הקדמתו לספרו."],["41","41","תרומה כה, ח."],["42","42","כהובא בסנהדרין שם וספרי עה״פ. וכמו שכתב הסמ״ג מ״ע קסג וברמזי מ״ע שם. וראה כס״מ ריש הל׳ ביהב״ח. נ״כ הרמב״ם ריש הל׳ מלכים. ובארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161298\" data-slug=\"likkutei-sichot\" data-id=\"1300161298\">לקו״ש חט״ז ע׳ 298</a> ואילך."]]],[1300241100,"שטייט דער לשון פון „בחירה״⁴³): נאך מער: די ווייטערדיקע הלכות בשייכות צום ביהמ״ק רופט ער טאקע אן מיטן נאמען „מקדש״ — „כלי המקדש״, „ביאת מקדש״]\nדערמיט איז מודגש אז דער עיקר חידוש אין דעם ביהמ״ק בירושלים „בית עולמים״, איז בחירת הקב״ה⁴⁴.\nוואס דאס דריקט זיך אויס אויך אין דעם וואס (אויך) דער בית איז א „בית הבחירה״⁴⁵.\nח. ע״פ כל הנ״ל קען מען אויך מבאר זיין דעם לשון הרמב״ם⁴⁶ „כיון שנבנה המקדש בירושלים נאסרו כל המקומות כולן לבנות בהן בית⁴⁷ לה׳ כו׳״ — דלכאורה:\nוויבאלד אז דער עיקר אויפטו אינעם בית עולמים איז דער ענין הבחירה, האט דער רמב״ם געדארפט זאגן „כיון שנבחר בית עולמים״? נאכמער: אין מכילתא⁴⁸ שטייט טאקע אזוי דער לשון „עד שלא נבחרה ירושלים כו׳ עד שלא נבחר בית עולמים כו׳״ — און דער רמב״ם איז משנה פון לשון המכילתא און זאגט „כיון שנבנה המקדש״?\nוע״פ הנ״ל י״ל, אז ס׳זיינען דא צוויי פרטים אין דער בחירה במקדש שבירושלים, יעדערער אין זיין זמן:\nדי בחירה במקום המקדש, שבהר המורי׳, וואס דאס איז געווען⁴⁹ מימי האבות⁵⁰\n[וואס דערפאר איז דאס געווען דער „מקום שבנה בו אברהם המזבח ועקד",[["43","43","וכן לשונו במנין המצות בריש ספר היד מ״ע כ. סהמ״צ שם (לפנינו. אבל בתרגום העליר וקאפח: בית עבודה)."],["44","44","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191143\" data-slug=\"likkutei-sichot\" data-id=\"1300191143\">לקו״ש חי״ט ע׳ 143</a> ואילך. וש״נ. וראה שיחת ש״פ מטו״מ תשמ״ב."],["45","45","לכאורה י״ל שלדעת הרמב״ם פי׳ „בית הבחירה״ היינו — בית הנבחר להקרבת הקרבנות (כדלעיל הערה 34). וכמוש״כ בסהמ״צ מ״ע כ דהמ״ע היא „לבנות בית הבחירה לעבודה בו יהי׳ ההקרבה״ (וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111128\" data-slug=\"likkutei-sichot\" data-id=\"1300111128\">לקו״ש חי״א ע׳ 120</a> ואילך). וראה רמב״ם הל׳ יסוה״ת פ״ט ה״ג „ירושלים נבחרת לכך״. אבל מדיוק לשונו בספר היד* ריש הל׳ ביהב״ח בגדר המ״ע „לעשות בית לה׳ מוכן להיות מקריבים בו קרבנות״, שהבית והמצוה בבנייתו אינו בשביל ההקרבה כ״א „בית לה׳״ (והיינו להשראת השכינה). אלא שהבית צ״ל באופן ש„מוכן להיות מקריבים בו הקרבנות״ (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041345\" data-slug=\"likkutei-sichot\" data-id=\"1300041345\">לקו״ש ח״ד ע׳ 1346</a> והערה 34). וכן מוכח מלשונו שם ה״ג (נעתק לקמן ס״ח) „נאסרו כל המקומות כולן לבנות בהן בית לה׳״ ומביא הכתובים (דה״א כב, א. תהלים קלב, יד) „זה הוא בית ה׳ האלקים . . זאת מנוחתי עדי עד״. כדלקמן בפנים."],["46","46","הל׳ בית הבחירה פ״א ה״ג."],["47","47","ידועה השקו״ט באחרונים „דלבנות בהן בית כו׳ ואין שם ביה״ק משמע דלא נאסרו במות! (ראה מעשי למלך על אתר). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161479\" data-slug=\"likkutei-sichot\" data-id=\"1300161479\">לקו״ש חט״ז ע׳ 466</a> הערה 12, די״ל דההמשך ברמב״ם „ולהקריב בהן קרבן״ — „בהן״ (בהמקומות) ולא „בו״ (בהבית) — מורה שמוסיף ענין שני, איסור הקרבה (במק״א) בבמות. ע״ש."],["48","48","בא בתחלתה."],["49","49","ולשון המכילתא „עד שלא נבחרה ירושלים כו׳ עד שלא נבחרה בית עולמים כו׳״ היינו הבחירה בפועל למזבחות ולהשראת השכינה כההמשך במכילתא „יצאת א״י כו׳ יצאת ירושלים״. וראה מפרשי המכילתא. וכמה גירסאות בהמכילתא שם ובפירושה."],["50","50","וע״ד הבחירה בא״י כשהיתה „כשברא העולם כו׳ בחר בא״י״ (תנחומא פרשתנו ח) — ראה לקו״ש חי״ח ע׳ 402. *) שכתבו בלה״ק, משא״כ סהמ״צ שכתבו בערבית. ובידנו רק העתקות — וצ״ע פי׳ התיבה בערבית בדיוק ואין ללמוד מפי׳ התיבה עתה — כי כידוע דיוק פי׳ התיבות בכל לשון — משתנה במשך הזמן. ולהעיר מהכלל אפילו בלה״ק — ל׳ תורה לחוד ול׳ חכמים לחוד. ועוד שספר היד הוא: א) פסקי הלכות, ב) בתראי לגבי סהמ״צ (יד מלאכי כללי הרמב״ם אות כג)."]]],[1300241101,"עליו יצחק והוא המקום שבנה בו נח כו׳״, ווי דער רמב״ם איז מבאר אין פ״ב⁵¹]:\nאון די בחירה אין דעם בית גופא, וואס דאס האט זיך אויפגעטאן ווען „נבנה המקדש בירושלים״ (און דעמולט איז אויך נתוסף געווארן די שלימות הבחירה אויך פון דעם מקום), וואס דערפאר איז דוקא דאן „נאסרו כל המקומות כולן לבנות בהן בית לה׳״.\nדערמיט איז אויך מבואר פארוואס דער רמב״ם ברענגט אויף דעם ראיות פון די פסוקים⁵² — „ויאמר⁵³ דוד זה הוא בית ה׳ האלקים וזה מזבח לעולה לישראל״, וואס דאס ברענגט ארויס ווי די בחירה איז (ניט נאר אין מקום המקדש נאר אויך) אין דעם בית גופא: „ואומר זאת מנוחתי עדי עד״, וואס אין דעם צווייטן פסוק איז מוסבר דער טעם אויף דעם וואס די בחירה איז (אויך) אין בית — היות אז דער אויבערשטער האט בוחר געווען (ניט צוליב א טעם ותפקיד מיוחד מקום להקרבה, נאר) אלס „זאת מנוחתי עדי עד״ — איז במילא די בחירה אין דעם בית גופא⁵⁴.\nט. עפ״ז איז אויך מובן דער חילוק הנ״ל (ס״ד) וואס בנוגע צו שילה שטייט „והבאתם (שמה)״, די תורה הויבט אן מיטן חיוב ההבאה של האדם (און דאס ברענגט אז עס איז דא א „שמה״), און באַ ירושלים איז די התחלה „שמה (תביאו)״ (ובמילא דארף אהין זיין דער „תביאו״):\nדער חיוב צו מקריב זיין קרבנות בשילה דוקא (בזמן משכן שילה) איז „חיוב גברא״: אזוי ווי אידן זיינען מצווה להקריב קרבנות און דערנאך איז צוגעקומען אין דעם חיוב אז עס זאל זיין אין א מקום מיוחד — האט דער אויבערשטער פאר זיי אויסגעקליבן (משכן) שילה אלס דעם מקום ההקרבה⁵⁵. (און בדוקא — עס ווערט חל אויף זיי א איסור צו מקריב זיין מחוץ לשילה⁵⁶);\nמשא״כ בירושלים, וואס דער ענין הבחירה איז מצ״ע און אין א חפצא אינעם בית — „בית הבחירה״, איז י״ל אז די מצות ההקרבה דארטן — „להקריב כל הקרבנות בבית הבחירה״⁵⁷ — איז אויך מצד דעם „חפצא״ פון קרבן.\nועפ״ז יומתק דער לשון הרמב״ם אין ספר היד⁵⁸, ביי דער מצות ההקרבה בבית הבחירה, וואו ער הויבט אן די הלכות ניט מיט דעם חיוב האדם „מצות עשה להקריב כל הקרבנות בבית הבחירה״, נאר מיט די קרבנות: „כל הקרבנות כולם כו׳ מצות עשה להקריבן בבית הבחירה״, וואס דערפון איז",[["55","55","ולפי כהנ״ל י״ל שג״ז נלמד מהיתר הקרבה בבמה לאחר שילה (כנ״ל ס״ג) שאין זה מקום מנוחת השכינה בקביעות. כנ״ל בארוכה."],["56","56","וראה לעיל הערה 34."],["57","57","לשון הרמב״ם במנין המצות בריש ספר היד, מ״ע פד. ועד״ז בהכותרת להל׳ מעשה הקרבנות מצוה כא."],["58","58","הל׳ מעה״ק רפי״ח."],["51","51","הל׳ ביהב״ח ה״א וה״ב. וראה לקו״ש חי״ט שם."],["52","52","ראה גם לקו״ש חי״ט שם הערה 47. לקו״ש חט״ז שם."],["53","53","דה״א כב, א."],["54","54","ולכן נקרא „בית עולמים״, הבית גופא (אף שהבית עצמו נחרב). ובלשון הרמב״ם (הל׳ ביהב״ח פ״ז ה״י) „לפי שקדושת המקדש וירושלים מפני השכינה ושכינה אינה בטילה והרי הוא אומר כו׳ אע״פ ששוממין בקדושתן הן עומדים״ — הבית לא רק המקום. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111185\" data-slug=\"likkutei-sichot\" data-id=\"1300111185\">לקו״ש חי״א ע׳ 177</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161480\" data-slug=\"likkutei-sichot\" data-id=\"1300161480\">חט״ז ס״ע 467</a> ואילך."]]],[1300241102,"משמע, אז דער חיוב צו מקריב זיין די קרבנות דוקא דארט איז (ניט נאר א תנאי אין אופן ההקרבה מצד דעם מקריב — גברא, נאר) אויך⁵⁹ מצד די קרבנות, חפצא.\nויש לומר אז דאס איז מצד דעם טעם הנ״ל: וויבאלד אז עס איז דא א בית הבחירה, א מקום השכינה, ברענגט עס אויך א חיוב אויף דער חפצא פון די קרבנות, אז מ׳דארף זיי מקריב זיין אין דעם בית.\n(משיחות ש״פ מטו״מ וש״פ ראה תש״מ; ש״פ דברים תשמ״ב)",[["59","59","בפיה״מ להרמב״ם שם מ״ט הביא הכתוב (יא) „שמה תביאו גו׳״ שבפסוק „והי׳ המקום אשר יבחר ה״א בו גו׳״. אבל גם בהפסוק (יד) שהביא בהל׳ מעה״ק שם, ובסהמ״צ ומנין המצות שם, נאמר „שם תעלה עולותיך ושם תעשה״, ולא כבשילה „והבאתם שמה גו׳״ (כנ״ל)."]]],[1300241103,"<h3>ראה ב</h3>\nא. אויף מצות הענקה (לעבד עברי ולאמה עברי׳) זאגט דער פסוק¹ דעם טעם: „וזכרת כי עבד היית בארץ מצרים ויפדך ה׳ אלקיך, על כן אנכי מצוך את הדבר הזה היום“.\nשטייט אויף דעם אין ספרי²: „וזכרת כי עבד היית בארץ מצרים — הענקתי³ לך ושניתי לך, אף אתה הענק לו ושנה לו⁴: מה במצרים נתתי לך ברוחב יד אף אתה תתן לו ברוחב יד. וכן הוא אומר⁵ אם תשכבון בין שפתים כנפי יונה נחפה בכסף זו ביזת מצרים, ואברותי׳ בירקרק חרוץ זו ביזת הים; תורי⁶ זהב נעשה לך זו ביזת הים, עם נקודות הכסף זו ביזת מצרים“⁷.\nד.ה.⁸ דער פסוק „וזכרת כי עבד היית בארץ מצרים ויפדך ה״א“ מיינט צו זאגן,\nאז וויבאלד דער אויבערשטער האט אויסגעלייזט די אידן פון מצרים און האט זיי דערביי געגעבן א (צווייענ־דיקע) „הענקה“: („ביזת מצרים“ און „ביזת הים“) — „על כן אנכי מצוך את הדבר הזה“ — די מצוה פון הענקה צו אן ע״ע און אמה עברי׳.\nלפי זה איז שווער⁹: עיקר חסר אין פסוק? — וועגן דעם עיקר, דער הענקה ביי יצי״מ ווערט דא אינגאנצן ניט דערמאנט?\nב. וועט מען דאס פארשטיין בהקדם הביאור אין דברי הספרי הנ״ל בפרטי ההלכה. ובהקדמה:\nוויבאלד מען לערנט אפ דערפון (פון אופן יצי״מ) דעם דין הענקה ובפרטיו „אף אתה הענק לו ושנה לו וכו׳“ איז מובן, אז ביזת מצרים וביזת הים זיינען ענין „הענקה“ ממש, און ניט סתם א נתינה לעבד ביציאתו מעבדות —\nאיז תמוה¹⁰:\nא) דין¹¹ הענקה איז דוקא מיט זאכן וואס זיינען „בכלל ברכה“ (נאר זאכן וואס קענען זיך מערן וכיו״ב), אבער ניט מיט כספים וכו׳¹² — און ביזת מצרים",[["1","1","פרשתנו טו, טו."],["2","2","כ״ה בדפוס ראשון. ויש כמה שינויי נוסחאות בדפוסים אחרים. ואכ״מ."],["3","3","וצ״ע למה הובאו מהפסוק תיבות אלו דוקא (ועד״ז בפרש״י), ולא העיקר — „ויפדך גו׳“."],["4","4","ראה פירוש רש״י על הפסוק."],["5","5","תהלים סח, יד."],["6","6","שה״ש א, יא. ולהעיר שמב׳ פסוקים אלה מביאים ראי׳ (מכילתא בא יב, לו. ועוד) שביזת הים גדולה מביזת מצרים."],["7","7","בפירוש דברי הספרי — ראה ספרי דבי רב כאן. מנ״ח (מצוה תפב — והביא רק מרש״י). שו״ת צפע״נ דווינסק ח״ב סי׳א (הובא בצפע״נ עה״ת כאן). צפע״נ עה״ת שמות ג, כב. וראה גם צפע״נ עה״ת וארא ו, יג. צפע״נ לסנהדרין צא, א. פנים יפות ותו״ת כאן. ולהעיר שלא הובאו דברי הספרי בפוסקים. וראה לקמן בפנים."],["8","8","ראה גם רשב״ם וספורנו כאן."],["9","9","ראה גם אלשיך כאן (קושיא ו). וראה הכתב והקבלה כאן."],["10","10","ראה פרשת דרכים דרך מצרים דרוש ה. תולדות אדם ומלבי״ם לספרי כאן. צפע״נ שם."],["11","11","קידושין יז, א. ספרי פרשתנו טו, יד."],["12","12","ואף שהיא מחלוקת התנאים (קידושין וספרי שם. וראה צפע״נ שם, דמשמע שדעתו שדרשה זו בספרי היא למ״ד שיש הענקה מכספים), הרי נתנו"]]],[1300241104,"וביזת הים איז בעיקר באשטאנען פון כסף וזהב ובגדים¹³ (כמפורש בכמה פסוקים¹⁴ און מדרשי חז״ל¹⁵).\nב) ביי אן עבד הנמכר לעכו״ם איז בכלל ניטא קיין דין הענקה — היינט ווי קען מען זאגן אז די ביזה וואס אידן האבן באקומען פון די מצרים זאל האבן א גדר פון הענקה?\nג) דער חיוב פון הענקה איז אויפן אדון — און דא אין ספרי איז ער מדגיש, אז די הענקה ביי יצי״מ איז געווען פון דעם אויבערשטן (וואס האט געמאכט¹⁶ אז די מצרים זאלן געבן¹⁷ אידן די כלי כסף כו׳) — „הענקתי . . ושניתי . . נתתי“¹⁸?\nג. כשם ווי מיר געפינען, לויטן ספרי, אז אידן האבן באקומען הענקה בצאתם ממצרים, עד״ז שטייט אויך בנוגע יוסף׳ן, וואס איז געווען אן עבד ביי פוטיפר, אז ארויסגייענדיק לחירות האט ער באקומען הענקה, ווי דער טאטע איז מבאר אין זיינע רשימות אויף מס׳ קידושין (אין דער סוגיא פון הענקה), וז״ל¹⁹:\n„יוסף שהי׳ מתחלה עבד עברי כמ״ש²⁰ ושם אתנו נער עברי עבד, הנה כשיצא לחפשי ולחירות צריך לתת לו הענקה, וההענקה שניתן לו, מלבד זה מה שנתן לו פרעה הטבעת ורביד הזהב .. ובגדי שש²¹ . . הנה עיקר ההענקה הוא מה שנתן לו הקב״ה, והוא מה ששלח את גבריאל ולמדו ע׳ לשון²² . . ואל תקשי הרי הענקה צריך להיות מהאדון שהי׳ עבד לו . . י״ל מפוטיפר הי׳ ג״כ הענקה, והוא מה שניתן²³ לו בתו אסנת“²⁴.",[["12","12","להם כלים דלכו״ע אינם בכלל ברכה*. ועוד, הרי מרא דשמעתא דממעטים כספים הוא ר״ש, ו„סתם ספרי ר״ש“ (סנהדרין פו, א. וש״נ)."],["13","13","בפרשת דרכים שם (הובא גם במלבי״ם), שהכספים כו׳ היו בתור תשלום על עבודתם, וההענקה היא ה„מקנה כבד מאד“, ומביא ראי׳ ע״ז מ„מה שאמרו בספרי“ (ונראה שכוונתו למכילתא) על הפסוק (בא יב, לח) „מקנה כבד מאד — כאן נתקיים ואחרי כן יצאו ברכוש גדול“. אבל במכילתא שלפנינו, לכאורה יש לדייק להיפך, ממה שמסיים „עם יציאתן ממצרים אני ממלאן כסף וזהב“. וראה גם מדרש הגדול כאן: הענקתי לכם כסף וזהב ואבנים טובות ומרגליות אף אתה כו׳. וראה גם בעה״ט כאן (טו, יד)."],["14","14","שמות ג, כב. בא יא, ב. יב, לה. וראה צפע״נ דלעיל הערה 7."],["15","15","ראה פרש״י בשלח טו, כב. ובכ״מ."],["16","16","כמש״נ ויתן ה׳ את חן גו׳ לקיים הבטחתו ואחרי כן יצאו ברכוש גדול (בא יא, ג ובפרש״י שם). וציווה להים שיפלוט המצרים על שפתו (פסחים קיח, ב. ערכין טו, א)."],["17","17","כמובן מפשטות הכתובים שהי׳ באופן דונצלחם את מצרים (משא״כ הלוואה לזמן — ה״ז רק דדברים הנצרכים לאיזה ענין הנדרש באותו הזמן). וכמפורש ברשב״ם עה״ת (שמות ג, כב. בא יא, ב. יב, לו), ספר השרשים לר״י אבן ג׳נאח (שרש שאל), בחיי בשם הר״ח, חזקוני וכלי יקר (שמות שם — שהנתינה היתה במתנה. והטענה „תנו לנו כסף וזהב שנטלתם ממנו“ (סנהדרין צא, א) — ה״ז טענת המצרים, וגם מענת גביהא בן פסיסא היו שאפילו לפי שיטתם אדרבה חייבים הם לבנ״י. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211012\" data-slug=\"likkutei-sichot\" data-id=\"1300211012\">לקו״ש חכ״א ע׳ 12</a> ואילך."],["18","18","ואף שלכמה דעות (ראה אנציקלופדי׳ תלמודית ערך הענקה ע׳ תרעה. וש״נ) כופין על הענקה, מ״מ צריך ביאור מדוע מתייחסת ההענקה להקב״ה. ועוד: בביזת הים לא היתה נתינה (מהמצרים), ולקיחת הביזה היתה לאחרי מיתת המצרים מן ההפקר (שפת הים). — ואולי י״ל שזהו בגדר דביזת מלחמה, ובל׳ הכתוב הוי׳ נלחם לכם."],["19","19","תורת לוי יצחק ע׳ קכ."],["20","20","מקץ מא, יב."],["21","21","שם מא, מב."],["22","22","סוטה לו, סע״ב."],["23","23","אולי יש לומר, דמה שדייק לכתוב „ניתן“ ולא „נתן“, הוא משום שנתינת אסנת ליוסף היתה ע״י פרעה ולא ע״י פוטיפר."],["24","24","מקץ שם, מה. *) אלא שבצפע״נ שם ס״ל דכלי כסף וכלי זהב בכלל כספים הם. ע״ש."]]],[1300241105,"ולכאורה תמוה:\nא) יוסף איז טאקע געווען אן עבד עברי, אבער זיין אדון איז געווען א נכרי — היינט ווי קען מען זאגן אז „צריך לתת לו הענקה“ (כנ״ל)?\nב) וויבאלד אז „הענקה צריך להיות מהאדון שהי׳ עבד לו“, איז: (א) פאר־וואס „עיקר ההענקה הוא מה שנתן לו הקב״ה“? (ב) ווי איז שייך צו זאגן אז פרעה׳ס נתינת הטבעת ורביד הזהב כו׳ איז דער ענין פון הענקה וואס יוסף דארף קריגן פאר זיין עבדות ביי פוטיפר?\nג) מיט די אלע זאכן וואס יוסף האט געקראגן (טבעת ורביד הזהב כו׳, ע׳ לשון, אסנת²⁵) איז מען ניט מקיים מצות הענקה, כנ״ל.\nאון כאטש די רשימה הנ״ל איז ע״ד הקבלה — איז דאך ידוע די השתדלות (בכו״כ ענינים) אויסגלייכן קבלה און נגלה, ובפרט ע״פ הידוע²⁶ אז קבלה און נגלה דתורה איז א „תורה אחת“, ווי א גוף ונשמה זל״ז: קבלה איז מגלה דעם עומק וסוד וואס איז נסתר אין נגלה שבתורה.\nויש לומר, אז דער אויפטו אין דער רשימה (אז ביי יוסף איז דאס געווען א ענין הענקה) איז מיוסד אויפן ספרי הנ״ל, וואו מען זעט אז עס איז דא הענקה אויך אין א פאל (א) פון אן עבד עברי הנמכר לעכו״ם, און (ב) אויך ווען די הענקה באשטייט פון זאכן „שאינם בכלל ברכה“, און (ג) אפילו ווען זי קומט ניט פון דעם אדון —\nועד״ז ביי יוסף׳ן, אז (א) כאטש ער איז געווען אן עבד הנמכר לעכו״ם, און (ב) די הענקה איז באשטאנען פון טבעת ורביד הזהב כו׳, ע׳ לשון און אסנת, און (ג) איז געקומען ניט נאר פון זיין אדון, נאר בעיקר פון פרעה און „מה שנתן לו הקב״ה“ — איז דאס אבער „הענקה“.\nד. והביאור בזה י״ל:\nאין הענקה זיינען דא צוויי חלקים: א) די נתינת האדון, ב) קבלת העבד — דאס וואס ווערט אויפגעטאן דורך איר אין דעם עבד.\nדאס וואס דער אדון דארף געבן הענקה איז פארבונדן מיט דער (פריער־דיקער) עבדות: די נתינה איז הכרת טובה צום עבד פאר זיין ארבעט אלס עבד [ביז אז עס איז דא א סברא, אז הענקה (איז ניט נאר בתורת צדקה, נאר עס) האט א גדר פון שכר פעולה²⁷];\nמשא״כ די הנאה ותועלת וואס דער עבד באקומט פון דער הענקה, איז עס א פרט וחלק פון זיין שחרור: די שלימות השחרור איז אויב (ער גייט ניט ארויס ריקם, נאר) ער באקומט דעמולט א מתנה מיוחדת, וואס איז מבטל און איז היפך פון עבדות, עס ווערט און איז א מצב פון חירות, רוחב יד וכו׳.\nאון דער צווייטער פרט אין הענקה — שלימות השחרור של העבד — איז מודגש אין דעם טעם „וזכרת כי עבד היית בארץ מצרים ויפדך ה״א על כן אנכי מצוך גו׳“,\nוויבאלד אידן זיינען געווען עבדים און „ויפדך ה״א“, דערפאר זיינען זיי מחוייב טאן אז אן עבד׳ס פדי׳ ושחרור זאלן זיין כדבעי.",[["25","25","ולכאורה „אסנת“ היא „בכלל ברכה“."],["26","26","ראה זח״ג קנב, א."],["27","27","ראה בכ״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191154\" data-slug=\"likkutei-sichot\" data-id=\"1300191154\">לקו״ש חי״ט ע׳ 154</a>. וש״נ."]]],[1300241106,"ה. עפ״ז איז מובן וואס דער ספרי זאגט אז ביזת מצרים וביזת הים איז געווען אן ענין פון הענקה:\nוויבאלד אז דער פסוק רעדט (ניט וועגן דעם חיוב הנתינה שעל האדון, נאר) וועגן דער פדיית העבד, עס זאל זיין חירות בשלימות, איז אין דעם (א) קיין אונטערשייד ניט ביי וועמען ער איז פריער געווען אן עבד, און (ב) ס׳איז ניט (אזוי) נוגע פון וועמען די הענקה קומט (דוקא פון דעם אדון), נאר — דאס וואס דער עבד בעבר האט די הענקה בהווה ובעתיד — מצב דחירות.\nדערמיט ווערט אויך פארענטפערט פארוואס די הענקה (ביי יצי״מ) האט געקענט זיין (אויך) פון דברים שאינם בכלל ברכה:\nדער תנאי אז די הענקה מוז זיין פון דברים שישנם בכלל ברכה איז שייך מצד חיוב ההענקה שעל האדון (אז ער דארף געבן אזא הענקה אז אפילו לאחר זמן זאל זיין ניכר זיין הכרת טובה וכו׳).\nאבער בנוגע דער פעולת ההענקה אויף דעם עבד (שלימות השחרור והחירות שלו) — אז זי ווערט ברגע נתינת המתנה, דארפן דערנאך ניט האבן א פעולה נמשכת, ווייל ער איז דאך א בן חורין.\nו. עפ״ז יש לומר, אז דער חידוש דין הנלמד אין ספרי — „הענקתי לך ושניתי לך אף אתה הענק לו ושנה לו, מה במצרים נתתי לך ברוחב יד אף אתה תתן לו ברוחב יד“ — איז ניט קיין אויפטו אין דעם חיוב פון דעם אדון צו געבן הענקה, נאר דאס איז אן ענין נוסף (וואס איז נוגע צו שחרור העבד):\nמצד דעם חיוב הענקה שעל האדון, איז דא אויך א שיעור למעלה מיט וויפל מ׳איז יוצא אפילו לכתחילה דעם חיוב (וואס איז גענוג אלס אן אות פון הכרת טובה לפי גודל עבודתו):\nאבער מצד דעם פרט אין הענקה וואס טוט אויף די שלימות הפדי׳ של העבד, איז ניטא קיין שיעור — וואס מערער מתנות ער באקומט, נכסים דעצמו (עס קען זיין במדת נכסי עני, אדער — עשיר, אדער — מרבה נכסים), אלץ מערער איז דאס מוסיף אין דעם חירות שלו — און דערפאר „הענק לו ושנה לו . . ברוחב יד“.\nומהאי טעמא ווערט אין פסוק ניט דערמאנט (בפירוש) וועגן דעם „רכוש גדול“ וואס דער אויבערשטער האט געגעבן אידן בצאתם ממצרים, נאר בלויז „ויפדך ה׳ אלקיך“: דער לימוד פון יציאת מצרים איז (ניט פון דער כמות ההענקה — הענקתי ושניתי כו׳ — וואס איז דאן געווען, נאר) אז כשם ווי דעמולט איז די חירות פון עבדות במצרים געווען אין אן אופן פון „ויפדך“ בשלימות, וואס דאס מיינט במילא מיט קבלת רכוש גדול (ביז אז אויך „הענקתי לך ושניתי לך וכו׳“) — עד״ז דארפן אידן מקיים זיין, אז דער שחרור פון זייערע עבדים זאל זיין בשלימותו, און דערפאר דארפן זיי געבן הענקה „שניתי“ און „ברוחב יד“.\nז. לויט דעם וועט מען אויך פאר־שטיין די דערמאנטע דיוקים אין דער רשימה פון טאטן:\nוויבאלד אז יוסף איז געווען אן עבד עברי שנשתחרר, איז, ניט קוקנדיק וואס זיין אדון איז געווען א נכרי, „צריך לתת לו הענקה“, כדי זיין שחרור זאל זיין אין א פולקאמען אופן.\nאון אין דער הענקה גופא זיינען דא צוויי פרטים: די שלימות השחרור בפשטות ובפועל איז געווען דורכדעם\n---"],[1300241107,"וואס פרעה האט אים ממנה געווען פאר א משנה למלך (דער היפך ואל קצה השני פון עבדות), וואס דאס איז געווען בנתינת הטבעת ורביד הזהב כו׳²⁸.\nאבער די אפשריות וההכנה ער זאל ווערן א משנה למלך, וואס נעמט אראפ די טענה פון אצטגניני פרעה אז „עבד²² שלקחו רבו בעשרים כסף תמשילהו עלינו . . יהא יודע בשבעים לשון“, איז דורך דער צווייטער הענקה, וואס „בא גבריאל ולימדו שבעים לשון“.\nאון דערפאר איז דאס „עיקר ההענקה“, ווייל דאס האט אויפגעטאן ביי יוסף׳ן (מצדו) די הכנה און דעם שלימות המצב פון חירות: משא״כ די נתינת הטבעת ורביד הזהב כו׳ וואס ער האט געקראגן פון פרעה׳ן איז געווען די תוצאה און דער בפועל פון דעם.\nדערנאך איז ער מחדש אין דער רשימה נאך אן ענין: „הענקה צריך להיות מהאדון שהי׳ עבד לו“, ד.ה. אז אויך אין דער שלימות פון שחרור העבד קומט צו דורך א הענקה וואס דער אדון אליין איז מעניק — ווארום ווען ער קריגט א מתנה פון דעם זעלבן מענטשן וואס האט אים פריער געהאלטן אלס עבד, איז זיין מצב החירות אין א פיל שטארקערן אופן²⁹.\nדערפאר האט יוסף באקומען הענקה אויך פון פוטיפר (אסנת); אבער אעפ״כ איז דאס נאר א טפל, און דער עיקר איז וואס ער האט באקומען פון פרעה און די שבעים לשון — ווייל די הענקות האבן אין אים אויפגעטאן די שלימות הפדי׳ והשחרור שלו, כנ״ל.\nח. דער ביאור הנ״ל (ע״ד הנגלה) אין דעם גדר ההענקה — אז דאס איז אויך פארבונדן מיט דעם שחרור העבד — איז אויך מתאים מיטן ביאור פון טאטן פון מצות הענקה ע״ד הקבלה:\nאין דער רשימה הנ״ל איז ער מבאר³⁰, אז „עבד עברי הוא . . רק בחי׳ מוחין דקטנות . . וכשנגמר עבודתו . . הוא שנעשה בן חורין, חורין הוא חו״ב . . והנה כשיוצא לחפשי . . צריך להיות ג״כ הענקה . . הכפל דהעניק תעניק י״ל שהוא לנגד חו״ב, והוא כי מה שנעשה בן חורין הוא מצד חו״ב כנ״ל, הנה מחו״ב נמשך גם ההענקה אליו“.\nזעט מען, אז די הענקה ביציאתו לחירות איז ניט קיין באזונדערער זייטיקער ענין (אלס שכר פאר דער עבדות), נאר די הענקה האט אין זיך דעם תוכן פון יציאה לחירות — גילוי בחי׳ חו״ב. וואס דאס איז מתאים עם ההסברה דלעיל (ע״ד הנגלה), אז ההענקה טוט אויף שלימות שחרור העבד.\nט. על פי האמור לעיל, י״ל (בדרך אפשר) דעם טעם (פנימי) פארוואס מצות הענקה איז נאר ביי עבד עברי ואמה עברי׳, און ניט ביי אן עבד כנעני:\nבפשטות י״ל הטעם ווייל ביי אן עבד כנעני איז דא דער חיוב פון „והתנחלתם אותם לבניכם אחריכם . . לעולם בהם תעבודו“³¹ — מען טאר ניט באפרייען אן עבד כנעני³² (סיידן לצורך מצוה",[["28","28","וי״ל שמטעם זה גם נתינת אסנת היתה ע״י פרעה, שגם זה חלק משלימות השחרור (ראה שפ״ח לפרש״י מקץ מא, מה)."],["29","29","ע״ד ומעין דהשיאו רבו בת חורין וכו׳ יצא לחירות (גיטין מ, א)."],["30","30","שם ע׳ קיד־קיט."],["31","31","בהר כה, מו."],["32","32","ברכות מז, ב. וש״נ."]]],[1300241108,"וכיו״ב³³), און וויבאלד אז „תורה על הרוב תדבר“³⁴ האט תורה ניט געזאגט מצות הענקה צוליב מקרים יוצאים מן הכלל, וואו מ׳מעג משחרר זיין דעם עבד.\nאבער על פי פנימיות הענינים איז עס נאך דורש ביאור, ואדרבה: אויב אן עבד עברי ואמה עברי׳, וועלכע זיינען כנגד עולם היצירה ועולם הבריאה, כידוע³⁵, דארפן האבן הענקה — גילוי המוחין: דארף דאך אן עבד כנעני, וואס איז כנגד עולם העשי׳³⁶, זיכער אנקומען צו (הענקה —) גילוי המוחין?\nוע״פ הנ״ל, אז דער ענין פון הענקה און דער ענין פון שחרור זיינען תלוי זה בזה (אין תוכן), און זיי בריינגען די זעלבע פעולה, איז עס פארשטאנדיק. ווייל א איד וואס עבודתו איז בבחי׳ עבד כנעני, בלייבט אלעמאל במהותו (הרוחנית) — אן עבד, וכדלקמן.\nיו״ד. ס׳איז מבואר אין חסידות³⁷, אז דער ענין פון עבד עברי און אמה עברי׳ אין דער עבודת האדם איז די עבודה פון בירור המדות. משא״כ עבד כנעני איז ענינו — קבלת עול, בדוגמא צו אן עבד (כנעני) כפשוטו, וואס (מצד עצמו איז) „בהפקירא ניחא לי׳“³⁸, און ער דינט דעם אדון נאר „מחמת אימת רבו“.\nאבער אע״פ אז די דרגא פון אן עבד כנעני איז נידריקער ווי די דרגא פון „עבד עברי“ און „אמה עברי׳“, וואס זייער דינען דעם אויבערשטן איז מיט א געפיל און געשמאק (מדות) — פונדעסטוועגן האט די עבודה פון „עבד כנעני“ מערער (די מעלת ה)ביטול³⁹:\nאון „עבד עברי“ און „אמה עברי׳“, וואס עבודתם איז פארבונדן מיט מדות, איז הגם אז אויך זיי זיינען עבדים וואס דינען דעם אויבערשטן מיט קבלת עול וביטול (עבודת עבד), איז אבער אין דעם אריינגעמישט אויך א געפיל פון זייער אייגענער מציאות⁴⁰: משא״כ אן „עבד כנעני“, וואס ביי אים איז ניטא קיין הרגש הלב אין זיין עבודה, איז דאך זיין דינען דעם אויבערשטן דורכאויס מיט קבלת עול וביטול צום רצון העליון⁴⁰ (און קיין תערובת פון זיין אייגענער מציאות).\nוי״ל אז דאס איז דער טעם הפנימי פארוואס אן עבד כנעני איז והתנחלתם גו׳ לעולם בהם תעבודו, קען ניט נשתחרר ווערן:\nדי עבודה פון בירור המדות ביי „עבד עברי“ און „אמה עברי׳“, היות אז זי איז פארבונדן מיט מציאות האדם, דערפאר איז (א) דאס ביי זיי אן עבודה מוגבלת, ובמילא האט זי א סוף; און (ב) נאכמער: די שלימות פון דער עבודה גופא איז, ווען מען גייט ארויס (פון איר) לחירות — ארויסגיין און אויפהויבן זיך פון דער עבודה אינעם ענין המדות, און צוקומען",[["33","33","ראה פסחים קיג, א. ברכות שם. וראה גם קידושין כד, א."],["34","34","ראה מו״נ ח״ג פל״ד."],["35","35","שער המצות וסהמ״צ ר״פ משפטים. ובכ״מ."],["36","36","ראה סהמ״צ להצ״צ פג, ב. ובכ״מ."],["37","37","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540097\" data-slug=\"torat-chaim\" data-id=\"2300540097\">תו״ח שמות עא, ב</a> ואילך. אוה״ת משפטים ע׳ א׳קכז ואילך. סהמ״צ להצ״צ שם ואילך. ועוד."],["38","38","גיטין יג, א."],["39","39","בהבא לקמן להעיר גם מ<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091073\" data-slug=\"likkutei-sichot\" data-id=\"1300091073\">לקו״ש ח״ט ע׳ 73</a> ואילך. וש״נ."],["40","40","להעיר מהמבואר בהמשך תרס״ו (ד״ה ומקנה רב ושלאחריו, ע״ש). וראה שם (ע׳ שי. ס״ע שכו ואילך) בביטול דעבד פשוט, דהוא וכל אשר לו נקנה לאדונו, והוא רק „קנין כספו“ של האדון כשורו וכה״ג — שזה נאמר על עבד כנעני (משפטים כא, כא. אמור כב, יא ובפרש״י. וראה קידושין כג, א ואילך. ועוד)."]]],[1300241109,"צו דער מדריגה פון עבודת השם שע״פ מוחין, טעם ודעת⁴¹.\nמשא״כ די עבודה פון אן עבד כנעני — קבלת עול — איז ביטול לגמרי. ער פארלירט זיין אייגענע מציאות, ער האט ניט קיין אייגענע רצונות, תענוג ומדות, נאר ער גיט זיך אוועק אינגאנצן צום אדון⁴²: ובמילא איז ביי אים ניט שייך דער ענין השחרור, ווייל: (א) אט די עבודה (בביטול לגמרי) איז א בלתי מוגבלת, און גיט ניט קיין ארט אויף „שחרור“⁴³. (ב) נאכמער: אין דער עבודה זיינען מוחין (טעם ודעת של האדם) מבלבל — ומובן אז ס׳איז במילא ניט שייך אין דעם קיין „הענקה“ להאדם, וואס ענינה איז גילוי המוחין שלו, כנ״ל,\nנאר מוחין פון דעם אדון ווי באם אדון⁴⁴ ובלשון חז״ל „שכינה מדברת מתוך גרונו“, לערנען (כולל הבנה והשגה) באופן פון „איתמר“⁴⁵.\nיא. טראץ דער מעלה פון ביטול וואס איז דא אין דער עבודה פון „עבד כנעני“, ווערט כללות עבודת עם ישראל פארגליכן צו „עבד עברי“⁴⁶ דוקא —\nווי עס שטייט אין חסידות⁴⁷, אז דער פסוק⁴⁸ „שש שנים יעבוד ובשביעית יצא לחפשי חנם“ איז א רמז אויף דער „עבודה שהעבדים שהן הישראלים צריכים לעבוד הוא שית אלפי שני דהוי עלמא, ובאלף השביעי הוא אמתת קבלת השכר⁴⁹ ואז יצאו לחפשי חנם בלא מצות“⁵⁰\n[וכשם ווי דאס איז אין כללות העבודה, עד״ז איז אויך אין דער עבודה פרטית ביי יעדער אידן: אין די ששת ימי החול דארף ביי אים זיין די עבודה בטורח ועמל: און דערנאך קומט די מנוחה פון יום השבת, ווען ער ווערט „באפרייט“ פון דער עבודה ועמל].\nקען מען זאגן⁵¹ די הסברה בזה: טראץ דער מעלה נפלאה וואס איז דא אין דעם ביטול מוחלט פון אן עבד כנעני, איז אבער תכלית הכוונה עס זאלן זיין ביידע עבודות⁵²: סיי ביטול, און סיי כוחות הנפש (און דער ביטול זאל דורכנעמען די כוחות), ער זאל האבן א געשמאק און א הבנה און א הרגש אין זיין עבודה. און",[["41","41","ושייך לתוכן ענין החירות, כי המדות מוגבלות בציורן, משא״כ שכל ענינו חירות (בערך המדות), כי אינו נתפס בקו אחד (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141127\" data-slug=\"likkutei-sichot\" data-id=\"1300141127\">לקו״ש חי״ד ע׳ 115</a>. וש״נ)."],["42","42","המשך תרס״ו שם (ס״ע שכה ואילך)."],["43","43","ראה המשך תרס״ו שם (ע׳ שכא־ב): ועבודתו היא בתמידות בלי שום שינוי וחילוף . . ולא יגרע עבודתו לעולם."],["44","44","ראה המשך תרס״ו שצויין בהערה 42."],["45","45","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380409\" data-slug=\"likkutei-torah\" data-id=\"4001380409\">לקו״ת נשא כה, ב</a>."],["46","46","וראה המשך הנ״ל (ע׳ שיט): כי לי בנ״י עבדים . . בבחי׳ עבד נאמן (ראה לעיל הערה 40)."],["47","47","סהמ״צ להצ״צ פג, א. וראה גם תו״א משפטים עו, א. סה״מ תקס״ה ע׳ רפה."],["48","48","משפטים כא, ב."],["49","49","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a> בהגהה מל״ת להאריז״ל (משא״כ ימות המשיח ותחה״מ הם (לא שכר בלבד, כי אם) „תכלית ושלימות בריאת* עולם הזה“ — תניא שם)."],["50","50","ראה תשובות וביאורים סי״א (ע׳ 51)* הערה 9, שבתניא שם מוכח דקאי להשיטה דאין מצות בטילות בתחה״מ (כ״א באלף הז׳). וכן מוכח בסהמ״צ ובסה״מ תקס״ה שם. אבל ראה לקו״ש ח״ה ע׳ 244 ואילך ובהערה 33 שם."],["51","51","מעין זה — עבודת בע״ת ועבודת צדיקים ששניהם צ״ל בכ״א וכמו שישנו במשך השנה תשרי וניסן."],["52","52","ע״ד מ״ש ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ״א (נז, א</a>) „שכל אדם צ״ל בשתי בחי׳ ומדרגות . . בחי׳ עבד ובחי׳ בן“. וראה המשך תרס״ו שם. *) לכאורה כצ״ל. וכ״ה בכמה דפוסים. *) אג״ק כ״ק אדמו״ר שליט״א ח״ב ע׳ סט. המו״ל."]]],[1300241110,"ס׳איז ניט גענוג א ביטול און חיות וכו׳, נאר ער זאל האבן דערין א געשמאק.\nדעריבער דארף די עבודה זיין אין דער בחי׳ פון „עבד עברי“ — אן עבדות וואס איז פארבונדן מיט די מדות (והרגש) פון מענטשן: ביז מען דער־גרייכט די „יציאה לחירות“ — די עלי׳ פון דער עבודה פון מדות צו דער עבודה פון מוחין, עבודה שע״פ טעם ודעת.\nביז צו דער שלימות החירות וואס קומט דורך „הענקה“ — אז מען גיט א אידן מלמעלה גילוי המוחין, וואס ברענגט אריין א שלימות אין דער עבודה⁵³ שע״פ טעם ודעת.\nיב. ס׳איז ידוע מאמר המדרש⁵⁴ אויף „מגיד דבריו ליעקב חוקיו ומשפטיו לישראל“⁵⁵ — „מה שהוא עושה הוא אומר לישראל לעשות“, איז דערפון מובן אז אזוי איז עס אויך בנוגע דער מצות „הענקה“ וואס דער אויבערשטער איז מקיים און גיט אלס אדון צו די אידן, זיינע עבדים — איז עפ״ז י״ל אז נוסף דערצו וואס באלף השביעי וועלן אידן זוכה זיין צום קיום פון „ובשביעית יצא לחפשי חנם“, וועלן זיי אויך באקומען דעם „הענק תעניק לו“, א הענקה נוספת פון דעם אויבערשטן.\nאון וויבאלד אז ערב שבת דארף מען טועם זיין „מכל תבשיל ותבשיל“⁵⁶ פון מאכלי שבת — איז מובן אויך בעניננו, אז נוסף לזה וואס שוין איצט, ערב שבת, דארפן, איז מען טועם פון דער „מנוחה“ וואס וועט זיין באלף השביעי, דארף זיין אויך די „טעימה“ פון דער הענקה.\nויהי רצון, אז נאכדעם וואס מ׳האט די „טעימה“ פון דעם „שכר“ און פון דער „הענקה“ און פון דער „מנוחה“ —\nזאל מען בקרוב ממש זוכה זיין צו אכילת כל תבשיל ותבשיל (ונעשה דם ובשר כבשרו), ימות המשיח ותחיית המתים ש„הם תכלית ושלימות בריאת עולם הזה שלכך נברא מתחלתו“⁵⁷,\nביז צו דעם „עיקרו“⁵⁸ פון „קבלת שכר“ וואס איז „באלף השביעי“⁵⁷.\n(משיחות ש״פ ראה תשל״ו, תש״מ)",[["53","53","ע״פ המבואר בפנים יש לבאר ע״פ פנימיות הענינים מ״ש בספרי (פרשתנו טו, יד) „הענק תעניק . . אפילו מאה פעמים“ [דע״פ פשוטו תמוה (כקושיית התו״ת כאן) איך אפי״ל הענקה לעבד א׳ מאה פעמים] — כי לכל מדריגה של עבודת ה׳ יש בחי׳ המוחין שלה, ובכל עלי׳ מחיל אל חיל יש נתינת הענקה (— מוחין) לפ״ע הדרגא ההיא."],["54","54","שמו״ר פ״ל, ט."],["55","55","תהלים קמז, יט."],["56","56","שו״ע אדה״ז או״ח סר״נ ס״ח."],["57","57","תניא שם."],["58","58","להעיר מענין „סוף מתן שכרן של מצות“ „סוף כל השכר כולו“ שברמב״ם הל׳ תשובה פ״ט (בתחלתו, בסופו)."]]],[1300241111,"<h3>אלול *</h3>\nא. בנוגע תפלה בצבור — וואס איז פון די מעלות הכי חשובות אין תפלה¹ — געפינט מען א פלוגתא צווישן די חכמים און רבן גמליאל²: די חכמים זאגן „כשם ששליח ציבור חייב כך כל יחיד ויחיד חייב״ — עס איז דא א חיוב אויף יעדן יחיד (פונעם ציבור) צו מתפלל זיין פאר זיך: „רבן גמליאל אומר שליח ציבור מוציא את הרבים ידי חובתן״.\nאון די גמרא³ ברענגט אויף דעם א ברייתא⁴: „אמרו לו לרבן גמליאל לדבריך למה צבור מתפללין, אמר להם כדי להסדיר שליח צבור תפלתו (דער שליח צבור זאל האבן צייט צוגרייטן זיין תפלה⁵), אמר להם רבן גמליאל לדב־ריכם למה שליח צבור יורד לפני התיבה אמרו לו כדי להוציא את שאינו בקי, אמר להם כשם שמוציא את שאינו בקי כך מוציא את הבקי״.\nדאס הייסט: לויט די חכמים, איז — „צבור עיקר״⁶: דער ענין פון תפלה\nבצבור איז וואס דער צבור איז מתפלל צוזאמען⁷, און דער ענין פון חזרת הש״ץ איז בלויז א תקנה צו מוציא זיין דעם „אינו בקי״⁸; משא״כ ר״ג האלט, אז „שליח צבור עיקר״⁶: דער עיקר ענין פון תפלה בצבור איז די תפלת הש״ץ, און דאס וואס איידער חזרת הש״ץ איז יעדער יחיד פון דעם צבור מתפלל תפלת לחש פאר זיך, איז דאס בלויז א תקנה צוליב ש״ץ⁹ — „כדי להסדיר שליח צבור תפלתו״.\nב. אין וואס באשטייט דער טעם וסברת הפלוגתא, צי „צבור עיקר״ אדער „ש״ץ עיקר״?\nקען מען זאגן, אז דאס איז פארבונדן מיט דער שאלה הידועה¹⁰ — וואס האט מער חשיבות, ריבוי הכמות אדער גודל",[["","","*) וסיום מס׳ ראש השנה. וע״פ הידוע (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091326\" data-slug=\"likkutei-sichot\" data-id=\"1300091326\">לקו״ש ח״ט ע׳ 299</a>. וש״נ) ש(בר״ת של) אלול שייך (ובהם נרמזים) כל הג׳ קוין דתורה תפלה וצדקה, מו״ל הדרן זה שבו מבואר „לשיטתייהו״ של ר״ג וחכמים בג׳ קוין אלו."],["1","1","ראה ברכות ח, רע״א. רמב״ם הל׳ תפלה רפ״ח. ובכ״מ. וראה ס׳ הלקוטים (דא״ח — הצ״צ) ערך צבור. וש״נ."],["2","2","משנה סוף ר״ה (לג, ב)."],["3","3","שם לד, ב."],["4","4","תוספתא ר״ה בסופה."],["5","5","כהלשון בתוספתא שם: שש״ץ מתקין א״ע."],["6","6","לשון הרא״ש ר״ה שם. — אבל בר״ן ר״ה (לד, ב. הובא בתוי״ט סוף ר״ה) מביא מירושלמי (ברכות פ״ג ה״ג) דבתפלה מסתבר שיהא כל אחד מבקש רחמים על עצמו. ולפ״ז מה ש„כל יחיד ויחיד חייב״ אינו שייך להמעלה דתפלה בצבור. [והמעלה דתפלה בצבור היא ע״י השמיעה (אח״כ) מהש״ץ (ע״ד המבואר לקמן הערה 23). וראה לקמן הערה 8]."],["7","7","להעיר מברכות (כא, סע״א) „התפלל . . ומצא צבור שמתפללין אם יכול לחדש בה דבר יחזור ויתפלל״. וראה שם (ריש ע״ב) קס״ד הגמרא „יחיד לגבי צבור כמאן דלא צלי דמי״."],["8","8","וצע״ק בלשון הרמב״ם (הל׳ תפלה פ״ח ה״ד) „וכיצד היא תפלת הציבור יהי׳ אחד מתפלל בקול רם והכל שומעים״. ומשמע שעיקר ענין של תפלה בציבור הוא תפלת הש״ץ, והרי פסק הרמב״ם כחכמים (שם ה״ט). ואולי ס״ל כנ״ל הערה 6 בדעת הר״ן. וראה דברי ירמי׳ על הרמב״ם שם. ולהעיר מליקוטי שו״ת חת״ס (לונדון תשכ״ה) ס״ג. ועוד. ואכ״מ."],["9","9","אלא שלאחרי שנתקנה תקנה זו, הרי הבקיאים המתפללים בלחש יוצאים י״ח בתפלת לחש, ולא מן הש״ץ (תשובות הרמב״ם הוצאת פריימאן סי׳ לה). וראה לקמן הערה 23."],["10","10","ראה לקח טוב להרי״י ענגל כלל טו־טז. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111073\" data-slug=\"likkutei-sichot\" data-id=\"1300111073\">לקו״ש חי״א ע׳ 65</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021126\" data-slug=\"likkutei-sichot\" data-id=\"1300021126\">ח״ב ע׳ 126</a> ואילך. ועוד."]]],[1300241112,"האיכות — וואס מען געפינט אין דעם א פלוגתא צווישן רבן גמליאל וחבריו:\nדי גמרא¹¹ דערציילט, אז בשעת ר׳ גמליאל איז געווען נשיא, איז „הי׳ . . מכריז ואומר כל תלמיד שאין תוכו כברו לא יכנס לבית המדרש״, און דערנאך, בשעת מ׳האט אים מעביר געווען פון דער נשיאות און ר׳ אלעזר בן עזרי׳ איז געווארן נשיא¹², „סלקוהו¹¹ לשומר הפתח ונתנה להם רשות לתלמידים ליכנס . . ההוא יומא אתוספו כמה ספסלי״.\nדאס הייסט: ר׳ גמליאל האלט, אז דער עיקר חשיבות פון א ישיבה (בית מדרש) איז — איכות התלמידים, און דעריבער, פלעגט ער נאר אריינלאזן די תלמידים וואס תוכם כברם (אע״פ אז דורך דעם איז געווען מיעוט הכמות פון תלמידים): משא״כ חבריו (ראב״ע, ר׳ יהושע און ר׳ עקיבא) האלטן אז ריבוי הכמות איז מכריע מעלת האיכות, און דעריבער דארף מען אריינלאזן אין ביהמ״ד אויך תלמידים שאין תוכם כברם, ווייל דער עיקר איז עס זאל זיין מער תלמידים בישיבה — ריבוי בכמות, כאטש דאס וועט גורם זיין א מיעוט באיכות הכללי דביהמ״ד — ובמילא — גם באיכות הפרטים.\nועפ״ז יש לומר, אז אין דעם וואס ר׳ גמליאל האלט אז „תפלת הש״ץ עיקר״, גייט ער לשיטתו אז איכות איז מכריע כמות.\nג. דער ביאור אין דעם:\nאין דעם אויפטו פון א „צבור״ (גופא) זיינען דא די ביידע מעלות פון „כמות״\nאון „איכות״¹³: א) א ציבור באשטייט דוקא פון (ריבוי בכמות) עשרה (עכ״פ) מישראל¹⁴. ב) דער צירוף פון עשרה מישראל שאפט א מציאות חדשה, א חטיבה אחת פון אן עדה קדושה (א חשיבות באיכות).\nאון דאס איז דער חילוק צווישן תפלת הצבור (וואס איז כולל די תפלות פון כאו״א פונעם ציבור בפ״ע) און תפלת הש״ץ:\nתפלת הצבור האט די מעלה פון ריבוי הכמות — דער ריבוי פון תפילות וואס ווערט נצטרף יחד — בשעת עשרה מישראל זיינען מתפלל צוזאמען:\nדאקעגן אין תפלת הש״ץ איז פאראן די מעלה פון איכות, ווארום\n[נוסף על זה וואס א ש״ץ מוז האבן געוויסע תנאים ומעלות¹⁵, ובמילא האט זיין תפלה (אויך אלס יחיד) א גרע־סערע חשיבות באיכות לגבי די תפלות פון סתם מתפללים — איז נאכמער:]\nא שליח צבור איז ענינו, וואס ער איז כולל די פיפיות עמך בית ישראל¹⁶, וואס „הוא נעשה שליח לכולם . . שפיו כפיהם״¹⁷, אזוי אז יעדער ווארט וואס ער איז מתפלל, איז דאס כאילו ווי די גאנצע עדה זאגט עס דורך פיו. דאס הייסט, אז אין תפלת הש״ץ איז מרוכז",[["11","11","ברכות כח, א."],["12","12","ראה ברכות שם כז, סע״ב ואילך."],["13","13","ראה לקח טוב שם סט״ז אות ז."],["14","14","מגילה כג, ב (במשנה. וראה גמרא שם). וש״נ."],["15","15","ראה תענית טז, סע״א ואילך. טושו״ע (ודאדה״ז) או״ח סי׳ נג."],["16","16","ל׳ ברכת התורה — (כנוסח הגמרא) ברכות יא, ב. פיוט שאומר הש״ץ אחרי „עלינו״ בחזרת הש״ץ דתפלת מוסף של ר״ה ויוהכ״פ (אבל — לפי נוסח חב״ד אין אומרים זה)."],["17","17","ל׳ אדה״ז — שו״ע או״ח סרי״ג ס״ו (לענין ברכת המצות כשאחד מברך לכולם)."]]],[1300241113,"ומאוחד די תפלה פונעם צבור ווי ער ווערט איין מציאות פון אן עדה קדושה — אן אנדער גדר אין איכות התפלה אפילו לגבי די תפלות פון ריבוי המתפללים בצבור.\nאון דאס איז די פלוגתא פון די חכמים און ר״ג¹⁸: די חכמים האלטן אז ריבוי הכמות איז מכריע איכות, און דעריבער זאגן זיי אז דער עיקר פון תפלה בצבור איז — תפלת הצבור: משא״כ ר״ג האלט אז די איכות ווערט איבער די כמות, און דעריבער, אע״פ אז תפלת הש״ץ איז מעוטה בכמות — ס׳איז בלויז איין תפלה — איז זי אבער מער חשוב ווי תפלת הצבור, ווייבאלד זי איז פיל גרע־סער (דערהויבענער) באיכות (האבנדיק דעם כח פון גאנצן צבור כאחד)¹⁹.\nד. מ׳האט שוין אמאל גערעדט²⁰, אז בשעת מען געפינט א פלוגתא צווישן חכמים מצד דער זעלבער סברא אין צוויי (אדער מער) ערטער — איז פא־ראן א חידוש אין יעדער פלוגתא לגבי די אנדערע פלוגתות (וואס דערפאר מוזן אראפגעבראכט ווערן בפירוש אלע פלוגתות און מען קען זיי ניט אפ־לערנען איינע פון דער צווייטער — ובלשון הש״ס „וצריכא״).\nועד״ז בעניננו: אין יעדערער פון די צוויי פלוגתות הנ״ל איז פאראן א חידוש:\nאין דעם ענין פון „בית המדרש״, ווי־באלד דא רעדט זיך וועגן א תלמיד „שאין תוכו כברו״, פעלט אים די כללות ה„איכות״ פון א „תלמיד״, כמאמר חז״ל²¹ „כל תלמיד חכם שאין תוכו כברו אינו תלמיד חכם״: משא״כ ביים ענין פון תפלה, איז ביי תפלת הצבור פאראן (ניט נאר די מעלה פון כמות, נאר) אויך די מעלה פון איכות, ווארום בשעת צען אידן דאוונען צוזאמען האט די תפלה (פון יעדערן בפ״ע אבער אלס א טייל פון צבור) א מעלה²² לגבי תפלת היחיד: עס איז נאר, אז די איכות פון תפלת הש״ץ (אין וועלכער דער גאנצער צבור ווערט נתאחד אלס איין מציאות פון אן עדה קדושה) איז נאך ביתר שאת ועילוי.\nאון דעריבער, ווען עס וואלט גע־שטאנען די שיטה פון ר״ג בלויז ביים ענין פון „בית המדרש״ וואלט מען גע־מיינט, אז דוקא דארט גייט ער בתר איכות: משא״כ ביים ענין התפלה איז ער מודה אז „תפלת צבור עיקר״ (ווייבאלד עס פארמאגט ביידע מעלות: א גרע־סערע איכות (לגבי תפלת היחיד) און אויך ריבוי כמות)²³.",[["18","18","להעיר גם מב׳ האופנים בשו״ע אדה״ז שם: אם רצו אחד מברך לכולם כדי לקיים ברב עם כו׳ ואם רצו כל אחד מברך לעצמו . . להרבות בברכות כו׳. ע״ש. ואכ״מ."],["19","19","ע״פ המבואר בפנים יומתק גם הטעם (בפנימיות העניינים) שהלכה כר״ג בברכות של ר״ה ושל יוה״כ (ר״ה לה, רע״א) — כי ראש השנה (וכן יוה״כ שנק׳ ר״ה — יחזקאל מ, א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380951\" data-slug=\"likkutei-torah\" data-id=\"4001380951\">לקו״ת ר״ה נח, א</a>) לגבי כל השנה הוא ע״ד הש״ץ שכולל כל הציבור, נשיא שכולל כל העם (ראה לקמן בסוף השיחה) — עיין לקו״ת ר״ה שם. עטרת ראש בתחלתו בארוכה."],["20","20","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061082\" data-slug=\"likkutei-sichot\" data-id=\"1300061082\">לקו״ש ח״ו ס״ע 71</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171115\" data-slug=\"likkutei-sichot\" data-id=\"1300171115\">חי״ז ע׳ 115</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181118\" data-slug=\"likkutei-sichot\" data-id=\"1300181118\">חי״ח ע׳ 109</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191075\" data-slug=\"likkutei-sichot\" data-id=\"1300191075\">חי״ט ע׳ 75</a> ואילך. ועוד."],["21","21","יומא עב, ב. וראה המשך הגמ׳ שם."],["22","22","ע״ד ענין ה„צבור״ בקרבן פסח (ראה ירושלמי פסחים רפ״ז: אף פסח קרבן ציבור), שהוא מצד זה ש„אתי בכנופיא״ (יומא נא, א. פרש״י פסחים סו, סע״ב), ונשחט ב(ג׳) כתות — קהל (פסחים סד, א־ב. ע״ש). אבל מכיון שכ״א מביא קרבן לעצמו אינו כקרבן ציבור ממש (ראה פיהמ״ש להרמב״ם בהקדמתו לסדר קדשים „המין הרביעי״. וראה לקו״ש חי״ח ע׳ 436. ובארוכה — ח״ח ע׳ 104 ואילך. ע׳ 112 ואילך)."],["23","23","ולהעיר מתשובות הרמב״ם (הנ״ל הערה 9) — שגם לר״ג התקנה היא באופן — שהבקיאים"]]],[1300241114,"שטייט דעריבער שיטת ר״ג אויך ביי תפלה, בכדי צו לאזן הערן, אז אויך אין דעם פאל איז כדאי דער מיעוט בכמות צוליב א נאך גרעסערער איכות.\nולאידך גיסא, ווען שיטת ר״ג וואלט געשטאנען בלויז ביי תפלה (איז נוסף לזה וואס מ׳וואלט געקענט זאגן אז ביי בית המדרש זיינען די חכמים מודה צו ר״ג מטעם הנ״ל — איז אויך בנוגע צו שיטת ר״ג) וואלט מען פון דארט ניט געקענט אפלערנען אז ער האלט אזוי אויך בנוגע צו „בית המדרש״. ווייל ביהמ״ד איז ענינו תורה וואס נקנית בדבוק חברים ובפלפול התלמידים²⁴, ואדרבא מתלמידי יותר מכולם²⁵ — איז וואס מער תלמידים (כולל אויך שאין תוכם כברם) אלץ מער פלפול²⁶ און אלץ טיפער דער „נקנית״.\n[וע״ד המוסר יש להוסיף: היות תורה איז מלשון הוראה²⁷: ווייזן א מענטשן ווי ער דארף זיך פירן — במילא וואלט געווען א מקום לומר אז א ישיבה איז אויך צוליב תלמידים שאין תוכם כברם בכדי אז זיי זאלן ווייסן ווי צו פירן זיך און נאך מערער, אויפטאן אז ביי זיי זאל ווערן „תוכם כברם״²⁸].\nאון דעריבער דארף שטיין שיטת ר״ג ביי „בית המדרש״, להשמיענו, אז אויך בנידון זה האלט ר״ג אז מען רעכנט זיך מיט איכות.\nה. תוכן השאלה הנ״ל — צו ריבוי הכמות איז מכריע אדער האיכות — איז עולה בקנה אחד אדער עכ״פ מעין פון דער שאלה בכמה ענינים (ווי דער ראגאטשאווער איז מאריך בכמה מקומות²⁹): וואס איז דער עיקר הדבר — חומר (וגשם) הדבר, אדער זיין „צורה״ (ותוכן).\nאויב מען רעכנט זיך בעיקר מיט חומר — דעמאלט האט ריבוי הכמות מער חשיבות ווי איכות: אויב אבער דער עיקר איז צורת (ותוכן) הדבר — איז איכות מכריע כמות.\nעפ״ז קען מען געפינען נאך א „לשיטתי׳״ צווישן ר״ג מיט די חכמים — אין דעם דין פון „טענו חטים והודה לו בשעורים פטור, ורבן גמליאל מחייב״³⁰. די חכמים (ת״ק) האלטן אז א מודה במקצת איז חייב נאר ווען די הודאה",[["","","מתפללים בלחש ויוצאים י״ח בתפלתם זו. אלא שצ״ע, דכי מפני שבקיאין הם יגרע מתפלתם (שלא תהי׳ בה מעלת האיכות דתפלת הש״ץ)? ועושין זה (מתפללין בלחש) כדי שהש״ץ יוכל להסדיר תפלתו (ע״ד שאלת השואלים בתשובת הרמב״ם שם)?! וי״ל, דאף שכבר יצאו בתפלת לחש, מ״מ, כאשר מוסיפים על תפלתם ושומעים תפלת הש״ץ נתוספה בהם מעלת האיכות דתפלת הש״ץ (ע״ד ומעין שמצינו גבי כל תפלה, שרשאי אדם להתפלל תפלת נדבה אם מחדש בה דבר — ברכות כא, סע״א. טושו״ע (ודאדה״ז) או״ח סי׳ קז). ואכ״מ."],["24","24","אבות פ״ו, ו."],["25","25","תענית ז, א. מכות י, א."],["26","26","עפ״ז יובן מה שחלשה דעתי׳ דר״ג כשראה שנתוספו ספסלים, אף שלא חזר בו משיטתו שהאיכות מכריע — כי ראה שנתוסף גם באיכות בית המדרש, דההוא יומא „לא היתה הלכה שהיתה תלוי׳ בבית המדרש שלא פירשוה״ (ברכות כח, שם), „מתוך שרבו התלמידים רב החדוד והפלפול״ (רש״י שם)."],["27","27","זח״ג נג, ב. גו״א ר״פ בראשית בשם הרד״ק."],["28","28","עיין הל׳ ת״ת לאדה״ז פ״ד (בקו״א ס״א בסופו): וגם הרב י״ל דצריך להכניס א״ע כו׳. ועיין שם הלכה יז. אלא שצ״ע אם הכוונה ב„אין תוכו כברו״ בברכות שם היא לתלמיד שאינו הגון ממש (כפשטות משמעות הש״ס ביומא שם. וראה חדא״ג מהרש״א ברכות שם), דא״כ איך סלקוהו לשומר הפתח — דמשמע לגמרי, בלי כל הגבלה."],["29","29","ראה בארוכה מפענח צפונות פרק א, פרק יא (ושם גם בנוגע לכמות ואיכות). וש״נ."],["30","30","שבועות לח, ב (במשנה)."]]],[1300241115,"במקצת איז „ממין הטענה״, אבער ר״ג האלט, אז אויך ווען די הודאה איז שלא ממין הטענה איז מען חייב שבועה משום מודה במקצת.\nוואס אויך בנוגע דער פלוגתא קען מען זאגן אז דאס איז תלוי אין דער שאלה הנ״ל — וואס איז דער עיקר פון א זאך: איר חומר (וכמות) אדער איר צורה (ואיכות), ובהקדים:\nדער טעם פארוואס די הודאה פון א מודה במקצת זאל דארפן זיין ממין הטענה איז³¹, ווייל אויב די הודאה איז ניט ממין הטענה קומט אויס, אז ער איז ניט קיין מודה במקצת הטענה³²: אויף דער טענה פון חטין איז ער ניט קיין „מודה במקצת״ נאר א „כופר הכל״: און אויף זיין הודאה בשעורין — איז איבער־הויפט ניטא קיין טענה פון תובע (און במילא איז ניט שייך (מודה ב)מקצת הטענה).\nאבער די סברא ווענדט זיך, וואס מ׳נעמט אן אלס עיקר אין א „טענה״ — ווייל אין א טענה ותביעת ממון זיינען פאראן צוויי ענינים: די תביעה בפועל דריקט זיך אויס אין א דבר מסוים — חטים, שעורים וכיו״ב — וואס דאס איז דער „חומר״ (כמות) פון דער תביעה: און דער תוכן („צורה״) פון דער תביעה איז — ממון וואס ער מאנט ביים חבר (וואס דאס איז גלייך ביי אלע תביעות: חטים שעורים וכו׳).\nאון דאס איז די פלוגתא צווישן די חכמים מיט ר״ג ולשיטתייהו אזלי: די\nחכמים, לשיטתם, האלטן אז דער עיקר אין יעדער זאך איז דער חומר וכמות הדבר. ועד״ז בנדו״ד, איז דער עיקר דער „חומר״ הטענה: ובמילא קומט אויס, אז אין א פאל פון „טענו חטין והודה לו בשעורים״ איז ניטא קיין מודה במקצת הטענה: משא״כ ר״ג האלט אז מען רעכנט זיך מיט איכות הטענה, וואס זי איז די זעלבע סיי ביי חטים און סיי ביי שעורים — און דעריבער איז עס א הודאה במקצת, אפילו ווען דאס איז ניט „ממין הטענה״ (מצד דעם „חומר״ הטענה).\nו. און דער חידוש אין דער פלוגתא לגבי די פריערדיקע צוויי פלוגתות איז:\nבית המדרש (תורה) און תפלה זיינען א חפצא של מצוה, וואלט מען געקענט זאגן, אז דאס וואס ר״ג רעכנט זיך ביי זיי מיט איכות הדבר איז מהאי טעמא גופא: היות דאס איז א חפצא של מצוה ודבר שבקדושה, איז חשוב ומכריע דער תוכן ואיכות פון דער זאך:\nמשא״כ דברי הרשות האבן ניט קיין (תורה) חשיבות [ע״ד ווי רש״י³³ זאגט בנוגע צו סעודת חול — „סעודת חול לא חשיבא ולא שייכא בה הזמנה״, ווארום זייענדיק א סעודת רשות — ניט קיין תורה מציאות, האט עס ניט קיין חשיבות אז מען זאל אויף דעם דארפן א הכנה],\nאון דעריבער, ווען עס וואלט ניט גע־שטאנען בפירוש שיטת ר״ג בנוגע צו טענו חטים והודה לו בשעורים, וואלט מען ניט געקענט אפלערנען שיטתו פון תורה ותפלה,\n[ועד״ז לאידך גיסא: ווען עס וואלט געשטאנען די פלוגתא פון די חכמים",[["31","31","אף שהדין דהודאה ממין הטענה נלמד מפסוק (שם לט, ב. ב״מ ה, א) — מ״מ הרי אין זה גזה״כ כ״א דבר המובן בסברא."],["32","32","ראה שבועות שם: מה שטענו לא הודה לו ומה שהודה לו לא טענו. וראה שטמ״ק לכתובות קח, ב ד״ה ה״ג וחכמים אומרים וסד״ה גמרא ש״מ לרבנן (מרש״י במהדורא קמא)."],["33","33","ד״ה ואין יו״ט — ביצה ב, ב."]]],[1300241116,"מיט ר״ג בלויז בנוגע צו הודאה ממין הטענה — וואלט מען ניט געוואוסט שיטת חכמים בנוגע צו תורה ותפלה].\nז. כשם ווי מען געפינט שיטות ר״ג וחכמים בנוגע די צוויי „עמודים״³⁴ פון תורה און תפלה — עד״ז געפינט מען אויך ביי דעם דריטן „עמוד״³⁴ פון צדקה (גמילות חסדים).\nאין גמרא³⁵ איז פאראן א פלוגתא בפירוש הפסוק³⁶ „וחסד לאומים חטאת״: ר׳ אליעזר זאגט „וחסד לאומים חטאת, כל צדקה וחסד שאומות (עכו״ם) עושין חטא הוא להן שאינם עושין אלא להתגדל בו״: ר׳ יהושע זאגט „כל צדקה כו׳ חטא הוא להן שאין עושין אלא כדי שתמשך מלכותן״: און ר״ג זאגט „כל צדקה וחסד כו׳ חטא הוא להן שאין עושין אלא להתייהר בו״.\nאיז מסביר דער מהרש״א³⁷ דעם חי־לוק דא צווישן „להתגדל בו״ און „להת־ייהר בו״: „להתגדל בו״ מיינט (ניט א „לשון גדולה וחשיבות״ — ווייל דאס איז (אויך) „להתייהר״ — נאר דאס מיינט) „גדולה בשנים שיאריכו ימים״.\nד.ה. אז דער חילוק צווישן די ערשטע צוויי דרשות (פון ר״א און ר״י) און דרשת ר״ג איז: לויט זיי באשטייט די „חטאת״ פון די אומות אין דעם וואס זייער טאן צדקה וחסד איז נאר צוליב שכר: משא״כ לויט ר״ג איז זייער חטא דערין וואס זייער חסד וצדקה (איז צוליב, ובמילא —) ברענגט זיי צו דער מדה וחטא פון גאוה — „להתייהר״.\nוואס איז די סברת הפלוגתא? קען מען זאגן, אז דאס איז פארבונדן מיט דער שאלה — וואס איז קובע: חומר אדער צורה.\nח. די הסברה בזה:\nזאגן, אז די צדקה וחסד וואס אומות העולם טוען איז (ניט בלויז קיין מצוה ניט, נאר ס׳איז פארקערט) אן ענין פון חטאת — איז עס ווייל עס איז געטאן באופן אז עס איז דא א חסרון אין זייער חסד וצדקה, וואס דערפאר איז דאס אן ענין פון „חטאת״.\nאין דער מצוה פון צדקה זיינען דא צוויי חלקים: א) די מעשה הנתינה לעני — צושטעלן דעם עני זיינע צרכים. ב) די „איכות״ פון דער נתינה — בסבר פנים יפות, ארויסווייזן בשעת הנתינה צום עני זיין מיטגעפיל, דער (בלשון חז״ל³⁸) „והמפייסו בדברים״. און דאס איז אן עיקר בצדקה, און ווי דער רמב״ם³⁹ פסקנט: „כל הנותן צדקה לעני בסבר פנים רעות כו׳ אפילו נתן לו אלף זהובים אבד זכותו והפסידה״.\nאון אין דעם באשטייט די פלוגתא צווישן ר״ג מיט די פריערדיקע צוויי מ״ד:\nר״א און ר״י האלטן אז דער עיקר פון צדקה איז — דער „חומר״ וכמות, די פעולת הנתינה לעני. און דערפאר איז (לויט זיי) ווייבאלד די אומות העולם טוען צדקה וחסד לשם שכר איז עס א „חטאת״: ווייבאלד אז כל מטרתם דער־ביי איז צוליב שכר פאר זיך (ועד כדי כך — אז אויב זיי וועלן ניט באקומען דעם",[["34","34","אבות פ״א מ״ב."],["35","35","ב״ב י, ב."],["36","36","משלי יד, לד."],["37","37","בחדא״ג ב״ב שם. וראה גם הריטב״א ועיון יעקב לע״י שם."],["38","38","ב״ב ט, ב (אבל ראה תוד״ה והמפייסו שם)."],["39","39","הל׳ מתנות עניים פ״י ה״ד. ע״ש (ובה״ה שם). טושו״ע יו״ד סרמ״ט ס״ג־ד."]]],[1300241117,"שכר זיינען זיי זיך מתחרט⁴⁰ על הצדקה) — קומט אויס אז ס׳איז דא א חסרון אין דער מעשה הנתינה, עס איז אפגע־מאסטן לויט זייער רצון בהשכר וגודל השכר — ניט לויט צרכי העני: זיי זיינען ניט פארנומען מיט געבן דעם עני זיינע צרכים, נאר מיט באזארגן זיך מיט אריכות (שימשכו ה)ימים אדער „שתימשך מלכותן״.\nמשא״כ ר״ג האלט, אז דער עיקר פון יעדער זאך איז זיין צורה ואיכות: ועד״ז ביי צדקה, אז דער עיקר פון צדקה איז דער „והמפייסו״. ובהתאם לזה באשטייט דער „חטאת״ אין זייער צדקה וחסד (ניט אין זייער טאן לשם שכר [ווייל דאס רירט ניט אן לשיטתו דעם עיקר ניט אין צדקה], נאר) אין דעם וואס זיי טוען עס „להתייהר״ — חשיבות וגדלות הנותן, וואס דאס איז א חסרון אין דער איכות הצדקה: דער עיקר פון צדקה איז דער סבר פנים יפות, מיטפילן און מפייס זיין דעם עני, וואס דאס איז שייך נאר ווען דער נותן האלט זיך ניט העכער פון דעם עני — און דא איז די נתינת הצדקה והחסד אין אן אופן הפכי פון „והמפייסו״: „להתייהר״, גאוה וגסות הרוח!\nט. און אויך בנוגע צדקה איז דא א „צריכותא״ צו לאזן הערן דעת ר״ג — אז איכות וצורה איז מכריע — ווייל עס איז דא א חידוש אין זיין שיטה בנוגע צו צדקה לגבי דער זעלבער שיטה ביי אנדערע דברי קדושה: תפלה און „בית המדרש״ (תורה):\nענינן ועיקרן פון תורה ותפלה איז\n(ניט אזוי דער „חומר״⁴¹, נאר) די „איכות״ וצורה שלהן: דער עיקר ענין פון תורה⁴² איז⁴³ — די הבנת הענין הנלמד⁴⁴ (און אזוי אויך — און דאס איז א לימוד עמוק המביא לידי מעשה, וואס דאס איז אן ענין עיקרי אין תורה⁴⁵): ועד״ז ביי תפלה, איז עיקרה — „עבודה שבלב״⁴⁶, כוונת דע לפני מי אתה עומד⁴⁷ וכו׳.\nמשא״כ ביי צדקה איז עס להיפך: עיקר ענין הצדקה איז למלאות צרכי העני, אז ער זאל באקומען זיינע צרכים — און דערפאר קען מען אנעמען אז ס׳איז ניט בנוגע די כוונה פונעם נותן, נאר די קבלת העני. און ווי עס שטייט אין ספרי⁴⁸, אז ווען איינער איז „מאבד סלע מתוך ידו ומצאה עני והלך ונת־פרנס בה מעלה עליו הכתוב כאילו זכה״.\nאיז אויב עס וואלט געשטאנען שיטת ר״ג נאר ביי תפלה ותורה, וואלט מען געקענט זאגן, אז ביי צדקה איז ער מודה אז דער עיקר איז כמות: דארף דערי־",[["40","40","פרש״י ב״ב (י, שם) ד״ה כאן בישראל."],["41","41","אף שגם בהם צ״ל דיבור, ואדרבה — דוקא חלק הדיבור נמנה במנין המצות — ראה חידושים וביאורים בש״ס סי׳ יח."],["42","42","נוסף על הנ״ל סוף ס״ד — בנוגע לבית המדרש."],["43","43","בנוגע לתושבע״פ (ראה הנסמן בהערה הבאה), שממנה דוקא באים למעשה."],["44","44","ראה הל׳ ת״ת לאדה״ז ספ״ב. שו״ע אדה״ז או״ח ס״נ ס״ב (ממג״א שם)."],["45","45","עיין הל׳ ת״ת לאדה״ז פ״ד ה״ב־ג."],["46","46","ספרי (ופרש״י) עקב יא, יג. תענית ב, סע״א. רמב״ם ריש הל׳ תפלה."],["47","47","שמעכבת גם בדיעבד — ראה רמב״ם הל׳ תפלה פ״ד הט״ו־טז. — וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221117\" data-slug=\"likkutei-sichot\" data-id=\"1300221117\">לקו״ש חכ״ב ע׳ 117</a> ואילך ובהערה 36 שם."],["48","48","תצא כד, יט. — ולהעיר שבעל המאמר הוא ר׳ אלעזר בן עזרי׳, בר פלוגתי׳ דר״ג בענין „בית המדרש״ (ברכות שם), אבל אינו שייך להשקו״ט שבפנים — כי אין בזה פלוגתא."]]],[1300241118,"בער שטיין בפירוש זיין שיטה ביי צדקה, להשמיענו, אז אויך דא האלט ר״ג אז מען גייט בתר איכות.\nולאידך גיסא, ועוד ענין: פון שיטת ר״ג בנוגע צו צדקה וואלט מען ניט גע־קענט ארויסלערנען ווי זיין שיטה איז בנוגע תפלה ובית המדרש. ווייל ביי צדקה איז בלויז נוגע וועלכער פון די צוויי איז קובע — חומר (וכמות) אדער צורה (ואיכות) — באופן אז הכרעת האיכות מינערט ניט די כמות:\nמשא״כ ביי תפלה ובית המדרש זיינען זיי בניגוד: דורך הכרעת האיכות ווערט נתמעט די כמות: ביי בית המדרש — א כמות מועטה פון תלמידים (נאר — שתוכם כברם), אנשטאט א בית המדרש מיט ריבוי ספסלים;\nאון נאך מער ביי תפלה — וואס דער גאנצער תוכן ה„איכות״ פון א ש״ץ באשטייט אין מיעוט הכמות, אז ס׳איז ניטא קיין ריבוי (כמות) תפלות, נאר בלויז איין תפלה פאר דעם גאנצן ציבור.\nאון דעריבער וואלט מען פון זיין שיטה ביי צדקה ניט אפגעלערנט אז אויך ביי זיי גייט ער בתר איכות.\nומהנ״ל איז פארשטאנדיק אויך דער „וצריכא״ בנוגע צו די חכמים.\nיו״ד. ויש לומר, אז דער חידוש אין שיטת ר״ג (וואס מען לערנט אפ פון תפלת הש״ץ) — אז אויך אן איכות וואס איז ממעט הכמות איז מכריע — איז פארבונדן מיט ענינו של ר׳ גמליאל — אלס נשיא:\nדי נקודה עיקרית פון א נשיא איז, וואס א נשיא איז דוקא איינער⁴⁹. ע״ד ווי\nא מלך, וואס עס קען זיין א משנה למלך, פלג קיסר⁵⁰, אבער א מלך קען זיין נאר איינער [די מציאות פון צוויי מלכים קען נאר ווען זייער מלוכה איז בשני מקומות⁵¹, ע״ד מלכי יהודה ומלכי ישראל].\nדער טעם הדבר איז — ווייל א נשיא (ומלך) איז אן ענין של איכות, וכידוע⁵² אז א נשיא ומלך איז די נקודת המצי־אות פון דעם גאנצן עם, וואס דערפאר איז דער ענין פון א נשיא ומלך ניט פארבונדן מיט ריבוי הכמות — נאר להיפך: ער איז איינער, דער מועט ביותר אין כמות⁵³ — נאר זיין מעלה איז דוקא גודל האיכות (און דערפאר איז ער דער וואס איז מאחד את כל העם ומנהיגו).\nאון דערפאר איז זיין שיטה בנוגע לתפלה, אז איכות איז (ניט נאר דער עיקר, נאר עס איז) נוגע עד כ״כ — אז עס איז מכריע אפילו ווען דאס איז ממעט בתכלית די כמות.\nאון דאס איז אויך דער חילוק השיטות צווישן ר״ג מיט די חכמים, וואס זיי",[["49","49","ראה הוריות יא, ריש ע״ב. ולהעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231194\" data-slug=\"likkutei-sichot\" data-id=\"1300231194\">לקו״ש חכ״ג ע׳ 194</a>, שבזה גופא יש מעלה במלך על נשיא. ע״ש."],["50","50","סנהדרין צח, סע״ב."],["51","51","וכשכל הדור ביחד — הרי דבר אחד לדור ולא שני דברין (סנהדרין ח, א. פרש״י וילך לא, ז)."],["52","52","ראה בארוכה לקו״ש חי״ד ע׳ 1050 ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081025\" data-slug=\"likkutei-sichot\" data-id=\"1300081025\">ח״ח ע׳ 25</a>. ועוד."],["53","53","עפ״ז מובן מה שהמלך נקרא „לב כל קהל ישראל״ (רמב״ם הל׳ מלכים פ״ג ה״ו. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191165\" data-slug=\"likkutei-sichot\" data-id=\"1300191165\">לקו״ש חי״ט ע׳ 165</a> הערה 6) — כי גם ענינו של לב הוא — איכות חלוש הכמות, כמ״ש בזהר (ח״ג רכא, ב) שהלב הוא „רכיך ולשי״. וראה בארוכה לקו״ש <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031168\" data-slug=\"likkutei-sichot\" data-id=\"1300031168\">שם ע׳ 168</a> ואילך. *) משא״כ „מוח״, אף שענינו איכות, מ״מ אין הכמות שבו בחלישות. וראה בארוכה לקו״ש שם החילוק בין מוח ולב. ע״ש."]]],[1300241119,"זיינען געווען בלויז חברי סנהדרין, וואס דער ענין פון (חברי) סנהדרין איז — ריבוי הכמות. ווארום סנהדרין מוז האבן דעם ריבוי פון ע״א, און אז עס פעלט אפילו איינער פון זיי והקטן שבהם איז דאס ניט קיין סנהדרין⁵⁴.\nאון דערפאר איז זייער פלוגתא כללית, כנ״ל — צי ריבוי הכמות איז מכריע איכות, אדער להיפך, און ווי דאס איז מודגש בפלוגתתם בנוגע לענין התפלה: די חכמים האלטן אז „(תפלת) הצבור עיקר״ — (בדוגמת חברי הסנ־הדרין וואס האט געמוזט זיין ע״א סנ־הדרין);\nמשא״כ ר״ג האלט אז „(תפלת) הש״ץ עיקר״, ווייבאלד אז דער ש״ץ איז די נקודת האיכות פון דעם גאנצן צבור — בדוגמת הנשיא⁵⁵, וואס ער איז די נקודת האיכות פון דעם גאנצן עם.\n(משיחות ו׳ תשרי ויום שמח״ת תשל״ז)",[["54","54","הוריות ג, ב."],["55","55","להעיר מקריאת המלך בהקהל, וברמב״ם הל׳ תגיגה פ״ג ה״ז: כיום שניתנה בו בסיני כו׳ ומפי הגבורה שומעה, שהמלך שליח הוא כו׳."]]],[1300241120,"<h3>שופטים</h3>\nא. בנוגע צו דער מצוה פון מינוי מלך — שום תשים עליך מלך¹) — איז ידועה די שאלה²):\nבשעת אידן האבן געבעטן ביי שמואל הנביא „תנה לנו מלך“ איז ער דערפון געווען זייער אומצופרידן³), און אויך דער אויבערשטער האט געזאגט „כי אותי מאסו גו'“⁴ — ולכאורה, דאס איז דאך א מצוה וואס דער אויבערשטער האט אנגעזאגט אידן? ובפרט לויטן מאמר חז\"ל⁵ „ג' מצות נצטוו ישראל בכניסתן לארץ להעמיד להם מלך כו'“ — וואס דערפון איז מובן, אז דאס איז א מצוה נעלית ביותר, ואפילו פון די מצות התלויות בארץ.\nאון ווידער, אויב זייער מאנען א מלך אין יענעם זמן איז געווען א דבר בלתי רצוי — פארוואס האט דער אוי־בערשטער דאמאלס אנגעזאגט שמואל הנביא אז ער זאל נאכגעבן אידן און ממנה זיין א מלך אויף זיי?\nב. אין חסידות⁶) איז דעם מבואר, אז דער מכוון פון מינוי מלך איז אויף צוויי אופנים (זה למעלה מזה):\nא) א טעם פשוט, ווייל (בלשון המשנה⁷) „אלמלא מוראה (של מלכות) איש את רעהו חיים בלעו“ — אז דער מלך זאל אנפירן און אויפטאן אז די הנהגה פון די אנשי המדינה זאל זיין כראוי.\nאפילו ווען דער שכל פארשטייט אז מ'דארף זיך פירן כדבעי, איז עס אבער ניט גענוג, ווייל העין רואה והלב חומד וכו'⁸ — און דערפאר דארף מען אנקו־מען צו יראת המלך, וואס פועלט אז מען זאל זיך פירן בדרך הישר.\nב) ווען דער מצב איז אז המוח שליט על הלב בתמידיות — איז ניט נויטיק א מינוי מלך לענין האמור; עס זיינען אבער דא אזעלכע ענינים, וואס דער עם האט ניט קיין דעת צו פארשטיין ווי מען דארף זיך פירן בהם — נאר דער מלך מצד מעלתו וואס משכמו ומעלה גבוה מכל העם⁹ פארשטייט זיי, און ער גיט ארויס פקודות ווי מען זאל זיך פירן — און די אנשי המדינה טוען אזוי, ווייל אזוי האט דער מלך געהייסן.\nאון דאס איז דער ענין פון מינוי מלך (בפנימיותו ובשרשו) ביי עם ישראל — וואס זייער אדון מלך איז דער אוי־בערשטער, און דער מלך בשר ודם, וואס מ'איז ממנה, איז דער ממוצע וואס איז מגלה מלכותו ית' צו אידן:\nאידן מצד עצמם זיינען מאמינים, פארשטייען און פילן אז זייער חיות נעמט זיך פון (מלכותו של) הקב\"ה, וואס דאס דארף ביי זיי ארויסרופן דעם",[["1","1","פרשתנו יז, טו."],["2","2","אברבנאל פרשתנו „הספק העשירי“. ושם לאח\"ז מביא תי' כו\"כ מפרשים, ע\"ש. כלי יקר פרשתנו עה\"פ. רד\"ק ש\"א ח, ה. וראה סנהדרין כ, ב. רמב\"ם הל' מלכים פ\"א ה\"ב. ועוד."],["3","3","ש\"א שם, ו. וראה שם יב, יב ואילך."],["4","4","שם, ז."],["5","5","סנהדרין שם. ספרי ראה (יב, י). ועוד. רמב\"ם ריש הל' מלכים."],["6","6","סהמ\"צ להצ\"צ מצות מינוי מלך פ\"א ופ\"ג, ע\"ש באורך (בהבא לקמן ס\"ב־ג)."],["7","7","אבות פ\"ג מ\"ב."],["8","8","רש\"י שלח טו, לט."],["9","9","ש\"א ט, ב. ונת' באוה\"ת בראשית (כרך ד) ע' 1528. שם שה\"ש (כרך ב) ע' תיד־טו. ועוד."]]],[1300241121,"ביטול צום אויבערשטן. בשעת אבער זיי זיינען אין א מצב און ביי זיי פעלט אט דער ביטול, דארפן זיי אנקומען צו א מלך בשר ודם, וואס דורך מורא מלכותו וכו' וערט ביי זיי אויפגעטאן א יראה וביטול צו מלך מלכי המלכים הקב\"ה.\nאבער בשעת אידן זיינען ווי עס דארף צו זיין און עס איז ביי זיי פאראן דער ביטול צו אלקות מצד עצמם, דעמאלט איז דער אויפטו פון (מינוי) מלך אין א העכרן אופן: די מדריגות אין אלקות צו וועלכע אידן קענען מצד עצמם ניט צוקומען, ווייל די מדריגות זיינען העכער פון זייער השגה — איז דער מלך (וואס מצד מעלתו כנ\"ל האט ער א השגה אויך אין זיי) ממשיך ומשפיע זיי צו עם ישראל — און דאס פועלט בא אידן אויך א העכרן אופן פון יראה וביטול, א ביטול וואס איז העכער פון זייער הבנה והשגה.\nג. עפ\"ז ווערן פארענטפערט די שאלות הנ\"ל:\nשמואל הנביא האט געוואלט אז דער מצב פון אידן זאל זיין אין אן אופן אז זיי זאלן שטיין מיט א ביטול צו אלקות מצד עצמם, ניט אנקומענדיק צו א מלך — און דער מלך זאל ביי זיי פועל זיין די העכערע דרגא פון ביטול און יראה (בכלל — יראה עילאה); אידן האבן אבער געבעטן א „מלך לשפטנו ככל הגוים“¹⁰ — א מלך וואס זאל זיי בא־וארענען פון „איש את רעהו חיים בלעו“ — וואס דאס ווייזט אז ביי זיי האט געפעלט די דרגא פון יראת שמים, וואס אידן דארפן האבן מצד עצמם. און דערפאר האט דער אויבערשטער גע־זאגט „כי אותי מאסו גו'“ — עס פעלט ביי זיי יראת שמים.\nאון ס'איז מובן, אז אפ\"כ האט זיי דער אויבערשטער „נאכגעגעבן“ און געהייסן ממנה זיין א מלך — ווייל ווען בא א אידן פעלט ביראה, מאיזו סיבה שתהי', איז אע\"פ אז ער דארף אליין, און דער השפעה פון מלך, צוקומען צו דעם ביטול — דאך קען מען ניט וארטן — און ביז דעמאלט זאל ער זיין ח\"ו א איד אן עול מלכות שמים:\nער דארף אויף זיך תיכף אננעמען א מלך, וואס זאל אים באוארענען אין די ענינים: און דערנאך במשך הזמן, וועט ער מצד עצמו צוקומען צו דער דרגא פון ביטול און יראה, ביז אויך צו די דרגות פון סוג הב' דורך א מלך, כנ\"ל.\nד. פון יעדן ענין דארף מען ארויס־נעמען א הוראה אין עבודת ה':\nאע\"פ אז בזמן הגלות איז ניטא קיין מלך — זאגן אבער חז\"ל¹¹ „מאן מלכי רבנן“. אזוי ווי עס איז דא די מצוה פון מינוי מלך, עד\"ז האט א איד אויף זיך דעם ציווי פון מלכי רבנן „עשה לך רב“¹².\nאון אויף דעם איז די הוראה פון ענין הנ\"ל: עס זיינען פאראן אזעלכע וואס מיינען, אז בנוגע די נידעריקע ענינים קענען זיי אליין פארשטיין און מחליט זיין, ובמילא דארפן זיי וועגן דעם ניט פרעגן בא א „רב“.\nדי משנה זאגט „עשה לך רב“, יעדער איד דארף האבן א „רב“ — זיי טראכטן אבער, אז דערמיט ווערן געמיינט די",[["10","10","ש\"א ח, ה. ועד\"ז שם, כ. — ומש\"נ בפרשתנו (שם, יד) „אשימה עלי מלך ככל הגוים אשר סביבותי“ — ראה רמב\"ן שם, דמש\"נ „אשימה עלי גו'“ הוא „מרמיזותיו על העתידות שכן הי' כששאלו להם כו'“, אבל אי\"ז מעלת ענין המלוכה כפי שצ\"ל ע\"פ תורה."],["11","11","ראה גיטין ספ\"ה."],["12","12","אבות פ\"א מ\"ו ומט\"ז."]]],[1300241122,"ענינים נעלים; ווען עס קומט אבער צו ענינים פשוטים, איז ער א מאמין בעצמו, ער דארף ניט אנקומען צו השפעה פון א רב. דאס קען ער אליין אויפטאן.\nאי, עס גייט דורך א משך זמן און ער שטייט נאך אלץ אין זעלבן מצב נמוך — פונדעסטוועגן מיינט ער, איז ניט כדאי דערמיט צו גיין צום „רב“. ער וועט וארטן „עד שיערה עליו רוח ממרום“, ביז ער וועט נתעורר ווערן מיט יראה כדבעי און מתקן זיין אלץ וואס ער דארף מתקן זיין — בכח עצמו.\nאויף דעם איז די הוראה פון מינוי מלך ברוחניות איצטער: הגם אז (כנ\"ל — בא אידן) איז ענינו ופעולתו של מלך בעיקר שייך בנוגע צו העכערע מדריגות, אבער ווען ס'איז א מצב פון „אותי מאסו“, ח\"ו, אדער א חשש אויף דעם — דארף מען גלייך נוצן מורא המלך אויף דעם.\nה. עס זיינען פאראן אויך אזעלכע וואס זאגן, אז זיי געפינען ניט פאר זיך קיין „רב“. דארפן זיי וויסן אז דאס איז מעצת ופיתוי היצר. ווארום לא אלמן ישראל¹³, און ס'איז ניט שייך די מציאות, אז צווישן אידן זאל ניט זיין איינער וואס האט מער אהבת ה' ויראת ה' פון אים — און קען במילא זיין פאר אים א „רב“¹⁴. נאר דערויף דארף זיין עשה (אויך פון ל' מעשין על הצדקה¹⁵, כפיית ישות עצמו) און יגיעה — ער דארף זיך מתיגע זיין און זוכן, ביז ער וועט געפינען א „רב“.\nווארום אויף זיך טאר מען זיך ניט פאר־לאזן¹⁶ — מען מוז האבן א „רב“. און יגעת ומצאת¹⁷ — אויב ער וועט הא־רעווען און זוכן מיט אן אמת וועט ער געפינען א רב.\nאון דער „רב“ וועט מיט אים „איינ־לערנען“ די פרשיות וואס דער מלך פלעגט לייענען בהקהל — שמע און והי' אם שמוע¹⁸ וכו': פריער שמע וואס איז קבלת עול מלכות שמים¹⁹, און דערנאך „והי' אם שמוע גו' (און) ואספת דגניך“, ער וועט אים געבן צו פארשטיין אויך אין השגה אז דער „ואספת דגניך“ איז תלוי אין דעם „שמוע תשמער“:\nאון נאכדעם ווי דער „רב“ וועט ביי אים מעורר זיין די נידעריקע דרגא פון ביטול און קבלת עול, וועט ער אויף אים דערנאך ממשיך זיין די העכערע מדריגה — יראה עילאה.\nאון כהנ\"ל האט א שייכות מיוחדת צו עקבתא דמשיחא, ערב ביאת משיח צדקנו — וואס ענינו איז דאך ביידע זאכן²⁰: רב (ילמד תורה אלעמען — אפילו לאבות ומשה רבנו²¹) און מלך — מלכא משיחא.\n(משיחת שמחת בית השואבה, שנת הקהל, תשי\"ג)",[["13","13","ראה ב\"ר (פנ\"ו, ז) „אין דור שאין בו כמשה“."],["14","14","להעיר מפי' הרמב\"ם ורבינו יונה לאבות שם."],["15","15","ב\"י לסי\"ד סרמ\"ח. נת' בד\"ה ועבדי דוד תרצ\"ם. וראה לקו\"ת בחוקותי מת, א."],["16","16","כמחז\"ל (אבות פ\"ב מ\"ד) אל תאמין בעצמך."],["17","17","מגילה ו, ריש ע\"ב."],["18","18","סוטה מא, א (במשנה). רמב\"ם הל' תגיגה פ\"ג ה\"ג. — נת' לקמן ע' 204 ואילך."],["19","19","ברכות רפ\"ב (במשנה). הובא בפרש\"י סוטה שם ד\"ה ושמע."],["20","20","סהמ\"צ להצ\"צ שם."],["21","21","לקרית צו יו, א. ש' האמונה פנ\"ו ואילך. סהמ\"צ שם."]]],[1300241123,"<h3>שופטים ב</h3>\nא. נאָך דעם ציווי (בפרשתנו<sup data-n=\"1\">1</sup>, אַז „כי יכרית ה\"א את הגויים גו' וירשתם גו'\" זאָל מען אויסטיילן2 ג' ערי מקלט — „והי' לנוס שמה כל רוצח\"3 — איז דער פסוק ממשיך ומוסיף4: „ואם ירחיב ה\"א את גבולך כאשר נשבע לאבותיך ונתן לך את כל הארץ אשר דבר לתת לאבותיך . . ויספת לך עוד שלש ערים על השלש האלה\". שטייט אין ספרי (וירושלמי<sup data-n=\"5\">5</sup> געבראַכט אין רש\"י על אתר, אַז דער ציווי באַציט זיך צום זמן דלעת\"ל, ווען אידן וועלן באַקומען אויך „ארץ קני וקניזי וקדמוני\"6: און אַזוי פסק'נט אויך דער רמב\"ם7: „בימי המלך המשיח מוסיפין שלש אחרות על אלו השש . . והיכן מוסיפין אותן בערי הקני\nוהקניזי והקדמוני שנכרת לאברהם אבינו ברית עליהן כו'\".\nאיז ידוע אין דעם די שאלה8: צו וואָס וועט מען דאַרפן (נאָך) מוסיף זיין לעת\"ל נאָך ערי מקלט? — לכאורה וועלן דאָך דעמאָלט ניט זיין קיין רוצחים9 אפילו ביי די אומות העולם — ווי דער נביא זאָגט10 „לא ישא גוי אל גוי חרב\"11 —\nאון אע\"פ אַז ערי מקלט זיינען בעיקר צוליב אַ הורג נפש בשגגה — איז דאָך אָבער אויך די מציאות פון הריגת נפש בשגגה ניט שייך לעת\"ל, הן מצד הנהרג והן מצד ההורג:",[["1","1","יט, א ואילך."],["2","2","ל' הכתוב בפרשתנו (יט, ב. ז): שלש ערים תבדיל לך. וברמב\"ם (הלכות רוצח רפ\"ח): מ\"ע להפריש ערי מקלט שנאמר שלש ערים תבדיל לך. בהמצות שבהכותרת להל' רוצח (מצוה ט): להפריש ערי מקלט ולכוין• להם הדרך (ומשמע שג\"ז „לכוין להם הדרך\" בכלל המצוה). ובסהמ\"צ מ\"ע קפב: להכין•• שש ערי מקלט כו' ושיתקן דרך אליהם כו'. ומביא הכתוב (יט, ג) תכין לך הדרך. ובמנין המצות בריש ספר היד: להכין שש ערי מקלט שנאמר תכין לך הדרך ושלשת. ואכ\"מ."],["3","3","יט, ג."],["4","4","שם, ח-ט."],["5","5","מכות פ\"ב ה\"ז. וראה תוספתא מכות ספ\"ב."],["6","6","פרש\"י כאן, ח."],["7","7","הל' רוצח פ\"ח ה\"ד."],["8","8","זית רענן (להמג\"א) לי\"ל\"ש כאן. ומסיים: ועי' בכוונת האר\"י. וראה לי\"ת, ספר הליקוטים (להאריז\"ל) ושער המצות פרשתנו עה\"פ. ש\"ך עה\"ת עה\"פ. של\"ה בית דוד בסופו (כד, רע\"א ואילך). משכיל לדוד לפרש\"י כאן. ועוד."],["9","9","כ\"ה הלשון בל\"ת וספר הליקוטים ושער המצות שם „שלא יהיו רוצחים\", „שאז ירבו הרוצחים\". ולכאורה לשון זה מתאים על הורג נפש במזיד• [שגם מזיד מקדים לערי מקלט (מכות י, ב. רמב\"ם הל' רוצח פ\"ה ה\"ז)]. אבל גם בפרשתנו נאמר (יט, ד••. ו) לשון זה (רוצח) על הורג נפש בשגגה. וכן בפ' מסעי (לה, יא. כה ואילך). וכ\"ה במדרשי חז\"ל, וברמב\"ם בכ\"מ (ראה רמב\"ם שם ה\"ב, ה\"ט. ועוד). ואכ\"מ."],["10","10","ישעי' ב, ד."],["11","11","כ\"ה בל\"ת וספר הליקוטים ושער המצות שם. ועד\"ז בזית רענן שם. וראה הערה 17. •) עיין רשב\"ם יתרו כ, יג. ואכ\"מ. ••) הלשון בפסוק ג' „כל רוצח\", י\"ל בדוחק שבזה נכלל גם מזיד כיון שגם הוא מקדים בתחלה, כנ\"ל. אבל מהמשך הפרשה (יט, יא) לא משמע כן. ואכ\"מ. •) ובמנין המצות על סדר הלכות הרמב\"ם בריש ס' היד: ולהכין לו הדרך. וראה רמב\"ם ס' המדע (ירושלים תשכ\"ד) בש\"נ: ולכוין (כבפנים), לכונן. ••) בהוצאת הר\"ח העליר והר\"י קאפח „להבדיל\". ועד\"ז הוא בחינוך מצוה תקכ."]]],[1300241124,"דאָס גופא וואָס אַ מענטש ווערט געהרג'ט איז אַ באַווייז אַז אים קומט אַ חיוב מיתה, ווי די גמרא12 זאָגט אויפן פסוק13 „ואשר לא צדה והאלקים אנה לידו — במה הכתוב מדבר בשני בני אדם שהרגו את הנפש אחד הרג בשוגג ואחד הרג במזיד (ואין עדות וכו') הקב\"ה מזמינן לפונדק אחד זה שהרג במזיד יושב תחת הסולם, וזה שהרג בשוגג יורד בסולם ונופל עליו והורגו זה שהרג במזיד נהרג וזה שהרג בשוגג גולה\" — און וויבאַלד אַז לעת\"ל וועט ניט זיין קיין פאַל פון אַ הורג במזיד, וועט דאָך במילא ניט זיין אַזאַ איינער וואָס זאָל זיין מחוייב מיתה, אַז ער זאָל דאַרפן געהרג'ט ווערן בשוגג.\nאון אַזוי אויך מצד דעם הורג נפש בשגגה — ווארום ס'איז דאָך ידוע14, אַז דאָס עובר זיין אויף אַן עבירה בשוגג קומט דערפון וואָס מ'האָט עפעס אַ שייכות (מעין עכ\"פ, ווי לעיל בא„והאלקים אנה לידו\") צו דעם (רע שבה)חטא (וואָס דערפאַר „כל השוגגין צריכים כפרה\"<sup data-n=\"15\">15</sup> — און היות אַז לעת\"ל וועט נתבטל ווערן דער רע אין וועלט16,\nוועט דאָך במילא אויך ניט זיין קיין ארט אויף צו באַגיין אַן עבירה אפילו בשוגג17.\nב. ס'זיינען דאָ מפרשים18 וואָס לער־נען, אַז דאָס וואָס מ'וועט לעת\"ל מפריש זיין נאָך דריי ערי מקלט איז — „למצוה\", אדער בלשון המנ\"ח19 „והוא גזה\"כ (כי מצד הסברא לא יצטרכו לערי מקלט לע\"ל כי רק שלום ואמת וטוב יהי' בימי המלך המקוה ב\"ב רק גזה\"כ לעשות המצוה הזאת וגזה\"כ שיהי' ס\"ה תשעה)\".",[["12","12","מכות י, ב. פרש\"י משפטים כא, יג. וראה פרש\"י נח ט, ה."],["13","13","משפטים שם."],["14","14","ראה ל\"ת להאריז\"ל ויקרא (טעמי המצות שם מצות על כל קרבנך תקריב מלח). אגה\"ק סו\"ס כח."],["15","15","(וזהו כל ענין קרבן חטאת וכו') — פרש\"י ריש מס' שבועות ד\"ה תולה. פרש\"י נח שם. וידוע השקו\"ט בשוגג דרבנן הצריך כפרה (ראה נתה\"מ סרל\"ד סק\"ג. שו\"ת תורת חסד או\"ח סל\"א. אתוון דאורייתא כלל יוד. שו\"ת מנחת אלעזר (מונקאטש) ח\"ג סי\"ב (ובמפתחות שם). ולכאורה טעם האריז\"ל הנ\"ל הוא גם בדרבנן)."],["16","16","כ\"ה הקושיא בשל\"ה שם „בודאי לא יקרה שום רע אפי' כי הרע יכלה מהעולם ולא יהי' רק טוב בהחלט\"."],["17","17","בשער המצות שם מביא בהקושיא (נוסף על הכתוב „לא ישא גוי אל גוי חרב\") „וכתיב לא ירעו ולא ישחיתו וגו' וכתיב בלע המות לנצח וגו' ואם כן איך ולמה נצטווינו לעתיד לבוא להוסיף ג' ערי מקלט אחרות כנראה שאז ירבו הרוצחים\". ולכאורה משמע שהקושיא היא גם על הריגה בשוגג ועל עצם ענין המיתה. אמנם מסיים שם בהתירוץ „אך לא במזיד שהרי אז לא ישא גוי אל גוי חרב גו' אלא יהי' בשוגג ועי\"כ יתרבו הרוצחים בשוגג כו' אבל דע לך כי לא ישפך דם נקי כו' ר\"ל שלא יהי' במזיד רק בשוגג כנז' כי הכי כתיב ואת רוח הטומאה אעביר מן הארץ\" (ועד\"ז הוא בל\"ת וספר הליקוטים שם בקיצור). אבל בשל\"ה שם משמע דהקושיא היא גם על הורג נפש בשגגה (כנ\"ל הערה 16 [ושם בסוף העמוד מקשה על מה שביחזקאל מוכיר טומאת מת לאביו ולאמו יטמאו הלא כתיב בלע המות לנצח]). ולכאורה כן צריך לפרש גם בהאריז\"ל שם שמחלק שם בהתירוץ שתלוי אם הקץ יהי' „בעתה\" או „אחישנה\" ודוקא אז (אחישנה) יהי' שייך הורג נפש בשגגה. וראה ספר המאמרים תקס\"ה ס\"ע תשצט שמביא הקושיא מל\"ת להאריז\"ל „איך יתכן שיצטרך ערי מקלט לרוצחים בשוגג לעל\"ל\". ואולי בכהאריז\"ל אין הכוונה הריגת נפש בשוגג כפשוטו, כ\"א רק להענין ברוחניות (עד\"ז הקבלה, ראה שם התיקון לזרעו של הבל כו'). ודוחק. ואכ\"מ. וראה תו\"ח שמות ד\"ה ענין קין והבל. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי ע' א'תטו</a>."],["18","18","זית רענן בתירוץ הב'."],["19","19","מצוה תקכ."]]],[1300241125,"עס איז אָבער לכאורה שווער אַזוי זאָגן, ווארום אין דער פרשה גופא, בהמשך צום ציווי „אם ירחיב ה\"א את גבולך גו' ויספת לך עוד שלש ערים\" פירט אויס דער פסוק און זאָגט דעם טעם: „ולא ישפך דם נקי בקרב ארצך אשר ה\"א נותן לך נחלה\"20, אַז אויך דעמאָלט וועלן די ערי מקלט זיין פאַר־בונדן מיט אַ הורג נפש.\nג. עס זיינען פאַראַן מפרשים21 וואָס זאָגן, אַז דער צורך פון די ערי מקלט לעת\"ל וועט זיין נאָר אין דעם זמן פון תחילת ימות המשיח, וואָס דאָמאָלט איז „אין בין העוה\"ז לימות המשיח אלא שעבוד מלכיות בלבד\"22; משא\"כ אין דער שפעטערדיקער תקופה פון ימות המשיח23 — „בהמשך זמן שתתרבה הדעה בישראל\" — „אז לא יצטרכו לערי מקלט\"24.\nועפ\"ז קומט אויס, אַז פון דעם ציווי „ואם ירחיב ה\"א את גבולך\" — צו מוסיף זיין ג' ערי מקלט לעת\"ל — איז אַ ראי' צו דער דיעה הנ\"ל און שיטת הרמב\"ם25, אַז „אין בין העוה\"ז לימות המשיח אלא שיעבוד מלכיות בלבד\", (בתחלת זמן המשיח עכ\"פ<sup data-n=\"23\">23</sup>, ווי דער רמב\"ם איז מאריך בספרו26: „ואל יעלה על הלב שבימות המשיח יבטל דבר ממנהגו של עולם או יהי' שם חידוש\nבמעשה בראשית אלא עולם כמנהגו נוהג\"27. און במילא וועט אויך זיין שייך די מציאות פון הורג נפש (בשגגה<sup data-n=\"28\">28</sup>.\nדערמיט וואלט מען אויך געקענט מסביר זיין אַ דיוק אין רמב\"ם: נאָך דעם ווי דער רמב\"ם29 רעדט וועגן דער אמונה בביאת המשיח, אַז „כל מי שאינו מאמין בו כו' לא בשאר הנביאים בלבד הוא כופר אלא בתורה ובמשה רבינו שהרי התורה העידה עליו שנאמר כו' אף בפרשת בלעם נאמר כו'\", איז ער ממשיך און ברענגט נאָך אַ ראי' אין אַ באַזונדערע הלכה30: „אף בערי מקלט הוא אומר ואם31 ירחיב ה\"א את גבולך ויוספת לך עוד שלש ערים כו' ומעולם לא הי' דבר זה ולא צוה הקב\"ה לתוהו\" — ולכאורה איז ניט מובן: פאַרוואָס טיילט אויס דער רמב\"ם די ראי' אין אַ הלכה בפ\"ע?\nוע\"פ הנ\"ל י\"ל, אַז דערמיט ויל דער רמב\"ם מרמז זיין32, אַז די ראי' פון ערי מקלט באַציט זיך ניט נאָר צו דעם וואָס ער זאָגט אין דער הלכה שלפנ\"ז (וועגן ביאת המשיח בכלל), נאָר אויך צום תוכן המדובר אין דער הלכה שלאח\"ז33 —",[["20","20","ודוחק גדול לומר דקאי רק אלפני פניו."],["21","21","של\"ה שם. ואולי זוהי גם הכוונה בזית רענן שם (בתירוצו הא') „וי\"ל דמיירי לימות המשיח\". וראה ש\"ך עה\"ת. משכיל לדוד כאן."],["22","22","ברכות לד, ב. וש\"נ."],["23","23","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151430\" data-slug=\"likkutei-sichot\" data-id=\"1300151430\">לקו\"ש חט\"ו ע' 417</a> ואילך. וש\"נ."],["24","24","של\"ה שם."],["25","25","הל' תשובה ספ\"ט. הל' מלכים פי\"ב ה\"ב."],["26","26","רפי\"ב שם."],["27","27","והראב\"ד פליג שם."],["28","28","בש\"ך עה\"ת כאן: „אע\"פ שהוא (הרמב\"ם) הולך לשיטתו שכתב כו' עולם כמנהגו נוהג, עם כל זה אין עולה על הדעת שיהי' באותו הזמן רצחנים\". וצ\"ע, שהרי עיקר ענין ערי מקלט הוא להורג נפש בשגגה, ולמה אין עולה על הדעת שיהי' הורג נפש בשגגה כשעולם כמנהגו נוהג."],["29","29","הל' מלכים שם פי\"א ה\"א."],["30","30","שם הלכה ב."],["31","31","בדפוסים לפנינו „אם\". אבל בדפוס ראשון „ואם\" כבכתוב. ובכו\"כ כת\"י הרמב\"ם „כי\" במקום „אם\"."],["32","32","הביאור בזה בפשטות — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181289\" data-slug=\"likkutei-sichot\" data-id=\"1300181289\">לקו\"ש חי\"ח ע' 280</a>. חל\"ד ע' 114 ואילך."],["33","33","הלכה ג."]]],[1300241126,"„ואל34 יעלה על דעתך שהמלך המשיח צריך לעשות אותות ומופתים ומחדש דברים בעולם או מחי' מתים וכיוצא בדברים אלו אין הדבר כך שהרי רבי עקיבא כו'\" (און ברענגט די ראי' פון בן כוזיבא) —\nאויך אויף דעם (אַז עס וועט דאַן ניט זיין קיין חידוש דבר בעולם) איז דאָ אַ הוכחה פונעם ציווי צו מוסיף זיין ערי מקלט לעת\"ל, וואָס לערנט אונז אַז אויך בימות המשיח וועט זיין „עולם כמנהגו נוהג\". ובמילא איז מובן אַז ניט דאָס איז ענינו פון משיח'ן און ניט דאָס איז די בחינה אַז ער איז משיח.35\nד. עס איז אָבער שווער אַזוי צו לערנען אין רמב\"ם:\nאויב דער רמב\"ם מיינט צו זאָגן אַז פון דער הוספת ערי מקלט איז אַ ראי' מוכחת אַז מלך המשיח דאַרף ניט מאַכן קיין „אותות ומופתים ומחדש דברים בעולם\", וואָלט ער דאָס געזאָגט בפירוש (ובפרט אַז דאָס איז אַ ראי' פון אַ פסוק וציווי בתורה, און די ראי' וואָס ער ברענגט פון בן כוזיבא איז פון דברי ודרשת רז\"ל).\nנאָך מער: פון דעם סגנון הלשון, מיט וועלכן דער רמב\"ם הויבט אָן די הלכה (ג) שלאח\"ז: „ואל יעלה על דעתך שהמלך המשיח צריך לעשות אותות ומופתים ומחדש דברים בעולם\" (און ניט „ואין המלך המשיח צריך לעשות כו'\") איז משמע, אַז אויך נאָך דער הלכה (ב) וועגן ערי מקלט לעת\"ל קען זיין אַ קס\"ד („יעלה על דעתך\") אַז משיח\n„צריך לעשות אותות כו'\" נאָר מען איז עס שולל ווייל ר' עקיבא כו'.\nד.ה. אַז פון דעם ציווי להוסיף ערי מקלט לעת\"ל איז קיין ראי' ניט אַז משיח וועט ניט דאַרפן ווייזן קיין אותות ומופתים כו'.\nועפ\"ז איז מובן, אַז ס'איז אויך קיין ראי' ניט פון דעם אַז עס וועט ניט זיין שינוי מנהגו של עולם36.\nה. וי\"ל דעם ביאור אין דעם:\nפון הוספת ערי מקלט לעת\"ל איז קיין ראי' ניט אַז דעמאָלט וועט זיין עולם כמנהגו נוהג, ווייל די ערי מקלט וועלן זיין צוליב אַ הורג נפש בשגגה לפני זה — בזמן הזה37. און זייענדיק דעמאָלט אין די ארצות קני קניזי וקדמוני38 וועט ער דאַרפן גולה זיין אין אַן עיר מקלט39.\nווי מען געפינט ביי חיוב חטאת, אַז ר' ישמעאל40 כתב על פנקסו אַז „כשיבנה ביהמ\"ק אביא חטאת שמינה\"41.",[["34","34","כ\"ה בדפוסי הרמב\"ם. ובכמה כת\"י הגירסא „אל\"."],["35","35","ראה מ\"ש במאמר תחיית המתים רפ\"ז. וראה לקו\"ש חי\"ח <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181289\" data-slug=\"likkutei-sichot\" data-id=\"1300181289\">שם ע' 280</a> ואילך."],["36","36","וכדמשמע גם מלשון הרמב\"ם שם רפי\"ב „אל יעלה על הלב שבימות המשיח יבטל דבר ממנהגו של עולם\", שיכול להיות קס\"ד שיבוטל דבר ממנהגו של עולם גם לאחרי שידעינן ע\"ד הוספת ערי מקלט לעת\"ל (ושהבחינה על משיח אינה בזה שצריך לעשות אותות כו' או לחדש דבר בעולם). וראה בפנים."],["37","37","ראה אלשיך כאן סוף פסוק ח."],["38","38","ובפרט להדיעות שהן ארץ אדום עמון ומואב (ראה אנציקלופדי' תלמודית ערך ארץ אי\"ע' רה. וש\"נ), שגם לפני ביאת המשיח נמצאים שם יהודים."],["39","39","גם להדיעה שהובאה בריטב\"א (מכות יא, ב) „דבעינן כה\"ג המכפר שיהא נמצא בשעת רציחה\" ואם לאו אינו יוצא משם לעולם — י\"ל דזהו דוקא באם יש אפשריות שיהי' כה\"ג, משא\"כ בנדו\"ד אין זה מעכב. ועוד דשיהי' כה\"ג — הוא בשעת גמר דין (משנה מכות שם). ולהעיר מענין דלאו מינה לא מחריב בה (זבחים ג, א)."],["40","40","שבת יב, ב."],["41","41","וראה יומא פ, א ופירש\"י שם. אנציקלופדי' תלמודית ערך חטאת בסופו (ע' תקג). ואף את\"ל"]]],[1300241127,"און אע\"פ אַז דער טעם פון הבדלת ערי מקלט — „להכין לך הדרך וערי מקלט רבים\"42 — איז: „פן ירדוף גואל הדם אחרי הרוצח כי יחם לבבו והשיגו כי ירבה הדרך והכהו נפש\"43 — כדי קענען אַנטלויפן פון דעם גואל הדם44, און דערפאַר „אם ירחיב ה\"א את גבולך גו' ויספת לך עוד שלש ערים\", אַז אויך דעמאָלט זיינען די ערי מקלט אַ מקום הצלה פון גואל הדם —\nולכאורה איז יחם לבבו גו' ניט שייך לעת\"ל,\nזאָגט מען דאָך אָבער בספרי בפר־שתנו — „מצוה ביד גואל הדם לר־דוף\"45; און וויבאַלד ס'איז אַ מצוה46, איז מובן, אַז דאָס איז שייך אויך לעת\"ל.\nובמילא דאַרפן זיין די ערי מקלט כדי צו אַנטלויפן פון דעם גואל הדם47.\n[במשנה48 איתא אַז מצוה ביד גואל הדם צו הרג'נען דעם רוצח, נאָר אין פאַל פון אַ רוצח שיצא חוץ לתחום (ערי מקלט) ומצאו גואל הדם, אָבער ניט ווען ער האַלט ערשט ביים אַנטלויפן אין עיר מקלט,\nאָבער כדי שלא לאפושי במחלוקת יש לומר49, אַז אויך לויט דער דיעה, מיינט עס ניט אַז דוקא דעמאָלט (לאחר ווי ער איז אַריין אין עיר מקלטו און פון דאַרט אַרויס חוץ לתחום) ווערט דאַן נתחדש די מצוה פון גואל הדם50, אָבער איידער דער רוצח קומט לעיר מקלטו איז אַן איסור אויפן גואל הדם צו הרג'נען דעם",[["","","ע\"פ משנ\"ת שאי\"ז חיוב על כ\"א, ושלימות הכפרה נעשית ע\"י התשובה שבזמן הזה (ראה לקו\"ש חי\"ח שם ע' 416. ובארוכה בשיחת ר' תשרי תשמ\"א) — יש לומר, דשאני גלות שהוא לא רק כפרה כקרבן, אלא גם גדר עונש. ואף שחיוב קרבן חטאת הוא מצות היחיד, והמצוה דגלות היא מצות הבי\"ד ד„מצות עשה להגלותו\" (רמב\"ם רפ\"ה מהל' רוצח. סהמ\"צ ומנין המצות מ\"ע רכה), הרי „גם המכה הוא בכלל מ\"ע זו שנאמר\" (מסעי לה, כח) עליו כי בעיר מקלטו ישב עד מות הכהן הגדול\" (חינוך מצוה תי בתחלתה). ואף שזהו לאחר גמר דין, הרי גם בתחלה חיוב עליו (משום הגנה, כדלקמן בפנים). וראה לקמן הערה 47."],["42","42","פרש\"י פרשתנו יט, ו."],["43","43","שם."],["44","44","ולהעיר מחדא\"ג מהרש\"א מכות י, ב — דעיקר חובת גלות מפני גואל הדם שלא יהרגנו, וכשאין חשש זה אין חובת גלות. אבל כבר הקשו על דבריו שמוכח בכ\"מ דכשאין גואל דם חייב לגלות. (ראה ספרי פרשתנו שם ה\"ו. ועוד)."],["45","45","ראה ספרי דבי רב לספרי שם."],["46","46","ראה בארוכה ביאור הרי\"פ פערלא לסהמ\"צ לרס\"ג ח\"ג פרשה יז, שגואל הדם מצותי' דגופי' הוא ולא בתור שליח ב\"ד."],["47","47","ואפילו את\"ל דזה שאין דין גלות וגואל הדם בזמן הזה הוא לא רק משום ארי' הוא דרביע עלי' אלא שמופקע בעצם••, הרי מכיון שהחטא דהורג נפש הוא „משום המתפעל והוה דבר נמשך\", „החטא נמשך לעולם\" (צפע\"נ מכות ה, ב בגמ' ד\"ה וכסבוריין), נמצא כאילו נעשה מעשה החטא אז, ובמילא ישנו החיוב גלות ומצות גואל הדם כו'."],["48","48","מכות פ\"ב מ\"ז (יא, ב). ושם יב, א. וראה בכללות גדר גואל הדם (ובהבא לקמן) אנצק' תלמודית שם. וש\"נ."],["49","49","ולהעיר ממאירי מכות (יא, ב) שכתב במחלוקת ריה\"ג ור\"ע אי הוי מצוה או רשות „ולא סוף דבר כשיצא אלא אף מעיקרו\"."],["50","50","ראה צפע\"נ מהד\"ת טז, א-ב. לב, ד (נעתק בכללי התומ\"צ בערכו). •) אבל ראה שו\"ת צפע\"נ (וורשא) סרט\"ו בסופו: ועי' בספרי פ' מסעי דמבואר דערי מקלט נוהג גם בזה\"ז ע\"ש אף שאין מקדשין ולא מזבח ולא סנהדרין, צפע\"נ למכות ו, א (גליון ד\"ה מנה\"מ) — נעתק בצפע\"נ עה\"ת מסעי לה, כט. וראה קצוה\"ח סימן ב. ••) ראה אנציקלופדי' תלמודית ערך גלות וערך גואל הדם בסופו. וש\"נ. ועי' הלשון בראשונים שהובאו שם. וראה רמ\"א חו\"מ ר\"ס תכ\"ה."]]],[1300241128,"רוצח (פונקט ווי אַן אַנדער מענטש)51 —\nנאָר אַז אויך לדעה זו איז מלכת־חילה, נאָך פאַר דער ניסה לערי מקלט איז שוין דאָ אַ מצוה (ע\"ד ווי שיטת הספרי<sup data-n=\"52\">52</sup> אויפן גואל הדם צו נוקם זיין מיתת קרובו; נאָר היות אַז תורה גיט דעם הורג נפש בשגגה די הגנה פון עיר מקלט, ווערט מיט דעם באוארנט, אַז כל זמן דער רוצח איז נאָך ניט אַנגע־קומען לעיר מקלטו53 איז ארי' הוא דרביע עלי' אויף דעם גואל הדם און ער קען ניט מקיים זיין מצותו54].\nו. מען דאַרף נאָך אָבער פאַרשטיין (בשיטת הרמב\"ם):\nדער רמב\"ם פסק'נט דאָך55 אַז ס'איז נאָר אַ רשות ביד גואל הדם להרגו (ווען יצא חוץ לתחומה בזדון). ולכאורה, אפילו לדעתו אַז לעת\"ל איז עולם כמנהגו נוהג, איז אין הכי נמי אַז עס קען זיין אַ הורג בשגגה, ווי קומט אָבער דעמאָלט — יחם לבבו (ובמילא) אַ מציאות פון גואל הדם. וויבאַלד (דער רמב\"ם אַליין פסק'נט)56 אַז „באותו הזמן לא יהי' שם רעב ולא מלחמה ולא קנאה ותחרות כו' ולא יהי' עסק כל העולם אלא לדעת את ה' בלבד\": אין אַ מצב, פון „לא קנאה ותחרות\" און זיין עסוק „לדעת את ה' בלבד\", איז ווי קען זיין אַז איינער זאָל הרג'נען אַ צווייטן וואָס „לו אין משפט מות\", נאָר מצד דעם וואָס „יחם לבבו\".\nאון מען קען ניט ענטפערן אַז דאָס וואָס מ'וועט לעת\"ל דאַרפן האַבן ערי מקלט וועט זיין — ניט אויף צו מציל זיין דעם הורג נפש בשגגה פון דעם גואל הדם, נאָר — אלס אַ כפרה פאַר דעם חטא (ווייל ענינן פון ערי מקלט איז ניט בלויז הגנה והצלה, נאָר אויך כפרה57 על החטא) — ווארום דער פסוק זאָגט בפירוש „ולא ישפך דם גו'\", אַז זיי וועלן זיין (אויך לעת\"ל) צוליב הגנה והצלה.\nנוסף לזה: אויב די ערי מקלט לעת\"ל וועלן זיין נאָר צוליב דעם אַז אַ הורג נפש בשגגה זאָל האָבן אַ כפרה, איז דאָך ניטאָ דער חשש אַז „כי ירבה הדרך והכהו נפש\", איז ניטאָ קיין הכרח אויף ערי מקלט אין ארץ קני קניזי וקדמוני דוקא — עס זיינען דאָך שוין דאָ ערי מקלט אין אי\"ע ועבר הירדן58;\nמשא\"כ ווען דער טעם איז (אויך ובעיקר) בכדי צו מציל זיין דעם הורג נפש בשגגה פון דעם גואל הדם, אַזוי",[["51","51","ראה מנ\"ח מצוה תי."],["52","52","ובספרי דבי רב לספרי כאן, דמאן דאית לי' (בש\"ס) מצוה אפי' בתחלה מצוה (כבספרי כאן) אלא שנשאר בצ\"ע. ובביאור הרי\"פ פערלא לסהמ\"צ לרס\"ג מל\"ת רעד כתב בפירוש הספרי שהמצוה היא לרדפו לעיר מקלטו ולא להרגו ע\"ש. ומהספרי דבי רב משמע דמפרש גם להורגו."],["53","53","ולהעיר מצפע\"נ מכות יב, א (גליון ד\"ה רוצח שיצא) דאם לא גלה עדיין לכו\"ע פטור אם הרגו. וי\"ל ע\"פ הנ\"ל בפנים, דכשאינו בורח לערי מקלט אין לו ההגנה."],["54","54","אף שיש לפרש שדוקא לאחר שנגמר דינו בב\"ד להגלות וחל עליו החיוב להצטער צער גלות ששקול כמעט כצער מיתה (חינוך מצוה תי) הרי כשיצא מעיר מקלטו, מצוה ביד גואל הדם לקיים חיוב זה."],["55","55","הל' רוצח פ\"ה ה\"י."],["56","56","סוף הלכות מלכים."],["57","57","ראה מכות ב, ב. תוד\"ה מודי שם יא, ב. ובכ\"מ. וראה שו\"ת צפע\"נ שם. צפע\"נ למכות (י, א) ד\"ה הללו. וש\"נ."],["58","58","כי אין מקור לחדש דערי מקלט קולטים ומכפרים רק על הורג נפש שבאותה מדינה."]]],[1300241129,"מובן פארוואס מ'דארף האבן די הוספת הערים אין ארץ קני קניזי וקדמוני, היות אז ביי „לנוס שמה\" איז נוגע עס זאל ניט זיין „ירבה הדרך\".\nז. וי\"ל הביאור בזה:\nדי הלכה פון גואל הדם מיט אלע פרטים איז ניט אן ענין פון „דברה תורה . . כנגד יצה\"ר\"59 וועלכער וועט מסית זיין און מאכן אז „יחם לבבו\" דערפאר האט תורה בלית ברירה געגעבן רשות (אדער אַ ציווי) צו הרג'נען דעם רוצח\n— ווארום אויב אַ הורג נפש בשגגה איז ניט חייב מיתה, איז ווי איז שייך צו זאגן אז דער גואל הדם האט רשות אים צו הרג'נען, וכש\"כ — אז עס איז אַ מצוה אויפן גואל הדם? —\nנאר דאס איז אַ הנהגה מעיקרא ע\"פ תורה או מצוה60: עס זיינען דא אופנים ווען די תורה הייסט ב\"ד זאל אויספירן דעם חיוב מיתה — ווען עס זיינען דא עדים והתראה; פאראן אופנים ווען עס קומט מיתה בידי שמים; און ביי אַ הורג נפש בשגגה, ווייבאלד אז דורך אים איז געהרג'עט געווארן אַ נפש מישראל61, האט תורה דאס איבערגעגעבן62 צו דעם\nוואס „ראוי ליורשו\"63 (אַ שייכות צו עם — ובמילא איז (ע\"פ תורה) „יחם לבבו\"<sup data-n=\"64\">64</sup> צו הרג'נען דעם רוצח65, אויף אראפנעמען דעם „ורצח גואל הדם את הרוצח גו' ולא תקחו כופר לנוס גו' ולא תחניפו את הארץ גו' ולארץ לא יכופר לדם גו' כ\"א בדם שופכו\"66 [ובפרשתנו „והי' עליך דמים\"67] — די מעשה החטא.\nאון דעריבער איז אויך לדעת הרמב\"ם וואס פסק'נט אז „רשות לגואל הדם להרגו\", דארף מען האבן ערי מקלט לעת\"ל אויף אנטלויפן פון דעם גואל הדם, ווייבאלד אז דער גואל הדם איז אן ענין ע\"פ תורה68 (ניט (נאר) מצד אַ טבע (יצה\"ר) געפיל פון נקמה) — יחם לבבו,\nובמילא איז דאס אויך בהזמן (לעת\"ל)69 ווען עס איז „לא קנאה ותחרות\" נאר „עסק כל העולם לדעת את ה' בלבד\".",[["59","59","כמו באשת יפת תואר (קדושין כא, סע\"ב. פרש\"י תצא כא, יא)."],["60","60","וכדמוכח מהא דלכו\"ע במזיד, „מצוה ביד גואל הדם להרוג את הרוצח\" (רמב\"ם הל' רוצח פ\"א ה\"ב). ואם אין לו גואל הדם ב\"ד מעמידים לו גואל הדם (סנהדרין מה, ב. וראה רמב\"ם וכס\"מ שם). וראה הוספות הרמב\"ן לספר המצות מ\"ע יג. ובכ\"מ."],["61","61","ראה צפע\"נ מכות י, ב בתחלתו מגליון."],["62","62","ואף שהרשות לגואל הדם היא רק כשיצא חוץ לתחום (כברמב\"ם שבהערה 55), משא\"כ לפנ\"ז גואל הדם (רק) פטור (רמב\"ם שם פ\"ה ה\"ט) — י\"ל שאי\"ז שאז נתחדש כל הגדר דרשות משא\"כ לפני שבא לעיר מקלטו, כ\"א שלפנ\"ז ארי' הוא דרביע עלי', וכנ\"ל בפנים סוס\"ה לדעת המ\"ד מצוה."],["63","63","רמב\"ם שם פ\"ב ה\"ב — לענין גואל הדם בהורג במזיד."],["64","64","ע\"ד החילוק באופן האבלות ע\"פ תורה בהתאם למדת הקירוב משפחתי."],["65","65","ע\"ד העניין ד„קנאין פוגעין בו\" (סנהדרין פב, א), דלכמה דיעות הוי רשות (רא\"ש ויד רמ\"ה שם. וראה גם רמ\"א חו\"מ סתכ\"ה ס\"ד). וכן השוים במל\"מ הל' רוצח ספ\"א. וי\"ל שבגואל הדם הוי יתירה מזה, כי קנאי הבא לימלך אין מורין לו (סנהדרין שם), משא\"כ בגואל הדם (שירי קרבן לירושלמי סנהדרין ספ\"ט)."],["66","66","מסעי לה, כז. לב-לג."],["67","67","ראה מו\"ק ה, א."],["68","68","ראה תפארת ישראל למשנה מכות שם דהוי מצוה קטנה דכל כה\"ג לגבי מצוה ממש רשות קרי לה."],["69","69","וזה שאפי\"ל מציאות שאדם יהרג לעת\"ל — אף שע\"פ גמ' הנ\"ל ס\"א הוא לפי שהרג במזיד (בלי עדים) — צריך לומר (גם לדעת הרמב\"ם) שהוא לפי שהרג במזיד בזמן הזה (ראה אלשיך שם)."]]],[1300241130,"ח. ויהי רצון אז דורך דער עבודה פון ערי מקלט בזמן הזה ברוחניות — לימוד התורה, וואס „דברי תורה . . קולטין\"70,\nובפרט אין דעם זמן וואס איז געגעבן געווארן אלס א „מקלט\" — דער חודש אלול וואס ר\"ת שלו איז71 „אנה לידו ושמתי לך\", „לרמוז כי הקב\"ה בחסדו אנה וזמן חדש אלול לכל מי שחטא בתוך השנה שישוב אז בתשובה ויקב־לוהו\"72,\nזאל מען זוכה זיין בקרוב צו דעם „ירחיב ה\"א את גבולך\" וכפשוטו, און עס וועט זיין דער „ויספת לך עוד שלש ערים\" — די הוספת ג' ערי מקלט,\nאון אויך ברוחניות, די התגלות טעמי תורה לע\"ל73 דורך משיח צדקנו74 במהרה בימינו ממש.\n(משיחות מוצש\"ק פ' בלק ופנחס תשל\"ח)",[["70","70","מכות י, א. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי ע' א'תיד</a> ואילך."],["71","71","ל\"ת ושער הפסוקים להאריז\"ל פ' משפטים. פרי עץ חיים שער ר\"ה פ\"א."],["72","72","שה\"פ שם. ועד\"ז בל\"ת ופע\"ח שם."],["73","73","אוה\"ת שם ס\"ע א'תטו."],["74","74","רש\"י שה\"ש א, ב. — וראה ד\"ה אל תצר את מואב — לאדהאמ\"צ."]]],[1300241131,"<h3>שופטים ג</h3>\nא. אויפן פסוק¹ „כי האדם עץ השדה” פרעגט די גמרא² „וכי אדם עץ [ה]שדה הוא” און פארענטפערט: „אלא משום דכתיב כי ממנו תאכל ואותו לא תכרות, וכתיב³ אותו תשחית וכרת, הא כיצד אם תלמיד חכם הגון הוא ממנו תאכל (למוד הימנו, רש״י) ואותו לא תכרות, ואם לאו אותו תשחית (סור מעליו, רש״י) וכרת”.\nדארף מען פארשטיין: פון דעם וואס די גמרא פרעגט „וכי אדם עץ שדה הוא” איז מוכח, אז די גמרא נעמט אן, אז דאס וואס דער פסוק פארגלייכט אן אדם צו „עץ השדה” איז ניט בלויז ווייל עץ השדה דינט ווי א משל⁴ פון וועלכן מ׳קען פארשטיין איינע (אדער עט־לעכע) פון די מעלות ותכונות של האדם\n[ווייל אויב דער פסוק מיינט צו פאר־גלייכן זיי נאר אין געוויסע פרטים, האט דאך דעמאלט קיין ארט ניט צו פרעגן⁵ „וכי אדם עץ שדה הוא” — וויבאלד עס\nזיינען דא כמה פרטים אין וועלכע אן אדם קען יע פארגליכן ווערן צו „עץ השדה”⁶],\nנאר אז אן אדם איז עץ השדה⁷: אז „עץ” דריקט אויס (ניט בלויז טיילווייז אדער טפל׳דיקע פרטים פון דעם אדם, נאר) די גאנצע זאך פון אדם — „האדם עץ השדה”.\n[ווייל אז דאס איז אויך פארשטאנדיק פון דעם וואס מען זאגט ניט קיין תחנון בחמשה עשר בשבט⁸ — ר״ה לאילנות⁹: ס׳איז א מנהג ישראל צו עסן פירות האילן ביום זה¹⁰ וכו׳ (און מען פאר־בינדט עס¹¹ מיטן פסוק „כי האדם עץ השדה”).\nאויב עץ השדה איז ניט מער ווי א משל אויף אדם — איז עס דאך ניט קיין טעם מספיק אז דער אדם זאל „פראווען” דעם עץ׳ס ר״ה¹². איז דער־פון מובן, אז „האדם עץ השדה” מיינט, כנ״ל, אז דער אדם איז עץ השדה, און דערפאר האט דער ר״ה פון דעם עץ א שייכות צו אדם].",[["1","1","פרשתנו כ, יט."],["2","2","תענית ז, א."],["3","3","שם, כ."],["4","4","עפ״ז יומתק זה שהש״ס לא נקט כאן לשון „למה נמשל אדם לעץ השדה” (וכיו״ב) — כלשון הש״ס כמ״פ תיכף לאח״ז בנוגע לדברי תורה."],["5","5","ברש״י (ועד״ז ברבינו גרשום) תענית שם: אלא מקיש אדם לעץ השדה מה עץ השדה כו׳. ומשמע שזוהי הכוונה בתירוץ הגמ׳, שהאדם אינו עץ השדה ורק נמשלו זל״ז. וצ״ע מהי הקס״ד מלכתחילה שהאדם הוי עץ השדה? *) בחדא״ג מהרש״א (ועד״ז בפי׳ הרי״ף לע״י) שם מפרש דקושית הש״ס היא שלפי פשוטו של מקרא (שמא האדם עץ שדה — רש״י עה״פ) הול״ל „כי עץ השדה אדם”. ע״ש. אבל מפשטות ל׳ הגמרא „וכי אדם עץ השדה הוא” משמע, שהקושיא היא איך אפ״ל שהאדם הוא עץ השדה, כבפנים."],["6","6","ראה אבות פ״ג מי״ז. ועוד. וראה בפרטיות ס׳ הליקוטים (צ״צ) ע׳ עץ, ס׳ הערכים־חב״ד ח״א ע׳ אדם סי״א, וש״נ."],["7","7","וראה רש״י שלח יג, כ."],["8","8","שו״ע או״ח סקל״א ס״ו."],["9","9","משנה ריש ר״ה (כדעת ב״ה)."],["10","10","מג״א שם סקט״ז. השלמה לשו״ע אדה״ז (לבעהמ״ס דברי נחמי׳) שם ס״ח. ויש מנהגים לומר ליקוטים מתנ״ך וזהר כו׳ (נדפסו בס׳ פרי עץ הדר — וויניציאה, תפ״ח. וכמ״ש לאח״ז). — ולא ראיתי במדינותינו נוהגים כן."],["11","11","ראה לקוטי מהרי״ח ח״ג מנהגי שבט (בטעם שלובשים בגדי יו״ט). ועוד."],["12","12","ופשוט שאינו דומה להעמדת אילנות בביהכנ״ס בעצרת (שו״ע אדה״ז או״ח סתצ״ד סט״ו)."]]],[1300241132,"איז ניט פארשטאנדיק:\nא) ווי אזוי ווערט פארענטפערט די שאלת הגמרא „וכי אדם עץ שדה הוא” דורך דעם תירוץ „אם ת״ח הגון הוא ממנו תאכל כו׳”, וויבאלד אז אויך דער ענין איז, לכאורה, ניט מער ווי (א) א משל ונמשל פון עץ השדה, (ב) און נאכ־מער — נאר אין איין פרט — בלייבט דאך די שאלה במקומה: „וכי” — צי דען קען מען צוליב דעם אנרופן דעם אדם „עץ השדה”?\nב) ווי פאסט בכלל צו מתאר זיין מעלת האדם — מין המדבר — דער־מיט וואס ער איז „עץ השדה”, ער האט די תכונות פון „צומח”?\nאמת טאקע אז ביי אן אדם איז פאראן אויך דער ענין ה„צומח” (ובפרט די צמיחה פון זיינע שערות וצפרניו כו׳), אבער: (א) אויב אזוי, איז דאך ביי אן אדם פאראן א גרעסערע מעלה — דער ענין פון „חי”¹³. (ב) ועיקר: ניט אין דעם באשטייט מעלת האדם (מדבר) — היינט ווי איז מתאים צו זאגן „האדם עץ השדה”?\nב. די מעלה מיוחדת — אויס־געטיילקייט פון מין הצומח (לגבי מדבר חי) באשטייט אין דעם וואס ער פאר־דעקט ניט „באהאלט” זיין אמת׳ן חיות, ער איז שטענדיק מחובר (דורך זיינע שרשים) צו זיין מקור, צום כח הצומח שבאדמה וואס מאכט אים „לעבן” און וואקסן. ווען מען רייסט אפ א צומח פון דער אדמה, ווערט עס אויס צומח.\nביי חי און מדבר געפינט מען ניט, אז זיי זאלן מוזן זיין צוגעבונדן לשרשם ומקורם: זיי זיינען ניט מחובר להאד־\nמה¹⁴, פון וואנעט עס איז געווען די התהוות (אויך) פון מין החי והמדבר — „הכל הי׳ מן העפר”¹⁵; נאך דער התהוות (לידה) פון יעדער חי ומדבר — איז ער ניט באהאפטן צו זיין שרש ומקור (וואס האט אים געבוירן): אויך דער מזון פון חי ומדבר איז אין אן אופן, אז זיי דארפן ניט שטיין אין א חיבור מיט דעם מקור פון דעם מזון.\nמשא״כ ביי צומח, וואס איז שטענדיק מחובר צו דעם כח הצומח שבאדמה.\n— מען געפינט עד״ז ביי דגים, אז זיי מוזן זיך שטענדיק געפינען אין מים, מקור חיותם, און ווען זיי זיינען פור־שים מן הים מיד הם מתים¹⁶; ואדרבא — מער פון צומח: זיי בלייבן מיט זייער גאנצער מציאות אין זייער מקור — אין וואסער:\nאבער — היא הנותנת: אין דעם גופא איז דער חידוש ביי צומח לגבי דגים, אז אויך ווען זיי וואקסן על פני האדמה, חוץ למקורם, ביז בוימער וואס וואקסן העכער פון ג׳ טפחים, עשר טפחים, ביז גאר הויך — בלייבן זיי תמיד מחובר מיט זייערע שרשים וואס זיינען בארץ, ועל ידם — מיטן כח הצומח שבאדמה.\nועוד — בא דגים איז דער דג פרטי כלל ניט פארבונדן מיט זיין מקור חיות פרטי, ער גייט אריבער ואפילו מנהר לים (ולהיפך), משא״כ בא צומח.\nג. אין דעם גופא איז פאראן א יתרון מעלה אין עץ השדה — אילנות — לגבי אנדערע צמחים¹⁷:",[["13","13","כידוע שהאדם כלול מדצח״ם (ראה ס׳ הערכים שם סעיף ז, וש״נ)."],["14","14","להעיר מאדני השדה (כלאים פ״ח, מ״ה). וראה ע״ח שמ״ב בתחלתו שהוא ממוצע „בין הצומח והחי”."],["15","15","קהלת ג, כ. ב״ר פי״ב, יא."],["16","16","ראה ע״ז ג, סע״ב. וראה ברכות סא, ב."],["17","17","נוסף לזה דשלימות גדלות הצמיחה היא באילנות כמש״נ (מ״א ה, יג) וידבר על העצים מן"]]],[1300241133,"אנדערע צמחים¹⁸ — ווי תבואה, פרי האדמה וכיו״ב — בלייבן ניט בקיומם (אלס צומח המחובר לארץ) משנה לשנה, זיי פארלירן זייער מציאות: דא־קעגן אילנות זיינען מוציא פירות משנה לשנה — זיי קענען סובל זיין אלערליי שינויים, קיץ וחורף כו׳, און עס ווערט ניט נפסק זייער קיום.\nוואס דאס ווייזט אויף א גאר שטארקן חיבור מיטן מקור חיותם, וואס גיט אין זיי אריין א תוקף גדול אויף ניט נתפעל ווערן פון שינויי הזמן, בלייבן בקיומם און אויך וואקסן משנה לשנה.\nד. דער אדם איז אן „עולם קטן”¹⁹. פונקט ווי דער „עולם גדול” איז איינ־געטיילט אין פיר סוגים: דומם, צומח, חי און מדבר, אזוי זיינען אויך ביים אדם אויך ברוחניותו, פאראן אט די פיר סוגים²⁰.\nוכידוע²¹, אז די מדות פון דעם מענטשן זיינען צומח שבנפש האדם, ווייל אין די מדות איז פאראן דער ענין הצמיחה מקטנות לגדלות.\nאין כח השכל איז פאראן ניט בלויז דער ענין פון צמיחה מקטנות לגדלות, נאר אויך דער ענין פון „חי”²², וואס דריקט זיך אויס אין תנועה ושינוי ממקום למקום, ווי א בעל חי וואס באוועגט זיך ממקום למקום. און עד״ז איז שכל ניט („מחובר”) מוגדר און אונ־\nטערגעווארפן צו איין טבע, שכל איז ענינו צו פארשטיין א זאך (ניט ווי אים וילט זיך, נאר) ווי די זאך איז, אזוי אז ער איז הולך און משנה מקום אמאל צו חסד און אמאל צו גבורה — ביי איין ענין איז מסקנת השכל אז עס דארף זיין חסד, און ביי א צווייטן ענין — גבורה. וכיו״ב.\nמשא״כ מדות (מצד עצמן) זיינען מוגדר אין זייער טבע — מדת החסד בלייבט (מצ״ע) אין קו החסד, און אזוי מדת הגבורה — אין קו הגבורה; עס איז נאר וואס זיי „וואקסן” מקטנות לגדלות.\nה. כשם ווי צומח אין „עולם גדול” איז אויסגעטיילט, כנ״ל, מיט דער מעלה וואס ער איז שטענדיק מחובר לשרשו, איז עד״ז ביי בחינת צומח שבאדם — מדות — אז זיי האבן א מעלה איבער שכל וואס דוקא זיי זיינען (שטענדיק) מחובר צו שרשם — פנימיות נפש האדם.\nאון דאס איז אויך דער טעם²³ פאר־וואס מדות (רגש הלב) האבן אין זיך, ווי מיר זעען, א תוקף גדול, ביז אז עס איז גאר שווער אז זיי זאלן משנה „מקום” זיין, זיך בייטן (ע״ד ווי גערעדט פריער בנוגע צו אילנות): אן איש החסד בטבעו, איז גאר שווער אז ער זאל נשתנה ווערן צו זיין אן איש הגבורה (ועד״ז להיפך).\n[ולהעיר אז אעפ״כ מעגליך איז עס — חאטש עס איז ניט רגיל, ניט ע״ד הרוב: א מענטש קען זיך מתגבר זיין מיט זיין שכל אויף טבע מדותיו, ביז אז ער קען זיי משנה זיין פון רע לטוב²⁴ — אזוי ווי",[["","","הארז גר האזוב (תו״ח בראשית ד״ה וייצר פי״ז)."],["18","18","ראה הדיעות בזה — ברכות מ, סע״א ואילך ובמפרשים שם. טאו״ח, רמ״א ושו״ע אדה״ז ר״ס רג. סדר ברכת הנהנין לאדה״ז פ״ו ה״ו."],["19","19","תנחומא פקודי ג. וראה אדר״נ פל״א, ג. ועוד."],["20","20","נסמן לעיל הערה 13."],["21","21","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו״א ד, א</a>. ובכ״מ (נסמנו בס׳ הערכים שם)."],["22","22","ראה בכ״ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061166\" data-slug=\"likkutei-sichot\" data-id=\"1300061166\">לקו״ש ח״ו ע׳ 155</a> (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061124\" data-slug=\"likkutei-sichot\" data-id=\"1300061124\">וראה שם ע׳ 113</a>)."],["23","23","עיין בזה ד״ה והארץ היתה במאמרי אדה״ז — תקס״ה (כרך א) בתחלתו (ושם כרך ב בתחלתו). תו״ח בראשית יא, ד ואילך. המשך תער״ב ח״א פרק רנא־ב. ד״ה להבין ענין טענת המרגלים תשט״ו."],["24","24","בכמה מקומות מבואר שע״י גדלות המוחין מתהפכות המדות מטבען (ראה תו״א הוספות קז,"]]],[1300241134,"בא אילנות איז דורך דער טירחא יתירה פון עוקר זיין זיי ממקומם און נוטע זיין במקום אחר — זיינען זיי צומח במקום החדש און אמאל — בעסער און ביתר שאת ווי אין דעם ערשטן ארט²⁵].\nאון דאס גופא איז אויך דער טעם פארוואס שכל ווערט ניט מוגדר אין טבע האדם (ווי מיר זעען, אז א מענטש קען פארשטיין ביז צו תופס זיין²⁶ אן ענין וואס איז היפך טבעו) — ווייל דער שכל („חי”) שבאדם איז בגלוי ניט אזוי מחובר צו שרשו בנפש²⁷ (פונקט ווי „חי” אין דעם „עולם גדול”, וועלכער האט ניט דעם חיבור (תמידי) לשרשו).\nו. דערמיט וועט מען פארשטיין וואס דער פסוק זאגט „כי האדם עץ השדה” — די זאך פון „אדם” איז „עץ השדה” (כנ״ל סעיף א) — ווייל דוקא אין די מדות²⁸, בחי׳ „צומח” שבו, קומט ארויס בגלוי (זייער שרש ומקור ווי ער איז ב)פנימיות הנפש.\nוי״ל אז דערפאר איז עיקר עבודת\nהאדם (ניט אזוי אין ענין השכל, נאר בעיקר) אין בירור וזיכוך המדות²⁹, ווייל תיקון המדות רירט אן דעם פנימיות הנפש; און דעריבער דערגרייכט א אדם צו זיין שלימות דוקא דורך דער עבודה, ביז אז אויך די שלימות פון שכל האדם („וידעת”³⁰) ווערט אויפגעטאן דורך זיין פועל זיין אויף די מדות האדם („והשבות אל לבבך”³⁰).\nאון דאס איז³¹ וואס די גמרא איז מסביר, אז דער ענין פון „האדם עץ השדה” גיט זיך ארויס אין דעם וואס „אם ת״ח הגון הוא ממנו תאכל”: דער פירוש פון „הגון” איז, אז ביי דעם ת״ח איז פאראן ניט נאר מעלת השכל (לימוד), נאר אז זיין שכל באווירקט זיינע מדות, וואס דאס ברענגט אים צו פירן זיך אין אן אופן „הגון”.\nאון דוקא פון אזא ת״ח „תאכל” — פון אים צו לערנען און מקבל זיין, ווייל „האדם עץ השדה”: ווען איז מען אן „אדם” בשלימותו (פון וועמען מען קען לער־נען) — ווען מ׳איז אן „עץ השדה”, אז בחינת הצומח שבאדם, מדות שלו, איז כדבעי³² למהוי.\nז. כשם ווי דאס איז ביי יעדער יחיד בפרט, עד״ז איז עס בנוגע צו כללות עם ישראל:",[["","","סע״ד ואילך. דרמ״צ פד, א. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158100090\" data-slug=\"or-hatorah-hb\" data-id=\"8158100090\">אוה״ת משפטים ע׳ א׳קלד</a>. ד״ה ביום השמע״צ תרס״ה. המשך תער״ב ח״ג ע׳ א׳רלא ואילך (ושם, שהוא דוקא מצד גדלות אבא, ע״ש)). ולהעיר ג״כ מהפתגם שכל ענין החסידות הוא לשנות טבע מדותיו (ראה כתר ש״ט ס״י כד. לקו״ד ח״א נו, א. וראה סה״מ קונטרסים ח״ב שכא, ב). וראה המשך תער״ב (ח״א) פרק רנח בסופו, שגם בחי׳ חכמה „פועל (רק) חלישות בהמדות ומ״מ אין זה שמשתנים המדות לגמרי בעצם מהותם”."],["25","25","וכמחז״ל בגפן (שמו״ר רפמ״ד) „כשבעלי׳ מבקשין שתשביח כו׳ עוקרין אותה ממקומה ושותלין אותה במקום אחר והיא משבחת”. — ולהעיר ג״כ מב״ר רפט״ו. זח״ב קסז, ב (נת׳ באוה״ת בראשית מה, ב ואילך)."],["26","26","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ״ה</a>."],["27","27","וראה המשך תער״ב ח״א שם — גם בנוגע לבחי׳ חכמה: דהחכ׳ היא שבא העצמות בכח שהוא חוץ להעצמות והמדות הן התגלות העצמות."],["28","28","וראה המשך תער״ב ח״ג (ע׳ א׳רכא): והאדם בכלל הוא בחי׳ המדות וכמו כי האדם עץ השדה."],["29","29","ראה ד״ה אל תצר לאדהאמ״צ (מאמרי אדמוה״א דברים ח״א ע׳ ד׳ ואילך). מאמרי אדה״ז תקס״ה (ח״ב) ע׳ תתב ואילך. ועוד. וראה ד״ה אין הקב״ה בא תרפ״ה (בסה״מ קונטרסים ח״ג) פ״ב. ד״ה וישא אהרן תרצ״ד (בסה״מ קונטרסים ח״ב) פ״א. ועוד. פתגם הנ״ל הערה 24."],["30","30","ואתחנן ד, לט."],["31","31","בהבא לקמן ראה גם לקו״ש ח״ד ע׳ 1115 ואילך."],["32","32","ראה כתובות סו, רע״א והובא בנוגע לצדקה (חסד, דאזיל עם כולי יומי — לקו״ת האזינו עו, ב (פע״ח ש׳ הה״ס פ״א. מאו״א אות יו״ד, ח. ועוד). ובכ״מ)."]]],[1300241135,"אלע אידן שטאמען פון די ג׳ אבות אברהם יצחק ויעקב, און דאס אין אן אופן אז זיי זיינען שטענדיק פארבונדן ומחובר מיט די אבות. און ווי רש״י זאגט אויפן פסוק³³ „כי מראש צורים אראנו” — „אני מסתכל בראשיתם ובתחילת שרשיהם³⁴ ואני רואה אותם מיוסדים וחזקים כו׳ על ידי אבות ואמהות”.\nאין וואס דריקט זיך אויס דער פאר־בונד פון יעדן איד מיט די ג׳ אבות? — ניט (אזוי) אין דעם ענין השכל, נאר דוקא אין דעם ענין המדות. כידוע³⁵ אז די ג׳ אבות זיינען כנגד די ג׳ מדות אהבה יראה ורחמים (כללות כל המ־דות³⁶), און זיי האבן מוריש געווען לבניהם אחריהם עד עולם אט די מדות, אזוי אז בחי׳ האבות זיינען פאראן „תמיד . . בכל זמן בכל אדם”.\nוואס דער טעם דערויף איז: דער ענין הירושה איז פארבונדן מיטן עצם פון מוריש און יורש³⁷. און דעריבער, דאס וואס די אבות האבן איבערגעגעבן לבניהם אחריהם אין אן אופן פון ירושה, איז ניט (אזוי) פארבונדן מיט זייער מדריגה אין שכל והשגת אלקות (לדוגמא: מדריגת אברהם — שכל הנעלם מכל רעיון³⁸) — ווייל שכל האט בגלוי ניט אין זיך (כ״כ) דעם חיבור מיט דעם עצם ופנימיות וואס גיט זיך איבער בירושה; נאר דאס איז פארבונדן מיט זייער עבודה אין מדות — אהבה יראה ורחמים, וויבאלד אז די טבע המדות שלהם איז פארבונדן מיט פנימיות הנפש.\nח. איינע פון די הוראות וואס מען דארף ארויסנעמען בפשטות פון דעם ענין:\nדער מקור החיות פון א אידן איז תורה, „כי הם חיינו”. אבער דער סדר החיים פון רוב בני אדם איז אויסגע־שטעלט געווארן (ע״פ תורה) אין אן אופן, אז „תורתם אומנתם” איז מועטים הם ובכלל יושבי אהל, התיישבות באהלה של תורה — ניט ווי דגים שבים וואס געפינען זיך שטענדיק בתוך מקור חיותם³⁹ נאר זיי גייען ארויס אין וועלט און דארטן דארפן זיי דורכפירן די שליחות לעשות לו ית׳ דירה בתחתונים.\nדארף מען געדענקען, אז „האדם עץ השדה” — א איד דארף זיין שטענדיק",[["33","33","בלק כג, ט."],["34","34","ראה ישעי׳ כז, ו: הבאים ישרש יעקב גו׳."],["35","35","ראה תו״א ר״פ וארא. ד״ה וארא בסה״מ תקס״ב ע׳ קלד. ובכ״מ. ועייג״כ <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי״ח</a> ואילך."],["36","36","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ״ג</a>, <a class=\"ft-cite\" href=\"#/read/torah-or/3901370003\" data-slug=\"torah-or\" data-id=\"3901370003\">תו״א א, סע״ב</a>. סה״מ תקס״ב שם. אוה״ת בהעלותך ע׳ שמא. ויקרא (כרך ג) ע׳ תתסב. ובכ״מ. ומבואר גם בענין חדר ר״ת חסד דין רחמים (מאו״א בערכו (ח, ז) ביי״נ. לקו״ת ויקרא ב, סע״ד. שלח מד, א. בלק עא, ב. ס׳ הליקוטים (צ״צ) בערכו, וש״נ). *) בתניא שם: ושאר המדות כולן הן ענפי היראה והאהבה״ — רק חו״ג (וכן הוא בכל ס׳ התניא (ח״א)). ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200148\" data-slug=\"or-hatorah-hb\" data-id=\"8159200148\">אוה״ת ויקרא</a> שבפנים ההערה: דנה״י הם ענפיהן של חג״ת . . כמ״ש בלקו״א ח״א פ״ג וז״ל ושאר המדות הן ענפי היראה והאהבה כו׳, אבל שם נחית רק לבאר דיש עיקר וענפים במדות. (ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא פמ״ו</a> (<a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">סה, סע״ב</a>): רמ״ח אברין . . נחלקין לשלש בחי׳ ימין שמאל ואמצע שהן חסד דין רחמים תרין דרועין וגופא וכו׳. ועד״ז בכ״מ — אבל במקומות אלה (עכ״פ ברובם) הכוונה (בעיקר) לג׳ קווין (אלא שבכל קו — כבכמה ענינים — יש: ענינו, שייכותו ללמעלה, שייכותו ללמטה))."],["37","37","ראה צפע״נ (שו״ת דווינסק ח״א סקי״ח. ועוד) שהיורש הוא מציאות המוריש."],["38","38","תו״א ר״פ לך. — וי״ל יתרה מזו דאפילו כפי שהם חב״ד (<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490042\" data-slug=\"or-hatorah-hb\" data-id=\"8316490042\">אוה״ת לך (כרך ד) תרצ, ב</a>. וראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670318\" data-slug=\"torat-chaim\" data-id=\"2300670318\">תו״ח לך פד, ד</a> ואילך, שהאבות הן בג׳ קווין חח״ן בג״ה דת״י) היו בשרשם ולא עיקר ענינם. ואכ״מ."],["39","39","ראה לעיל הערה 16."]]],[1300241136,"צוגעבונדן צום מקור חיותו: די חיות אין תורה ומצות וואס ער האט באקומען זייענדיק באהלה של תורה איידער ס׳איז געקומען די צייט פון „לרדוף”⁴⁰ — דארף ביי אים בלייבן שטענדיק, ביז אז ער פילט אז ער איז איצט צוגעבונדן צו יענעם זמן. ד.ה. ביי אים דארף ניט זיין דער הרגש, אז ער האט אמאל געלערנט אין א חדר און ישיבה און געדענקט איצט וואס ער האט אמאל געפילט און געטאן — נאר ער פילט איצט דעם פארבונד מיט יענעם זמן, ביז\nער פילט אז דאס איז זיין חיות איצט און אין דעם באשטייט זיין מציאות.\nולאידך דארפן די יושבי אהל וויסן, אז עס איז ניט גענוג לימוד התורה אליין, ווייל מיט שכל אליין, וואס אין אים זיי־נען דא שינויים, איז ניטא קיין פאר־זיכערונג אז אויך נאכדעם ווי מען גייט ארויס פון אהלה של תורה זאל מען בלייבן צוגעבונדן כדבעי צו תורה.\nדוקא ווען דער לימוד איז אין אן אופן פון „והשבות אל לבבך” ווערט תורה איינגעקריצט אין דעם מענטשן אין אן אופן פון „לא שניתי”: און אין וואס פאר א מצב ער זאל זיך נאר געפינען בלייבט ער צוגעבונדן צו מקור מים חיים — תורה ומצוות.\n(משיחות מוצאי ש״פ וארא תשל״ט, ש״פ בשלח תש״מ)",[["40","40","בן עשרים (אבות ספ״ה) — ראה הל׳ ת״ת לאדה״ז רפ״ג (ובקו״א שם)."]]],[1300241137,"<h3>שופטים ד</h3>\nא. ביים סוף פון דער היינטיקער סדרה, אין דער פרשה פון עגלה ערופה, שטייט אין פסוקי „והורידו זקני העיר ההיא את העגלה אל נחל איתן אשר לא יעבד בו ולא יזרע וערפו שם העגלה בנחל“<sup data-n=\"1\">1</sup>. איז רש״י מפרש אויפן ווארט „וערפו“: קוצץ ערפה בקופיץ. אמר הקב״ה תבא עגלה בת שנתה שלא עשתה פירות ותערף במקום שאינו עושה פירות לכפר על הריגתו של זה שלא הניחוהו לעשות פירות.\nדער מקור פון פירוש רש״י זה איז אין גמרא<sup data-n=\"2\">2</sup>. ס׳איז אבער ידוע אז ענינו פון פירוש רש״י על התורה איז, ווי רש״י אליין זאגט: אני לא באתי אלא לפשוטו של מקרא<sup data-n=\"3\">3</sup>; און ער ברענגט מדרשי חז״ל נאר דאמאלס ווען ס׳איז מוכרח לפשוטו של מקרא<sup data-n=\"4\">4</sup>.\nאיז ניט מובן בנדו״ד: צוליב וואס דארף רש״י צוגעבן דעם ענין פון „אמר הקב״ה תבא עגלה כו׳“, וואס איז א כעין נתינת טעם אויף דעם ציווי? — מצד פשוטו של מקרא איז ניטא קיין הכרח צו זוכן טעמים אויף (פרטי ה)מצות<sup data-n=\"5\">5</sup>.\nאויך דארף מען פארשטיין: א) פאר־וואס זאגט ער דא דעם לשון „אמר הקב״ה“, וואס איז ניט רגיל בפירושו ביי אנדערע ענלעכע הסברות וביאורים<sup data-n=\"6\">6</sup>; און ס׳איז מובן בפשטות אז רש״י דארף עס ניט זאגן, ווייל אלע ענינים פון תורה איז „אמר הקב״ה“.\nאון אע״פ אז דאס איז דער לשון הגמרא<sup data-n=\"7\">7</sup> — איז אבער רש״י בפי׳ על התורה ניט אויסן צו מעתיק זיין לשון הגמרא אדער מדרש וכיו״ב, (ובפרט אז ער גיט דערביי ניט צו די ווערטער „דרשו רבותינו“ וכיו״ב): און דא איז עס נאכמער מוכח דערפון, וואס בהתחלת פירושו דא איז ער משנה פון לשון הגמרא<sup data-n=\"8\">8</sup> — טא פארוואס איז ער מעתיק די ווערטער „אמר הקב״ה“<sup data-n=\"9\">9</sup>?\nב) בכל אופן: פארוואס איז רש״י מצרף דעם ענין „אמר הקב״ה תבא עגלה כו׳“ בהמשך צו זיין פירוש אויף „וערפו“ — „קוצץ ערפה בקופיץ“?\nדער טעם „תבא עגלה כו׳“ איז ניט אויף דעם פרט פון „וערפו“, נאר אויף דעם ציווי בכללותו — פארוואס מען נעמט (בל׳ רש״י) א „עגלה בת שנתה כו׳“ און מען הרג׳ט עס „ב(נחל איתן —) מקום שאינו כו׳“ (און ווי ס׳איז מפורש",[["1","1","כא, ד."],["2","2","סוטה מה, סע״ב במשנה: עורפין אותה בקופיץ מאחוריו. ושם מו, סע״א: אמר הקב״ה כו׳ (בשינויים)."],["3","3","בראשית ג, ח. ועד״ז שם, כד. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051001\" data-slug=\"likkutei-sichot\" data-id=\"1300051001\">לקו״ש ח״ה ע׳ 1</a> ובהנסמן שם."],["4","4","ראה לקו״ש שם הערה 2."],["5","5","להעיר גם בעניננו, שרש״י אינו מפרש הטעם ע״י ד״ה „ולקחו גו׳ עגלת בקר אשר לא עבד בה אשר לא משכה בעול“."],["6","6","לדוגמא פרש״י בפרשתנו: כ, ג (ראה סוטה מב, א). אחרי יז, יא. אמור כג, כד. חקת יט, כב (אלא ששם י״ל דאינו משנה כיון שמקדים העתקתו מיסודו כו׳). תצא כא, יח."],["7","7","שם מו, סע״א."],["8","8","התחלת לשון הגמרא שם היא „מפני מה אמרה תורה הביא עגלה בנחל“. וגם המשך לשון הגמרא שונה מלשון רש״י."],["9","9","ועד״ז בפסוק כא, ח „ונכפר להם הדם“ שפרש״י „הכתוב מבשרם“, ובמשנה שם מו, רע״א „רוח הקודש מבשרתך“ (ועד״ז בספרי סוף פרשתנו „רוה״ק אומר“)."]]],[1300241138,"ומודגש אין גמרא: „מפני מה אמרה תורה הביא עגלה בנחל“) —\nרש״י האט געדארפט שטעלן די צוויי ענינים אין צוויי באזונדערע דיבור־המתחיל׳ס: מעתיק זיין דעם ווארט „וערפו“ און אים אפטייטשן — „קוצץ ערפה בקופיץ“; און דערנאך א באזונ־דער ד״ה מיט די ווערטער „וערפו שם את העגלה בנחל“ און מפרש זיין דעם טעם: „אמר הקב״ה תבא עגלה כו׳“<sup data-n=\"10\">10</sup> (אדער בריינגען דעם טעם בהתחלת פירושו אויף דעם פסוק, אין פריער־דיקן ד״ה „אל נחל איתן“ וואו ער איז מפרש „קשה שלא נעבד“<sup data-n=\"11\">11</sup>).\nב. וי״ל הביאור בזה:\nע״ד הרגיל איז ניט דרכו של רש״י (בפירושו עה״ת) צו מפרש זיין די טעמי המצות; ווען ער קומט אבער צו אזא מצוה וואס איז ניט בהתאם מיט כללי וציוויי התורה בכלל, דארט מוז רש״י זיך שטעלן און מפרש זיין דעם טעם השינוי.\nובנדו״ד: בנוגע הבאת ושחיטת בע״ח לצורך האדם געפינט מען (ביז פרשתנו) כמה סוגים: א) קרבנות וואס ענינם איז כפרה<sup data-n=\"12\">12</sup>, כמפורש אין פ׳ ויקרא און צו; ב) ענינים דאנקען פאר ברכות, אדער בריינגען ברכות<sup data-n=\"13\">13</sup>, ג) וואס זייער ענין איז צו מטהר זיין, ווי בא מצורע — „זאת תהי׳ תורת המצורע ביום טהרתו וצוה הכהן ולקח למטהר שתי צפרים חיות“<sup data-n=\"14\">14</sup>. און דער חילוק ביניהם:\nקרבנות לכפר אדער וועלכע זיינען שייך צו ברכות — ווערן געבראכט אין משכן ובית המקדש „לפני ה׳“<sup data-n=\"15\">15</sup>, „המקום אשר יבחר ה׳ אלקיכם בו לשכן שמו שם“<sup data-n=\"16\">16</sup>, וואס די הקרבה לפני ה׳ איז פועל דעם „ונרצה לו לכפר עליו“<sup data-n=\"17\">17</sup>, אדער „לפני ה׳“ — מקור הברכות.\nמשא״כ די שתי צפרים בא מצורע לטהרתו איז עשייתן „מחוץ<sup data-n=\"18\">18</sup> למחנה, חוץ לשלש מחנות (אין דעם מקום המצורע) שנשתלח שם בימי חלוטו“ — ער זאל נטהר ווערן און קענען אריינ־קומען אין מחנה, און דעמאלט ברענג־ען די קרבנות בביהמ״ק לכפרתו<sup data-n=\"19\">19</sup>.\nמען געפינט נאך צווי קרבנות וואס אויך זייער הקרבה איז ניט בביהמ״ק — שעיר המשתלח ביום הכפורים און פרה אדומה.\nשעיר המשתלח ווערט אויך אנגע־רופן חטאת (שני שעירי עזים לחטאת<sup data-n=\"20\">20</sup>), — און כאטש ער ווערט ניט נקרב ע״ג המזבח, איז אבער דער עיקר מעשה הכפרה שעל ידו<sup data-n=\"21\">21</sup>, וואס דאס איז דער „וסמך .. והתודה עליו את כל עונות בני ישראל גו׳ ונתן גו׳“<sup data-n=\"22\">22</sup>, ווערט גע־טאן „לפני ה׳“<sup data-n=\"23\">23</sup> בעזרה<sup data-n=\"24\">24</sup>; און דאס וואס",[["10","10","או לאחרי סיום פירושו בפרטי עניני עגלה ערופה."],["11","11","או בהתחלת הענין (בפסוק הקודם) ולקחו גו׳ עגלת בקר. וע״ד שפרש״י בפ׳ תצא (כא, יא) אבל אם .. סופו כו׳ — בהתחלת הפרשה."],["12","12","דגם קרבנות נדבה (ראה פרש״י ויקרא א, ב) הם „לכפר“ (שם, ד ובפרש״י)."],["13","13","קרבן תודה (צו ז, יב (פרש״י שם) ואילך). קרבן שלמים (ויקרא ג, א (פרש״י שם) ואילך). ועוד."],["14","14","ר״פ מצורע."],["15","15","ויקרא א, ג. ובכ״מ."],["16","16","ראה יב, יא. ועד״ז שם, ה. יח. ועוד."],["17","17","ויקרא שם, ד. ובכ״מ."],["18","18","מצורע יד, ג ובפרש״י."],["19","19","שם, יוד ואילך."],["20","20","אחרי טז, ה."],["21","21","שם, יוד."],["22","22","שם, כא. ובפרש״י שם, יוד."],["23","23","שם, ז. ושם, יוד."],["24","24","פרש״י לפנ״ז ויקרא א, ה. וראה ע״ד ההלכה רמב״ם פ״ח מהל׳ מעשה הקרבנות הי״א דשעיר"]]],[1300241139,"ער ווערט אוועקגעשיקט „אל ארץ גזירה“ איז די כוונה דערביי אוועקשיקן כל עונותיהם פון בנ״י (ונשא השעיר עליו את כל עונתם אל ארץ גזירה<sup data-n=\"25\">25</sup>). דאס איז אבער (ע״פ פשוטו של מקרא) ניט קיין מעשה הקרבה<sup data-n=\"26\">26</sup>, נאר הפכו.\nלאידך בא פרה אדומה, כאטש אז אויך עשייתה איז „מחוץ למחנה — חוץ לשלש מחנות“<sup data-n=\"27\">27</sup>, איז דאך אבער ענינה — הכשר והקדמה צו מאכן די מי חטאת לטהר מטומאת מת, און קענען מקריב זיין א קרבן במקדש. און דאס וואס עס ווערט אנגערופן „חטאת“, זאגט דאך רש״י<sup data-n=\"28\">28</sup> „לשון חטוי כפשוטו ולפי הלכותיו קראה הכתוב חטאת לומר שהיא כקדשים להאסר בהנאה“.\nס׳איז נאר ע״פ „מדרש אגדה“ וואס רש״י איז מעתיק<sup data-n=\"29\">29</sup> „מיסודו של ר׳ משה הדרשן“ די פרטי עניני כפרה פון פרה אדומה. ווייל אע״פ אז איר עשי׳ איז בחוץ, זיינען אבער דא אין איר ענינים מעין קרבן: זי דארף זיין בכהן, און נאכ־מער „מצותה בסגן“, „ושחט אותה לפניו“, „והזה אל נוכח פני אהל מועד“<sup data-n=\"30\">30</sup>.\nג. בפרשתנו אבער — בא עגלה ערופה זעט מען אינגאנצן א נייעם ענין: פון איין זייט ווערט געזאגט אז זי טוט אויף דעם ענין פון כפרה — „כפר לעמך ישראל גו׳ ונכפר להם הדם“<sup data-n=\"31\">31</sup>, ניט אן ענין פון טהרה מטומאה; אבער לאידך, איז אין דעם ניטא קיין דמיון ושייכות צו קרבנות — ניט אין מקום (מען ברענגט עס ניט צום ביהמ״ק (אדער אויף א מזבח וכו׳) אפילו ניט נוכח המקדש), ניט בנוגע די עושי העבודה — זי ווערט ניט געטאן דורך כהנים (דער ציווי<sup data-n=\"32\">32</sup> „ונגשו הכהנים בני לוי“ באציט זיך בפשטות צום זמן פון נאך דער עריפה „הכהנים33 אומרים כפר לעמך ישראל“)<sup data-n=\"34\">34</sup>, און ניט אין מעשה העבודה — עס איז ניטא קיין מעשה שחיטה<sup data-n=\"35\">35</sup>, זריקה וכו׳.",[["","","יו״כ ששחטן בחוץ לפני שהתודה עליהם חייב הואיל וראוין לבוא לפני ה׳ לוידוי (וראה ראב״ד שם). וראה כס״מ שם. ועוד. וראה גם פרש״י אחרי שם, כב ד״ה ופשט: וסדר .. ושלח את השעיר .. ויצא כו׳ (והוא בבגדי לבן — רמב״ם הל׳ עבודת יוה״כ פ״ד ה״ב)."],["25","25","אחרי טז, כב."],["26","26","להעיר דע״ד ההלכה ישנו לימוד מיוחד „איש להכשיר את הזר (בשעיר המשתלח) מהו דתימא כפרה כתיבא בי׳ קמ״ל“ (יומא סו, ריש ע״ב). וראה רשב״א שבועות יג, א ד״ה בירושלמי דלפי׳ הא׳ כתב „דשילוחו (של השעיר) קרי קרבן“. אבל מסיים שם (בסוף פי׳ הב׳): „ואלו לפי׳ הא׳ לא ניח׳ שאין שילוחו קרוי קרבן“."],["27","27","חקת יט, ג ובפרש״י שם."],["28","28","שם, ט."],["29","29","אחרי סיום כל הענין (שם, כב)."],["30","30","שם, ג־ד ואילך ובפרש״י."],["31","31","פרשתנו כא, ח."],["32","32","פרשתנו שם, ה."],["33","33","פרש״י שם, ז."],["34","34","ע״ד ההלכה — ראה פרש״י בגמ׳ (חולין קלג, רע״א) דמשמע דהעריפה צריכה להיות בכהן (כ״כ בצפע״נ לרמב״ם הל׳ שחיטה פ״א הי״ג. וראה צ״פ עה״ת פרשתנו כא, ג). וראה רש״ש סוטה מה, ב ד״ה ועורפין. שו״ת בית יצחק או״ח סל״ה בשולי המכתב. אבל ראה שו״ת מחזה אברהם (או״ח סקמ״ה) דכוונת רש״י רק — דהכהנים אומרים כפר כהפסוק שהובא בפרש״י. וכן יש לתרץ בכ״מ שנאמר הלשון עריפת העגלה בכהן. ושקו״ט בזה בכ״מ. ואכ״מ."],["35","35","אלא שע״ד ההלכה (תוד״ה עגלה חולין פב, א. ד״ה דחייתו יומא סד, א) עריפה זו היא שחיטה וחייב משום אותו ואת בנו (ועריפה מטהרת מידי נבילה — זבחים ע, ב), כמו בשעיר המשתלח דדחייתו לצוק זו היא שחיטתו (יומא שם)*). ועי׳ זבחים שם ד„כפרה כתיב בה כקדשים“. אבל ברמב״ם (הל׳ שחיטה פ״ב הי״ו) דרק בשוחט העגלה חייב משום אותו ואת בנו, אף שפסק (הל׳ אבות *) אבל בספר הישר לר״ת (חלק הענינים שונים סי׳ תרלב) מחלק בין שעיר המשתלח לעגלה ערופה, דבעגלה אינו חייב משום אותו ואת בנו, ושם „דדחייתו לצוק דשעיר הוי כשחיטת עולת קדשים“."]]],[1300241140,"[ווען מען וואלט געלערנט אז די פעולות ביי עגלה ערופה זיינען בלויז א סימן ואות — וע״ד ווי אנדערע מפרשים<sup data-n=\"36\">36</sup> טייטשן אז „כשם שהעגלה תמה ונקי׳ שלא עשתה שום דבר, והקרקע קרקע בתולה כך אנו נקיים מן הרציחה“, ועד״ז „ירחצו את ידיהם סימן כשם שידינו נקיות כך אנו נקיים מחלל זה“ — וואלט ניט געווען קיין (שטארקע) קשיא, פארוואס דער אויבערשטער הייסט מאכן אזא סימן.\nע״פ פשוטו של מקרא אבער איז משמע אז די אלע מעשים זיינען חלקים פון דעם מעשה הכפרה].\nאיז א שאלה לויט פשוטו של מקרא — דאס איז ניט בהתאם צו הוראות התורה ווי אזוי און וואו עס ווערט אויפ־געטאן כפרה — אז עס איז דורך הקרבת הקרבנות לה׳ ע״י כהן בביהמ״ק!\n[נאך מער: ס׳איז אן איסור וחיוב כרת אויף שחוטי חוץ, „ואל פתח אהל מועד לא הביאו להקריב קרבן לה׳ גו׳ (עס מוז זיין) אשר יביאו בנ״י את זבחיהם גו׳ לה׳ אל פתח אהל מועד אל הכהן וזבחו גו׳ לה׳ גו׳ וזרק גו׳ על מזבח ה׳“<sup data-n=\"37\">37</sup>].\nדעריבער איז רש״י מפרש: „אמר הקב״ה תבא עגלה בת שנתה כו׳ ותערף כו׳“, דא איז אן אמירה נוספת — מיוחדת פון דעם אויבערשטן, און ענין של חידוש לגבי שאר התורה — א נייער אופן פון כפרה, וואס איז ניט ווי קרבנות37*) ושאר עניני כפרה אין דער תורה. דא קומט די כפרה דורך דעם וואס די פעולה, און דער מקום, און דער קרבן, זיינען בהתאם צו די פרטים אין דער הריגה.\nעפ״ז מובן אז דאס וואס רש״י איז מפרש „אמר הקב״ה תבא עגלה כו׳“ בהמשך צו „קוצץ ערפה בקופיץ“, איז (ניט נאר ווייל דער שינוי פון עריפה (און ניט שחיטה) באווייזט אז דא איז עס ניט קיין פעולה פון כפרה ווי בא קרבנות בכלל, נאר אויך) ווייל דאס איז א פרט עיקרי וואס איז מכריח דעם פירוש פון „אמר הקב״ה כו׳“.\nד. וועט מען דאס פארשטיין בהקדם וואס פריער, אין פ׳ בא<sup data-n=\"38\">38</sup> (בא פטר חמור) איז רש״י מפרש אויף „(ואם לא תפדה) וערפתו“<sup data-n=\"39\">39</sup>: „עורפו בקופיץ מאחוריו והורגו, הוא הפסיד ממונו של כהן לפיכך יפסיד ממונו“.\nפארוואס איז רש״י דא משנה פון פירושו בפ׳ בא, וואו כאטש ער זאגט דעם טעם „הוא הפסיד כו׳“ בהמשך לפירושו (ווי דא) אויף „וערפתו“, זאגט ער ניט דערביי „אמר הקב״ה“, ווי בפר־שתנו<sup data-n=\"40\">40</sup>?\nועפ״ז הנ״ל איז דאס מובן: עריפה לגבי שחיטה — איז מיתה באופן אכזרי,",[["","","הטומאה פ״ג הי״ג) ד„עגלה ערופה שנערפה כהלכתה טהורה כפרה כתיב בה כקדשים“. ואכ״מ."],["36","36","חזקוני (וריב״א) כאן."],["37","37","אחרי יז, ד־ו. 37*) ולהעיר מפרש״י לך טו, ט: „רמז לג׳ פרים פר יום הכפורים ופר העלם דבר של צבור ועגלה ערופה“, ולכאורה בא בהמשך לסיום פרש״י לפנ״ז (שם, ז) „בזכות הקרבנות“ (וראה פרש״י מגלה לא, רע״ב ד״ה קחה לי). אבל בב״ר (פמ״ד, יד) באיזו זכות א״ל בכפרות שאני נותן לפניך. ויאמר גו׳ קחה לי עגלה משולשת הראה לו ג׳ מיני פרים כו׳ ועגלה ערופה."],["38","38","יג, יג."],["39","39","ולהעיר שמפרשו עוה״פ בפ׳ תשא לד, כ. ובשינויים קלים. ואכ״מ."],["40","40","ואף שי״ל בפשטות שבמכילתא עה״פ וכן בגמ׳ בכורות (י, ב) לא נאמר כן, משא״כ בפרשתנו שכן נאמר בסוטה, הרי רש״י מפרש פשש״מ כנ״ל. ובפרט שלשון רש״י שם אינו כהלשון במכילתא, וגם בבכורות הלשון הוא „יפסד“ (וכ״ה בפרש״י תשא שם) ולא „יפסיד“."]]],[1300241141,"„עורפו בקופיץ מאחוריו“ קומט די מיתת הבהמה דורך יסורים וצער<sup data-n=\"41\">41</sup>, משא״כ ביי שחיטה מן הצואר — ניטא קיין שבירת העצם פון צוואר וכו׳<sup data-n=\"42\">42</sup>, ווי דער בן חמש למקרא זעט.\nאון רש״י איז מסביר בא פטר חמור42*): דאס וואס תורה זאגט „אם לא תפדה וערפתו“ מיינט ניט אז דער מענטש האט א ברירה פון צוויי גלייכע מצות: „תפדה בשה“ אדער „וערפתו“<sup data-n=\"43\">43</sup>; די פעולה פון „עורפו בקופיץ מאחוריו והורגו“, איז אן עונש: היות „הוא הפסיד ממונו של כהן לפיכך יפסיד ממונו“: כדי מדגיש זיין אז דאס איז אן ענין פון הפסד, ווערט דאס געטאן אין דעם אופן פון „וערפתו“, וואס איז אן אכזריות (והפסד בחיי החמור, ובמילא מעין זה אויך בבעל החמור — ווי מ׳זעט בפועל אז א מענטשן רירט אן<sup data-n=\"44\">44</sup> דער צער פון זיינע בע״ח).\nער זאגט אבער ניט דארטן „אמר הקב״ה“ ווארום דארט איז ניטא קיין שינוי לגבי מצות דוגמתו — ס׳איז דאך ניט קיין קרבן כפרה, תודה, טהרה וכו׳.\nבפרשתנו אבער, אן ענין פון כפרה, איז כאטש אז דער פרט פון מקום וואו דאס ווערט געטאן „נחל איתן קשה שלא נעבד“<sup data-n=\"45\">45</sup>, איז ניט ווי בא כפרה שע״י הקרבנות בביהמ״ק, אבער דער פרט פון וערפתו איז — ווי ביי חטאת העוף „ומלק את ראשו ממול ערפו“<sup data-n=\"46\">46</sup>.\nדערפאר זאגט רש״י און איז מפרט (כאטש ער האט שוין מפרש געווען דעם טייטש פון עריפה פריער<sup data-n=\"47\">47</sup>) „קוצץ ערפה בקופיץ“<sup data-n=\"48\">48</sup> (און איז אויך משנה פון לשון המשנה „עורפין אותה בקופיץ מאחוריה“), צו מדגיש זיין אז דא איז ניטא קיין פעולה בדומה צו מעשה הקרבנות, ווייל אזא פעולה פון „קוצץ“ זיין דעם עורף של בהמה (וועלכע האט א שטארקן עצם הצואר, און) מיט א „קופיץ“<sup data-n=\"49\">49</sup> — „כמין סכין גדול“<sup data-n=\"50\">50</sup> — איז",[["41","41","ראה מאירי למשנה סוטה מה, ב: וחותכין בו בכח מאחוריו. טור יו״ד סי׳ שכא ס״ז ורמ״א שם לענין פטר חמור: מכהו בקופיץ בערפו כדי שימות. ולהעיר מצרור המור בפרשתנו כא, א כי זה רמז על האכזריות כו׳. (ראה הערה הבאה)."],["42","42","וראה כתובות (לז, ב) סנהדרין (נב, ב) הוקשו כל שופכי דמים לעגלה ערופה, אבל בש״ס מן הצואר ולא כבעגלה ערופה בקופיץ ומול העורף כי צ״ל ברור לו מיתה יפה. וראה יד רמ״ה סנהדרין שם ד״ה מתני׳ מצות הנהרגין. ושם: לפי שפי הקופיץ עב ואינו חד כסייף וכשהוא חותך אינו חותך בלבד אלא משבר את הבשר הסמוך למקום חתך מכאן ומכאן ואין לך מיתה מנוולת מזו אבל סייף אינו כן לפי שפיו דק וחד יתר מדאי כו׳. וראה שטמ״ק כתובות שם ד״ה ברור ואחד הפירושים שם: לפי שמצד הסימנין הוא ממהר למות. — אבל בן חמש למקרא לא למד עדיין כ״ז (וכן המובא בהערה 50 ועוד) — ולכן הובא בפנים רק מה שהוא רואה בעיניו. 42*) ראה בכ״ז לקו״ש בא תשמ״א."],["43","43","כדיעה הא׳ במכילתא בא שם. וידועה פלוגתת הרמב״ם והראב״ד בזה (הל׳ בכורים רפי״ב)."],["44","44","ראה ת״ח (כד, לב): ויפתח הגמלים גו׳ (ואחר כך) ומים לרחוץ רגליו גו׳."],["45","45","פרשתנו שם, ד ובפרש״י שם."],["46","46","ויקרא ה, ח ובפרש״י שם. ובסוטה (מו, ריש ע״ב) למדין עריפה דעגלה מחטאת העוף."],["47","47","בפ׳ בא ותשא, אף שאינה קושיא, וכמדובר כמ״פ שדרכו של רש״י לפרש עוה״פ בקיצור מה שפי׳ בספר לפניו (ובנדו״ד ה״ז ג׳ ספרים לפניו), ובפרט שתיבת „עריפה“ אינה תיבה רגילה בחומש."],["48","48","קוצץ דוקא ולא סתם חותך (בניחותא). — ועפ״ז בטלה התמי׳ שלא פרש״י מהו קופיץ אף שמפרשו בכ״מ — כי פירושה דבר הקוצץ. ולהעיר מפרש״י ד״ה נחש הנחושת (חוקת כא, ט). „וא״ת אין קוצץ בלא כ״ת צד״י י״ל כו׳“ — בפרש״י ארוכה (ויחי מט, יט). ולהוסיף אשר „קופיץ קופץ (ולכן) קוצץ, משא״כ סכין שחותך בהולכה (הליכה) והבאה, כי ענינה אך ורק „שמכשרת בשר לאכילה“ (פרש״י וירא כב, ו)."],["49","49","דרק מיעוטן משתמשין לשחיטה (רש״י פסחים ע, א ד״ה קופיץ. וראה תוד״ה השוחט בכורות כד, ב)."],["50","50","ל׳ רש״י במשנה סוטה מה, ב ובפסחים שם. ביצה כח, רע״א. בכורות י, ב ד״ה בקופיץ. ועד״ז"]]],[1300241142,"בהיפך פון שחיטה, וואס דאס מאכט נאך שטארקער די שאלה: ווי איז דאס מכפר — בשעת ס׳איז ניט בדומה, און נאכ־מער ס׳איז בהיפך, פון הקרבת הקר־בנות?\nאון דעריבער איז רש״י אויך ממשיך ומדגיש „אמר הקב״ה תבוא עגלה כו׳“, דא איז געזאגט געווארן א נייער אופן פון כפרה: „תבוא עגלה בת שנתה שלא עשתה פירות ותערף במקום שאינו עושה פירות“, אז אלע ענינים דא זיינען דורכאויס באופן של שלילה — א) עגלה בת שנתה שלא עשתה פירות, ב) תערף, ג) במקום שאינו עושה פירות, ווייל עס קומט „לכפר על הריגתו של זה שלא הניחוהו לעשות פירות“.\nה. פון די ענינים מופלאים בפרש״י:\nע״פ הנ״ל י״ל אז רש״י און דער רמב״ם לשיטתייהו אזלי אין דעם פירוש פון „נחל איתן“.\nרש״י איז מפרש (כנ״ל) „נחל איתן — קשה שלא נעבד“, דער רמב״ם<sup data-n=\"51\">51</sup> אבער טייטשט „נחל ששוטף בחזקה“ און דאס וואס עס שטייט „אשר לא יעבד בו ולא יזרע“ איז אן איסור אויף להבא<sup data-n=\"52\">52</sup>.\nוי״ל אז די מחלוקת איז ניט נאר אין פירוש הכתוב, נאר ס׳איז פארבונדן אויך מיט א פלוגתא אין דעם עצם גדר הכפרה פון „עגלה ערופה“:\nדער רמב״ם איז מסביר אין מורה־נבוכים<sup data-n=\"53\">53</sup> דעם טעם אויף בריינגען אן עגלה ערופה ופרטי עניני׳, אז דאס זיינען תחבולות וועלכע גיבן א מעגלעכקייט אז דער רוצח זאל נתגלה ווערן, ובלשונו<sup data-n=\"54\">54</sup>:\nוא״א על הרוב עם החקירה ויציאת הזקנים והעומדים ולקיחת העגלה שלא ירבו דברי בני אדם, ואולי בפרסום הענין יודע ההורג, און ער איז מסיים: וחזק זה הענין בהיות המקום אשר תערף בו העגלה לא יעבד בו ולא יזרע לעולם שבעל הארץ יעשה כל תחבולה ויחקור עד שיודע ההורג כדי שלא תערף העגלה ולא תאסר ארצו עליו לעולם<sup data-n=\"55\">55</sup>.\nדער רמב״ן<sup data-n=\"56\">56</sup> זאגט (בנוגע צו דעם פרט פון „נחל איתן“), אז „לפי דעתי יש",[["","","במאירי סוטה שם. ובפיה״מ סוטה שם „הוא סכין הגדול והרחב“*). ובפרש״י ביצה לא, סע״א „סתם קופיץ הוא סכין של קצבים דומה לקרדומות שלנו“. ביד רמה סנהדרין שם: סכין גדול רחב כארכו ויש בו כובד. ובפרש״י פסחים (מאירי) ויד רמה שם דהוא לחיתוך בשר ולשבירת עצמות, וביד רמה שם „ופעמים שמבקעין בו עצים כדכתבן כו׳“ — ביצה לא, סע״א. וראה גמ׳ שם ע״ב. פרש״י ביצה הנ״ל ופיה״מ להרמב״ם במשנה שם."],["51","51","הל׳ רוצח פ״ט ה״ב."],["52","52","הל׳ רוצח פ״י ה״ט. וכ״ה בחזקוני עה״פ. וראה בארוכה תוי״ט לסוטה שם. ובמפרשי המשניות *) וליתא בפיה״מ תרגום קאפח. והש״ס סוטה שם. וש״נ. וראה מיני תרגומא פרשתנו כאן. מלאכת הקודש. ועוד."],["53","53","ח״ג פ״מ — הובא גם ברמב״ן ובבחיי כאן (פסוק א). וראה גם חינוך מצוה תק״ל. ובארוכה אברבנאל כאן. וראה כס״מ לרמב״ם שם ה״י דהביא טעם הנ״ל להלכה, ע״ש."],["54","54","מו״נ שם לפנינו (ובתרגום קאפח — בשינויים קצת)."],["55","55","כ״ה במו״נ שם לפנינו (ובתרגום קאפח — בשינויים קצת). אבל ברמב״ן (ובחיי) הובא בארוכה ולכן הקשה עליו. וכבר תירץ בספר הזכרון להריטב״א שנוסחא משובשת נזדמנה לו לרבינו ז״ל (הרמב״ן) — אולי מהעתקת אל־חריזי — ולשון המורה עברי הוא כבפנים כמו שהעתיק ר׳ שמואל תבון. ועי׳ בהמשך דבריו מה שמקשה כו׳ ומפרש בדעת הרמב״ם. וראה גם ריטב״א למכות כב, ב ד״ה ופרכי. חינוך מצוה תקלא. ובהנסמן לעיל הערה 52."],["56","56","עה״ת כאן. *) ראה ע״ד שם הספר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181381\" data-slug=\"likkutei-sichot\" data-id=\"1300181381\">לקו״ש חי״ח ע׳ 372</a> בשוה״ג להערה 14."]]],[1300241143,"בו טעם כענין הקרבנות הנעשים בחוץ<sup data-n=\"57\">57</sup> שעיר המשתלח ופרה אדומה, ולפיכך מנו חכמים עגלה ערופה מכלל החוקים“.\nאון אזוי געפינען מיר אין ספר היד להרמב״ם (בסוף הל׳ מעילה) אז די אלע דריי — עגלה ערופה ופרה אדומה ושעיר המשתלח — ווערן דארט גע־רעכנט צוזאמען<sup data-n=\"58\">58</sup> אלס חוקים.\nמשא״כ לפי דער דרשה וואס רש״י ברענגט אראפ, „אמר הקב״ה תבוא עגלה כו׳ שלא עשתה פירות ותערף כו׳ לכפר כו׳“, קומט אויס לכאורה אז ס׳איז ניט בסוג החוקים.\nו. ויש לומר, אז דאס זיינען דריי אופנים ווי מען קען לערנען דעם גדר הכפרה פון עגלה ערופה<sup data-n=\"59\">59</sup>: מצד דעם פועל, מצד דער פעולה בכללותה, מצד דעם נפעל (ומקומו):\nא) לפי הרמב״ם במו״נ איז די כפרה מצד הפועל: בשעת די זקני העיר הקרובים אל החלל טוען די אלע פעולות בכדי צו מגלה זיין דעם רוצח, איז דאס גופא אויף זיי מכפר, עס נעמט אראפ פון זיי<sup data-n=\"60\">60</sup> דעם עון<sup data-n=\"61\">61</sup>.\n[נאך ועוד: די כפרה באשטייט ניט נאר אין דעם וואס זיי טוען אלע מיני פעולות אז ס׳זאל נתגלה ווערן דער רוצח, נאר אויך ווייל מיט דעם זיינען זיי מפרסם בפרסום גדול אז „חפץ הזקנים ואנשי העיר“ איז געפינען דעם רוצח „לנקום ממנו נקמת הנרצח“<sup data-n=\"62\">62</sup> — און דאס גופא פארהיט און ווארנט אויס דעם ענין פון רציחה, ובמילא איז דאס גופא מכפר].\nב) לויטן רמב״ן (וי״ל אז אזוי איז עס אויך לדעת הרמב״ם בספר היד דארט), איז דאס מצד דער פעולה, וע״ד ענין הקרבנות (וואס אויך אויף דעם זאגט דער רמב״ם דארטן „וכל הקרבנות כולן מכלל החוקים הן“), אז די פעולה וכפרה פון קרבנות איז מצד דער מעשה ההקרבה, עד״ז איז ביי עגלה ערופה, וואס „כפרה נאמר בה כקדשים“<sup data-n=\"63\">63</sup>, ד. ה.",[["57","57","ובחזקוני כאן: אשר לא יעבד ולא יזרע דוגמת אל ארץ גזרה כי לשניהם פירוש אחד."],["58","58","כמפורש — אף שמסיים (כדלקמן בפנים) שכל הקרבנות כולן מכלל החוקים הן."],["59","59","פשטות הכתובים בפרשתנו (כא, ז ואילך) ובמפרשי התורה משמע שהכפרה בעיקר על יושבי העיר ולא על הרוצח. וראה פרש״י שם, ח: הכתוב מבשרם שמשעשו כן יכופר להם העון. וראה ראב״ע שם, ז הובא ברמב״ן. וראה הלשון בבחיי ובאברבנאל שם. וראה ערכין טז, א ובפרש״י שם ד״ה קשיא. ובכ״מ. וראה מאמרי אדה״ז (פרשיות ח״ב ע׳ תתכח). סהמ״צ להצ״צ (מצות עגלה ערופה): העגלה שאינה באה לכפר על החוטא כי אינו מתכפר בזה כלל כו׳ רק שהיא באה להסיר הקטרוגים מכל ישראל שהרי כל ישראל עריבים זה לזה ועי״ז העגלה נפטרים מן החטא המוטל על כללות ישראל מחמת הערבות. ולהעיר ממשנה סוטה מז, סע״א „כיפרה ספיקה והלכה לה“ ובפרש״י שם. ובגמ׳ שם מז, ב ועד״ז בכתובות לז, ב מנין כו׳ שאין פוטרת אותו כו׳ (וראה פרש״י כתובות שם ד״ה דשאני). רמב״ם הל׳ רוצח פ״י ה״ח. וראה פרש״י ויקרא ה, יח. פענח רזא ס״פ ויקרא."],["60","60","ראה משכיל לדוד לפרש״י פרשתנו כא, ח."],["61","61","לכאורה זוהי הכוונה במו״נ אף שלא פי׳ דזה ענין הכפרה. אבל פשיטא דאין כוונתו להוציא הכתוב מפשוטו, דעגלה ערופה באה לכפר. אבל להעיר מבחיי כאן: כפר לעמך ישראל כפר לשון גילוי הוא שיגלה להם הרוצח דאם היו ישראל שבאותו הדור זכאין היתה העגלה הולכת עד בית הרוצח והורגים אותו שם. זהו ונכפר להם הדם כלומר יתגלה להם הרוצח. ואם לא היו זכאין וכו׳ עורפין אותה שם והכהנים אומרים כפר לשון כפרה כו׳."],["62","62","חינוך שם ומסיים ע״ז „וכן מצאתי להרמב״ם ז״ל“."],["63","63","זבחים ע, ב וש״נ. רמב״ם הל׳ רוצח פ״י ה״ב. שם ה״ה. הל׳ אבות הטומאה פ״ג הי״ג. ועוד. ועיין גם מיני תרגומא שם ובפסוק ח. ובכ״מ."]]],[1300241144,"פונקט ווי ביי אלע קרבנות איז עס גזירת המלך, אז יעדער קרבן איז מכפר אויף אן עבירה (עבירות) מסוימת, עד״ז זיינען דא פעולות (הקרבנות) מסוימות שבחוץ<sup data-n=\"64\">64</sup>, שעיר המשתלח, פרה אדומה ועגלה ערופה, וואס גזירת המלך<sup data-n=\"65\">65</sup> איז, אז (אויך) די מעשה זאל מכפר זיין<sup data-n=\"66\">66</sup>.\nג) לדעת רש״י „תבוא עגלה בת שנתה כו׳“ קומט אויס א דריטער אופן — אז די כפרה איז ניט מצד דעם פועל אדער דער פעולה בכלל<sup data-n=\"67\">67</sup> — בדוגמת הקר־בנות, נאר מצד דעם נפעל (הנרצח, ועגלה הנערפת) — „תבוא עגלה בת שנתה שלא עשתה פירות ותערף במקום שאינו עושה פירות“, ווייל די כפרה איז ניט (נאר) אויף מעשה רציחה (פון רוצח) נאר במיוחד אויף דעם „אופן“ המיוחד שבנרצח (נפעל), „לכפר על הריגתו של זה שלא הניחוהו לעשות פירות“<sup data-n=\"68\">68</sup>.\nאון דעריבער זאגט מען דא „אמר הקב״ה“, ס׳איז געזאגט געווארן א נייעם אופן פון כפרה ניט ווי בא שאר אופני כפרה דקדשים<sup data-n=\"69\">69</sup> (אויך ניט הנעשים בחוץ, שעיר המשתלח ופרה אדומה)<sup data-n=\"70\">70</sup>.\nז. עפ״ז יומתק נאכמער דער חילוק אין פירוש „נחל איתן“: לטעם הרמב״ם במו״נ איז מובן וואס ער טייטשט „אל נחל איתן ששוטף בחזקה“, ניט קרקע קשה שלא נעבד (נאר — אז מכאן ואילך איז דא א לאו שלא יעבד בו), ווייל — לויט זיין טעם — פועלן אז דער בעל השדה „יעשה כל תחבולה ויחקור עד שיודע ההורג“ — איז אויב עס וואלט",[["64","64","וראה תוד״ה ותהא (חולין כג, ב): נקט פרה ועגלה ששניהם ענין אחד דשניהם קדשים הנעשים בחוץ ודמו אהדדי כו׳. ולהעיר מצפע״נ להל׳ שחיטה שם."],["65","65","ראה מדרש לקח טוב פרשתנו עה״פ, שלאחרי שמפרט טעמים פרטיים בעגלה ערופה שמביאים להתגלות הרוצח, מסיים „ועוד כי גזירת מלך היתה לכפר על ישראל“."],["66","66","במאמרי אדה״ז ובסהמ״צ שם: ולכך שניהם שעיר המשתלח ועגלה ערופה לא היו קריבים ע״ג המזבח כי אינן שייכים שם כלל מאחר שאינם באים לכפרה. אבל בסהמ״צ שם בסיום המאמר: ונכפר להם לישראל. וראה הלשון בהגהה בסהמ״צ שם. אבל להעיר מחידושי אגדות מהרש״א סוטה שם שמצרף הטעם דגמ׳ אמר הקב״ה תבוא עגלה כו׳ מ״ש הרמב״ם במו״נ."],["67","67","ראה הערה הקודמת."],["68","68","וי״ל שזהו הנפק״מ גם להטעמים דלעיל על מה בא לכפר: לטעם הרמב״ם במו״נ העיקר הוא גילוי הרוצח, בא לכפר בעיקר ע״ז שיש רוצח השייך לעיר זו כו׳ — הפועל (וראה אברבנאל שם. ועוד); לאופן הב׳ ה״ז בא לכפר על פעולת ומעשה ההריגה; ולטעם דהגמ׳ ורש״י — על זה שלא הניחוהו לעשות פירות — הנפעל."],["69","69","וכן יש לפרש הלשון במדרש לקח טוב שם „ועוד כי גזירת מלך היתה לכפר על ישראל“, שהכוונה בזה (לא שזהו חק, וכדעת הרמב״ם בספר היד דהוי מכלל החוקים, והיפך מש״כ לפנ״ז „מפני מה אמרה תורה לערוף עגלה במקום כו׳“ שמסביר טעם ואופן איך שמביא לגילוי הרוצח, שהרי לפנ״ז גזירת המלך במיוחד בעגלה, כי אם) — שנאמר כאן ענין חדש בגדר הכפרה. ואכ״מ."],["70","70","ע״פ הנ״ל אולי יש לבאר גם פלוגתת הרמב״ם ורש״י (בפי׳ עה״ת): להרמב״ם (הל׳ רוצח רפ״ט) אפילו נמצא בצד עיר זו שהדבר ידוע בודאי שהיא הקרובה מצוה למדוד, ולרש״י שפי׳ (כא, ב) „לכל צד לידע איזו קרובה“ מפרש הרא״ם דבמקום שאין ספק א״צ שם מדידה (וראה גו״א שם. פנים יפות שם). לטעם הרמב״ם שבמו״נ פשוט כי הוא חלק מהפרסום שיגלו הרוצח, ועד״ז להרמב״ם בספר היד (והרמב״ן) כיון שהכפרה היא מצד עצם המעשה י״ל דגם המדידה הוי חלק מהכשר מעשה הכפרה (וע״ד כמה פרטים בקרבנות (אבל ראה צפע״נ הל׳ שחיטה שם דרק משעת שחיטה ועריפה יש עליו גדר מכשיר ומכפר)). או בפשטות כיון דהוי מכלל החוקים מובן שאין הטעם משנה ומצוה למדוד (וראה צ״פ השלמה יא, א. מהדו״ת כא, ב). משא״כ לדעת רש״י שענינו — ענין של טעם — מובן שהוא רק בשביל לידע, ואם יודעים א״צ למדוד [אבל ראה מל״מ ברמב״ם שם שמפרש כהרא״ם שא״צ למדוד לשאר עיירות, אבל מן הקרובה צריך למדוד. וראה חי׳ חת״ס לב״ב כג, ב ד״ה נחזור]. ואכ״מ."]]],[1300241145,"געמיינט קרקע, דארף דאס זיין אדרבא א שדה טובה וואס איז ראוי לזריעה ביותר<sup data-n=\"71\">71</sup>, וואס דאן וועט עס מער אנ־רירן דעם בעל השדה און ער וועט זיך מער משתדל זיין צו געפינען דעם רוצח „שלא תאסר ארצו לעולם“71*); דערפאר לערנט דער רמב״ם אז „נחל איתן“ מיינט ניט קרקע, נאר א נחל של מים<sup data-n=\"72\">72</sup> „ששוטף בחזקה“.\nעד״ז איז לדעת הרמב״ם (בספרו היד): ווייבאלד דאס איז א כפרה בגדר וסוג הקרבנות, איז מסתבר אז דער ארט פון דער עריפה דארף ניט זיין (בדוקא) א קרקע קשה שלא נעבד, נאר פארקערט — וואס מער נבחר, א מקום משובח<sup data-n=\"73\">73</sup>.\nלויט רש״י אבער, ווייבאלד אז דא איז נשתנה ונתחדש „אמר הקב״ה“ — ס׳איז נתחדש געווארן א נייער סוג פון כפרה, כנ״ל — איז מסתבר אז אזוי ווי די עגלה איז א „שלא עשתה פירות“, און די פעולה איז „עריפה“ (עניני שלילה), דארף אויך דער מקום זיין פון שלילה, אזא „שאינו עושה פירות“, „איתן, קשה שלא נעבד“; אז ניט נאר מכאן ולהבא דארף עס זיין אזא ארט שאינו עושה פירות, נאר בעיקר — בהווה בשעת העריפה מוז עס זיין אן „איתן קשה שלא נעבד“ — „אינו עושה פירות“.\nח. התורה היא נצחית. איז מובן, אז די הוראה פון פרשת עגלה ערופה איז דא בכל הזמנים ובכל המקומות צו אלע אידן [ובמיוחד אין זמן הגלות, וואס האט א שייכות צום ענין פון שפיכת דמים, ווארום ברוחניות איז מען דורך יעדן חטא, במעשה דבור או מחשבה, גורם דעם ענין פון „שפיכת דם וחיות אדם דקדושה באדם דקליפה“73*)] — און דאס איז א הוראה נפלאה:\nמען רעדט וועגן „ימצא חלל באדמה גו׳ נופל בשדה“<sup data-n=\"74\">74</sup>, וואס אין דעם פאל קען מען טענה׳ן: וויבאלד אז אין מיתה בלא חטא74*), איז דאך זיכער אז דאס איז מאת ה׳, וע״ד מארז״ל<sup data-n=\"75\">75</sup> בנוגע לחוטא בשוגג (אויפן פסוק<sup data-n=\"76\">76</sup> והאלקים אנה לידו); איז דער מכה איש א רוצח און אים קומט אן עונש גדול, וויבאלד אבער אז „לא נודע מי הכהו“ — ובפרט לפי הפירוש (בגמרא ו)בפרש״י כנ״ל, אז די עגלה ערופה קומט בעיקר „על הריגתו של זה שלא הניחוהו לעשות פירות“ און ער האט ניט געהאט דעם מגני ומצלי<sup data-n=\"77\">77</sup> פון תומ״צ77*), איז דאך",[["71","71","וראה גם רד״ק בספר השרשים שלו ע׳ אית (הובא בבחיי כאן) שפירש „מקום דשן ושמן .. כי לפיכך יהיו נזהרים ונשמרים כו׳ שלא ימצא שם חלל“. עיי״ש. 71*) כקושיית הריטב״א בס׳ הזכרון שם (לגירסתנו במו״נ. ועד״ז קושיית הרמב״ן שם לפי גירסתו במו״נ — ראה לעיל הערה 55)."],["72","72","ופרט זה אינו שייך לטעמו במו״נ שם. וראה עד״ז בס׳ הזכרון שם."],["73","73","אבל מהמשך דברי הרמב״ן שם מובן, שלפי טעמו — שהוא „כענין הקרבנות הנעשים בחוץ“ — אין סברא „שיעשה בשדה טוב ראוי לזריעה“ (ל׳ הרמב״ן בקושייתו על המו״נ). ולכאורה הדיוק ברמב״ן הוא „קרבנות הנעשים בחוץ שעיר המשתלח“ — ראה חזקוני (שהובא לעיל הערה 57) „אשר לא יעבד ולא יזרע דוגמא אל ארץ גזרה“. משא״כ להרמב״ם בס׳ היד שכותב רק שעגלה ערופה מן החוקים בכלל (ולא הזכיר דוקא קרבנות הנעשים בחוץ) משמע, שהוא כמו גדר החוק דכל הקרבנות, שהוא מצד עצם פעולה וכפרה דהקרבנות, ובמילא מסתבר שמקומו צ״ל מקום נבחר, כבפנים. 73*) <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380362\" data-slug=\"likkutei-torah\" data-id=\"4001380362\">לקו״ת במדבר יג, ג</a>. ובכ״מ."],["74","74","פרשתנו כא, א. 74*) שבת נה, סע״א. ויחי נג, ב."],["75","75","מכות י, ב. פרש״י עה״ת (משפטים כא, יג)."],["76","76","משפטים שם."],["77","77","ראה סוטה כא, א. 77*) ראה שם מו, סע״א: מאי פירות אילימא פרי׳"]]],[1300241146,"בנוגע דעם ניזק כבר נגזר עליו מן השמים<sup data-n=\"78\">78</sup> — קען מען טראכטן, אז מען האט צו דעם קיין שייכות ניט און מען דארף זיך דערמיט ניט פארנעמען.\nועד״ז ברוחניות: בשעת מען טרעפט א אידן במעמד ומצב ירוד — „נופל (און וואו —) בשדה“, ער האט א שייכות צו „עשו .. איש שדה“<sup data-n=\"79\">79</sup>, היפך פון דער שטאט, מקום ישוב אדם — „ושכנתי“ פון דעם אדם העליון שעל הכסא<sup data-n=\"80\">80</sup>, אן ארט און סביבה פון תומ״צ —\nקען מען מאכן א חשבון: וועמענס שולדיק איז עס וואס דער איד געפינט זיך אין אזא מצב? — ער האט זיך גע־דארפט געפינען ניט בשדה נאר אין א מקום מושב ועיר, אין א סביבה פון תורה וירא״ש כו׳. ובמילא, דארפן די אידן וואס געפינען זיך בעיר, אין א סביבה פון אידן שומרי תומ״צ, פון זקנים וב״ד, ניט פארנעמען זיך מיט אים.\nאויף דעם איז די הוראה פון פרשת עגלה ערופה: דאס האט א שייכות ניט נאר צו די תושבי העיר הקרובה אל החלל; נאר אויך צו די זקני העיר ההיא — צום ב״ד פון דער שטאט<sup data-n=\"81\">81</sup>, ביז דאס רירט אן דעם ב״ד הגדול, „ויצאו זקניך, מיוחדים שבזקניך, אלו סנהדרי גדולה“<sup data-n=\"82\">82</sup>.\nאון די זקני בית דין פון דער עיר דארפן מאכן זיכער ועד כדי הכרזה אז „ידינו לא שפכו את הדם הזה“<sup data-n=\"83\">83</sup>, ווי רש״י טייטשט<sup data-n=\"84\">84</sup> „לא ראינוהו ופטרנוהו בלא מזונות ובלא לוי׳ כו׳“ — אז מען האט דעם אידן געגעבן „צידה לדרך“, דעם מזון פון תורה וכמש״נ<sup data-n=\"85\">85</sup> ותורתך בתוך מעי, ועד״ז — לבושים פון מצות<sup data-n=\"86\">86</sup> — וועלכע באשיצן פון „קעלט“ און פון קשת החרב, „לחם ולבוש“ וועלכע וועלן אים באגלייטן אין דעם שדה עשו — חושך הגלות, אין דעם מעמד ומצב פון „שדה“ וואו ער איז געגאנגען.\nאון נאכמער זאגט מען, אז דאס איז פארבונדן אויך מיט די סנהדרי גדולה שבלשכת הגזית. דלכאורה: וואס פאר א שייכות האבן זיי מיט דעם „חלל“ וואס מ׳האט געפונען — ניט בסמיכות צו ירושלים<sup data-n=\"87\">87</sup>, נאר צו אן אנדער ווייטער שטאט ערגעץ וואו אין ארץ ישראל<sup data-n=\"88\">88</sup>? — שטייט אבער אין תנא דבי אליהו",[["","","ורבי׳ אלא מעתה אזקן ואסריס ה״נ דלא ערפינן אלא מצות. ורש״י כאן סתם „פירות“ ולא פירש (אף שנוגע להלכה) כי מפרש פשש״מ, ואינו ספר הלכות [ואולי י״ל שמובן הוא ע״פ פרש״י ר״פ נח „שעיקר תולדותיהם של צדיקים מעשים טובים“ אף שהמדובר שם בצדיקים הר״ז בנוגע לפרט ד„עיקר תולדותיהם .. מע״ט, אבל בשאר כל אדם גם מצות (שמחויב בהם) הם בכלל תולדותיו — פירות שלו (כמדובר גם מזה שרש״י שינה מב״ר שם (פ״ל, ו): מה הן פירותיו של צדיק מצות ומע״ט)* — ראה בהנ״ל <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051030\" data-slug=\"likkutei-sichot\" data-id=\"1300051030\">לקו״ש ח״ה ע׳ 30</a> הערה 2]."],["78","78","אגה״ק סי׳ כה. וראה בארוכה אלשיך פרשתנו."],["79","79","תולדות כה, כז. וראה בארוכה אוה״ת עה״פ (קמב, ב ואילך)."],["80","80","ראה לקו״ת ראה (אלול) לב, ב. *) אבל בתנחומא נח ב: וכן תולדותיו של אדם אלו מעשיו הטובים."],["81","81","ראה מדרשי התורה להקדוש אשתרוק פרשתנו כא, ו. וראה מו״נ שם. ראב״ע כאן (פסוק ז). ועוד."],["82","82","פרשתנו כא, ב ובפרש״י (מסוטה מד, ב)."],["83","83","פרשתנו כא, ז."],["84","84","וראה סוטה מה, סע״ב במשנה (ועה״ג שם). ספרי עה״פ."],["85","85","תהלים מ, ט."],["86","86","ראה תדבא״ר פכ״ז."],["87","87","דהרי אין מודדים לירושלים שירושלים אין מביאה עגלה ערופה (רמב״ם הל׳ רוצח פ״ט ה״ד. וש״נ)."],["88","88","ראה רמב״ם שם רפ״ט."]]]]});
